/* 자동 생성 — 개념카드/굽기.py. 손으로 고치지 말 것 */
window.CARD={"행정법의 의의·법원과 일반원칙":{"묶음":[{"머리":"행정기본법의 법원칙 목록","줄":[{"t":"행정기본법에 명문으로 규정된 법원칙은 법치행정, 평등, 비례, 성실의무 및 권한남용금지, 신뢰보호, 부당결부금지의 6개다.","src":"행정기본법 제8조~제13조"},{"t":"행정의 자기구속의 원칙은 행정기본법에 명문 규정이 없다.","src":"기출 2021-26"},{"t":"행정에 관하여 다른 법률에 특별한 규정이 있는 경우를 제외하고는 행정기본법이 정하는 바에 따른다.","src":"행정기본법 제5조 제1항"},{"t":"행정에 관한 다른 법률을 제정하거나 개정하는 경우에는 행정기본법의 목적과 원칙, 기준 및 취지에 부합되도록 노력하여야 한다.","src":"행정기본법 제5조 제2항"}]},{"머리":"법치행정의 원칙(제8조)","줄":[{"t":"법치행정의 원칙: 행정작용은 법률에 위반되어서는 아니 된다(법률우위).","src":"행정기본법 제8조 | 기출 2025-27"},{"t":"법치행정의 원칙: 국민의 권리를 제한하거나 의무를 부과하는 경우와 그 밖에 국민생활에 중요한 영향을 미치는 경우에는 법률에 근거하여야 한다(법률유보).","src":"행정기본법 제8조 | 기출 2025-27"},{"t":"법률우위와 법률유보의 ‘법률’은 법령이 아니라 형식적 의미의 법률이다.","src":"행정기본법 제8조 | 기출 2025-27"},{"t":"법률유보 범위에 관한 학설: 침해유보설, 권력행위유보설, 급부행정유보설, 전부유보설, 중요사항유보설(본질성설).","src":"보충"},{"t":"중요사항유보설(본질성설): 국민의 기본권 실현에 관련된 본질적이고 중요한 사항은 국회가 법률로 스스로 정하여야 한다. 헌법재판소와 대법원이 취하는 입장이다.","src":"보충"},{"t":"의회유보: 텔레비전방송수신료 금액의 결정은 수신료에 관한 본질적으로 중요한 사항이므로 국회가 스스로 행하여야 한다. 한국방송공사법이 국회의 결정이나 관여를 배제하고 한국방송공사가 금액을 결정해 문화관광부장관의 승인을 얻도록 한 것은 법률유보원칙에 위반된다.","src":"기출 2023-26"}]},{"머리":"평등의 원칙·행정의 자기구속","줄":[{"t":"평등의 원칙: 행정청은 합리적 이유 없이 국민을 차별하여서는 아니 된다.","src":"행정기본법 제9조"},{"t":"행정의 자기구속: 재량준칙이 정한 바에 따라 되풀이 시행되어 행정관행이 형성되면, 행정기관은 그 상대방에 대한 관계에서 그 규칙에 따라야 할 자기구속을 받는다.","src":"기출 2021-28 | 기출 2024-29"},{"t":"자기구속의 법리는 평등의 원칙이나 신뢰보호의 원칙에서 도출된다. 재량준칙은 이를 통해 대외적 구속력을 가질 수 있다.","src":"기출 2022-30"},{"t":"자기구속의 법리는 행정관행이 형성된 경우 적용된다. 위법한 관행에는 자기구속이 인정되지 않는다.","src":"보충"}]},{"머리":"비례의 원칙(제10조)","줄":[{"t":"비례의 원칙 1호(적합성): 행정목적을 달성하는 데 유효하고 적절할 것.","src":"행정기본법 제10조 제1호"},{"t":"비례의 원칙 2호(필요성, 최소침해): 행정목적을 달성하는 데 필요한 최소한도에 그칠 것.","src":"행정기본법 제10조 제2호"},{"t":"비례의 원칙 3호(상당성, 협의의 비례): 행정작용으로 인한 국민의 이익 침해가 그 행정작용이 의도하는 공익보다 크지 아니할 것.","src":"행정기본법 제10조 제3호"}]},{"머리":"성실의무·권한남용금지(제11조)","줄":[{"t":"성실의무: 행정청은 법령등에 따른 의무를 성실히 수행하여야 한다.","src":"행정기본법 제11조 제1항"},{"t":"권한남용금지: 행정청은 행정권한을 남용하거나 그 권한의 범위를 넘어서는 아니 된다.","src":"행정기본법 제11조 제2항"},{"t":"행정절차법상 신의성실: 행정청은 직무를 수행할 때 신의에 따라 성실히 하여야 한다.","src":"행정절차법 제4조 제1항"}]},{"머리":"부당결부금지의 원칙(제13조)","줄":[{"t":"부당결부금지의 원칙: 행정청은 행정작용을 할 때 상대방에게 해당 행정작용과 실질적인 관련이 없는 의무를 부과해서는 아니 된다.","src":"행정기본법 제13조 | 기출 2025-26"},{"t":"부관은 해당 처분과 실질적인 관련이 있어야 한다(부당결부금지의 구체화).","src":"행정기본법 제17조 제4항 제2호"}]},{"머리":"신뢰보호의 원칙","줄":[{"t":"신뢰보호의 원칙: 행정청은 공익 또는 제3자의 이익을 현저히 해칠 우려가 있는 경우를 제외하고는 행정에 대한 국민의 정당하고 합리적인 신뢰를 보호하여야 한다.","src":"행정기본법 제12조 제1항"},{"t":"실권(失權)의 법리: 행정청은 권한 행사의 기회가 있음에도 장기간 권한을 행사하지 아니하여 국민이 그 권한이 행사되지 아니할 것으로 믿을 만한 정당한 사유가 있으면 그 권한을 행사해서는 아니 된다. 공익 또는 제3자의 이익을 현저히 해칠 우려가 있으면 예외다.","src":"행정기본법 제12조 제2항"},{"t":"행정절차법 제4조 제2항: 법령등의 해석 또는 행정청의 관행이 일반적으로 국민들에게 받아들여졌을 때에는, 공익 또는 제3자의 정당한 이익을 현저히 해칠 우려가 있는 경우를 제외하고는 새로운 해석 또는 관행에 따라 소급하여 불리하게 처리하여서는 아니 된다.","src":"행정절차법 제4조 제2항"},{"t":"신뢰보호 요건(판례): 행정청의 공적 견해표명, 상대방의 귀책사유 없는 신뢰, 신뢰에 기한 상대방의 조치(처리), 그 견해표명에 반하는 처분으로 인한 이익 침해의 4가지.","src":"보충"},{"t":"행정청이 공적 견해표명을 한 후 사정변경이 있는 경우, 특별한 사정이 없는 한 그 견해표명에 반하는 처분을 하더라도 신뢰보호원칙 위반이 아니다.","src":"기출 2022-27"},{"t":"신뢰보호원칙의 적용은 공익과 신뢰 이익을 비교형량해 판단한다. 신뢰를 보호하는 것이 공익 또는 제3자 이익을 현저히 해치면 적용되지 않는다.","src":"행정기본법 제12조 제1항"}]},{"머리":"법 적용의 기준(제14조)","줄":[{"t":"소급적용 금지(제1항): 새로운 법령등은 특별한 규정이 있는 경우를 제외하고는 그 효력 발생 전에 완성되거나 종결된 사실관계 또는 법률관계에 대해서는 적용되지 아니한다.","src":"행정기본법 제14조 제1항"},{"t":"신청에 따른 처분(제2항): 법령등에 특별한 규정이 있거나 처분 당시의 법령등을 적용하기 곤란한 특별한 사정이 있는 경우를 제외하고는 처분 당시의 법령등에 따른다. 신청 당시가 아니다.","src":"행정기본법 제14조 제2항 | 기출 2023-27 | 기출 2025-27"},{"t":"위반행위와 제재처분(제3항): 법령등에 특별한 규정이 있는 경우를 제외하고는 법령등을 위반한 행위 당시의 법령등에 따른다. 처분 당시가 아니다.","src":"행정기본법 제14조 제3항 | 기출 2023-27"},{"t":"위반행위 후 법령등이 변경되어 그 행위가 위반행위에 해당하지 아니하게 되거나 제재처분 기준이 가벼워진 경우로서 해당 법령등에 특별한 규정이 없는 경우에는 변경된 법령등을 적용한다.","src":"행정기본법 제14조 제3항 단서 | 기출 2023-27"},{"t":"처분의 효력: 처분은 권한이 있는 기관이 취소 또는 철회하거나 기간의 경과 등으로 소멸되기 전까지는 유효한 것으로 통용된다. 무효인 처분은 처음부터 효력이 발생하지 아니한다.","src":"행정기본법 제15조"}]},{"머리":"기간 계산과 법령등 시행일","줄":[{"t":"행정에 관한 기간 계산은 행정기본법 또는 다른 법령등에 특별한 규정이 있는 경우를 제외하고는 민법을 준용한다.","src":"행정기본법 제6조 제1항"},{"t":"권익을 제한하거나 의무를 부과하는 경우 그 권익 제한·의무 지속 기간의 계산: 일·주·월·연으로 정한 때 기간의 첫날을 산입한다. 기간의 말일이 토요일 또는 공휴일이어도 그 날로 만료한다. 국민에게 불리한 경우는 예외다.","src":"행정기본법 제6조 제2항"},{"t":"시행일 1호: 법령등을 공포한 날부터 시행하는 경우에는 공포한 날을 시행일로 한다.","src":"행정기본법 제7조 제1호 | 기출 2021-27"},{"t":"시행일 2호: 공포한 날부터 일정 기간이 경과한 날부터 시행하는 경우 공포한 날을 첫날에 산입하지 아니한다.","src":"행정기본법 제7조 제2호 | 기출 2021-27"},{"t":"시행일 3호: 그 기간의 말일이 토요일 또는 공휴일인 때에는 그 말일로 기간이 만료한다.","src":"행정기본법 제7조 제3호 | 기출 2021-27"},{"t":"훈령·예규·고시·지침 등은 고시·공고 등의 방법으로 발령한 날을 공포한 날로 본다.","src":"행정기본법 제7조 제1호"},{"t":"대통령령·총리령·부령은 특별한 규정이 없으면 공포한 날부터 20일이 경과함으로써 효력을 발생한다.","src":"법령 등 공포에 관한 법률 제13조"},{"t":"국민의 권리 제한 또는 의무 부과와 직접 관련되는 법률·대통령령·총리령·부령은 긴급히 시행하여야 할 특별한 사유가 있는 경우를 제외하고는 공포일부터 적어도 30일이 경과한 날부터 시행되도록 하여야 한다.","src":"법령 등 공포에 관한 법률 제13조의2"},{"t":"법률은 특별한 규정이 없으면 공포한 날부터 20일이 경과함으로써 효력을 발생한다.","src":"보충"},{"t":"행정에 관한 나이는 만(滿) 나이로 계산하고 표시한다. 출생일을 산입하여 계산하며, 만 1세에 이르지 아니한 경우에는 월수로 표시할 수 있다.","src":"보충"}]},{"머리":"행정법의 법원(法源)","줄":[{"t":"성문법원: 헌법, 법률, 조약·국제법규, 명령(대통령령·총리령·부령), 자치법규(조례·규칙), 대법원규칙·헌법재판소규칙·국회규칙·중앙선거관리위원회규칙.","src":"기출 2022-26"},{"t":"건축법시행규칙(부령), 서울특별시 성동구 조례(자치법규), 헌법재판소규칙, 대한민국헌법은 모두 행정법의 법원이다.","src":"기출 2022-26"},{"t":"불문법원: 관습법, 판례법, 조리(행정법의 일반원칙).","src":"보충"},{"t":"관습법은 법원이다. 사실인 관습은 법원이 아니다.","src":"기출 2022-26"},{"t":"관습법은 반복된 관행에 법적 확신이 더해져 법규범으로 승인된 것이다.","src":"보충"},{"t":"행정법의 법원 중 헌법은 최고법이고, 법률 > 법규명령(대통령령 > 총리령·부령) 순의 단계를 이룬다. 자치법규는 조례 > 규칙 순이다.","src":"보충"}]}],"함정":[{"x":"공적 견해표명은 묵시적으로 할 수 없다.","o":"공적 견해표명은 명시적으로뿐 아니라 묵시적으로도 할 수 있다.","src":"기출 2022-27 | 보충"},{"x":"신뢰보호의 대상은 특정 개인에 대한 행정작용에 한정되며, 법률에 대한 신뢰는 신뢰 보호의 대상이 되지 않는다.","o":"신뢰보호의 대상은 행정작용에 한정되지 않고 법률에 대한 신뢰도 신뢰보호의 대상이 된다.","src":"기출 2022-27 | 보충"},{"x":"귀책사유의 유무는 상대방을 기준으로 판단하며 상대방으로부터 신청행위를 위임받은 수임인 등 관계자는 고려하지 않는다.","o":"귀책사유의 유무는 상대방뿐 아니라 상대방으로부터 신청행위를 위임받은 수임인 등 관계자도 고려해 판단한다.","src":"기출 2022-27 | 보충"},{"x":"단순히 착오로 어떠한 처분을 계속하다가 처분청이 추후 오류를 발견하여 합리적인 방법으로 변경할 경우 신뢰보호 원칙에 위배된다.","o":"착오로 처분을 계속하다가 처분청이 오류를 발견해 합리적인 방법으로 변경하는 것은 신뢰보호 원칙에 위배되지 않는다.","src":"기출 2022-27"},{"x":"대통령령은 특별한 규정이 없으면 공포한 날부터 10일이 경과함으로써 효력을 발생한다.","o":"대통령령은 특별한 규정이 없으면 공포한 날부터 20일이 경과함으로써 효력을 발생한다.","src":"기출 2021-27 | 법령 등 공포에 관한 법률 제13조"},{"x":"행정의 자기구속의 원칙은 행정기본법에 명문으로 규정되어 있다.","o":"행정의 자기구속의 원칙은 행정기본법에 규정되어 있지 않다.","src":"기출 2021-26"},{"x":"법령 위반행위에 대한 제재처분은 처분 당시의 법령등에 따른다.","o":"법령등을 위반한 행위 당시의 법령등에 따른다. 신청에 따른 처분이 처분 당시 법령에 따른다.","src":"기출 2023-27 | 행정기본법 제14조"},{"x":"사실인 관습도 행정법의 법원에 해당한다.","o":"사실인 관습은 행정법의 법원에 해당하지 않는다.","src":"기출 2022-26"}]},"행정법관계와 사인의 공법행위":{"묶음":[{"머리":"공법관계와 사법관계의 구별(판례)","줄":[{"t":"행정재산의 사용허가 신청에 대한 거부를 다투는 소송은 공법관계(항고소송)다.","src":"기출 2024-27"},{"t":"서울시립무용단 단원의 해촉에 관한 소송은 공법관계(공법상 당사자소송)다.","src":"기출 2024-27"},{"t":"공익사업으로 이주하게 된 주거용 건축물 세입자의 주거이전비 보상을 둘러싼 소송은 공법관계(공법상 당사자소송)다.","src":"기출 2024-27"},{"t":"주민등록 전입신고와 그 수리 여부에 관한 소송은 공법관계(항고소송)다.","src":"기출 2024-27"},{"t":"한국마사회 기수의 면허취소를 다투는 소송은 공법관계가 아니다. 사법관계로서 민사소송으로 다툰다.","src":"기출 2024-27"},{"t":"공법·사법 구별 기준(학설): 이익설, 주체설, 성질설, 신주체설(귀속설), 복수기준설. 어느 하나로 정해지지 않으므로 법규의 취지·성질을 종합해 판단한다.","src":"보충"},{"t":"국유재산 중 행정재산의 사용허가는 행정처분이다. 일반재산의 대부계약(사법상 계약)은 사법관계다.","src":"보충"}]},{"머리":"공권과 반사적 이익","줄":[{"t":"개인적 공권의 성립요건: 강행법규에 의한 의무 부과, 사익보호성(법률상 이익), 청구(의사)력.","src":"보충"},{"t":"반사적 이익: 법규가 공익만을 목적으로 하여 간접적·사실상 얻는 이익으로, 침해되어도 소송으로 다툴 법률상 이익이 아니다.","src":"보충"},{"t":"무하자재량행사청구권: 재량행위에서 하자 없는 재량 행사를 요구할 수 있는 권리다. 특정 처분을 요구하는 권리가 아니다.","src":"보충"},{"t":"행정개입청구권: 사인이 행정청에 제3자에 대한 행정권 발동을 요구할 수 있는 권리다. 재량이 영(0)으로 수축되는 경우 인정된다.","src":"보충"}]},{"머리":"사인의 공법행위: 신고","줄":[{"t":"수리를 요하지 않는 신고(자기완결적 신고): 요건을 갖춘 신고서가 접수기관에 도달된 때 신고의무가 이행된다.","src":"행정절차법 제40조 제2항"},{"t":"행정절차법 제40조 제2항 요건: 신고서의 기재사항에 흠이 없을 것, 필요한 구비서류가 첨부되어 있을 것, 그 밖에 법령등에 규정된 형식상의 요건에 적합할 것.","src":"행정절차법 제40조 제2항"},{"t":"행정청은 요건을 갖추지 못한 신고서가 제출된 경우 지체 없이 상당한 기간을 정하여 보완을 요구하여야 하며, 보완하지 아니하면 그 이유를 구체적으로 밝혀 신고서를 되돌려 보내야 한다.","src":"행정절차법 제40조 제3항·제4항"},{"t":"행정기본법: 법률에 신고의 수리가 필요하다고 명시되어 있는 경우(행정기관의 내부 업무 처리 절차로서 수리를 규정한 경우는 제외)에는 행정청이 수리하여야 효력이 발생한다.","src":"행정기본법 제34조"},{"t":"수리를 요하지 않는 신고에 해당하는 것: 「건축법」 제14조 제1항에 따른 건축신고.","src":"기출 2022-28"},{"t":"수리를 요하는 신고(판례): 다른 법률에 의한 인·허가의제 효과를 수반하는 건축신고, 「수산업법」상 어업의 신고, 「노인장기요양보험법」상 장기요양기관의 폐업신고, 「식품위생법」상 영업양도에 따른 지위승계 신고.","src":"기출 2022-28"},{"t":"건축신고 반려행위는 항고소송의 대상이 되는 처분이다.","src":"보충"},{"t":"행위요건적 신고(수리를 요하는 신고): 수리 거부에 대해 항고소송이 가능하고, 수리가 있어야 법적 효과가 발생한다.","src":"보충"}]},{"머리":"사인의 공법행위 일반","줄":[{"t":"사인의 공법행위에는 의사표시 하자에 관한 민법 규정이 당연히 적용되지는 않는다. 행위의 성질에 따라 개별적으로 판단한다.","src":"보충"},{"t":"사인의 공법행위의 철회·보정은 행정청의 처분이 있기 전까지 가능하다. 신청의 성질상 불가능하거나 특별한 규정이 있으면 예외다.","src":"행정절차법 제17조 제8항"},{"t":"사인의 신청을 받은 행정청은 접수를 보류·거부하거나 부당하게 되돌려 보내서는 안 되고, 접수한 경우 접수증을 주어야 한다.","src":"행정절차법 제17조 제4항"},{"t":"신청에 흠이 있으면 행정청은 보완에 필요한 상당한 기간을 정해 지체 없이 보완을 요구하여야 한다.","src":"행정절차법 제17조 제5항"}]},{"머리":"행정법상 기간·시효","줄":[{"t":"국가에 대한 금전채권은 다른 법률에 규정이 없는 한 5년간 행사하지 아니하면 시효로 소멸한다.","src":"보충"},{"t":"공법상 부당이득반환청구는 공법관계에서 법률상 원인 없이 이득을 얻은 경우 인정되며, 원칙적으로 공법상 당사자소송으로 다툰다.","src":"보충"}]}],"함정":[]},"행정입법(법규명령과 행정규칙)":{"묶음":[{"머리":"법규명령의 종류와 한계","줄":[{"t":"법규명령은 위임명령(법률의 위임에 의한 새로운 입법사항 규정 가능)과 집행명령(상위 법령의 집행을 위한 세부사항만 규정)으로 나뉜다.","src":"보충"},{"t":"집행명령은 새로운 국민의 권리·의무를 정할 수 없다. 상위 법령의 위임이 없으면 새로운 의무를 정할 수 없다.","src":"기출 2023-28"},{"t":"대통령령은 법률에서 구체적으로 범위를 정하여 위임받은 사항과 법률을 집행하기 위하여 필요한 사항에 관하여 발한다(포괄위임 금지).","src":"보충"},{"t":"총리령·부령은 법률이나 대통령령의 위임 또는 직권으로 발한다.","src":"보충"},{"t":"입법 실제에서 대통령령에는 시행령, 총리령과 부령에는 시행규칙이라는 이름을 붙인다.","src":"기출 2023-28"},{"t":"헌법이 인정하고 있는 위임입법의 형식은 예시적인 것이다.","src":"기출 2021-28 | 기출 2023-28"},{"t":"법령의 위임이 없음에도 법령에 규정된 처분 요건 사항을 부령에서 변경하여 규정한 경우, 그 부령의 규정은 대외적 구속력이 없다.","src":"기출 2022-30"},{"t":"행정입법의 부작위는 항고소송으로 다툴 수 없다.","src":"기출 2022-30"}]},{"머리":"법규명령의 통제","줄":[{"t":"법원이 구체적 규범통제를 통해 위헌·위법으로 선언할 심판대상은 원칙적으로 재판의 전제성이 인정되는 조항에 한정된다. 해당 규정 전체가 아니다.","src":"기출 2021-28 | 기출 2023-28"},{"t":"행정소송에 대한 대법원판결에 의하여 명령·규칙이 헌법 또는 법률에 위반된다는 것이 확정되면 대법원은 지체 없이 그 사유를 행정안전부장관에게 통보하여야 하고, 통보를 받은 행정안전부장관은 지체 없이 이를 관보에 게재하여야 한다.","src":"행정소송법 제6조 | 기출 2022-30"},{"t":"명령·규칙의 위헌·위법 여부가 재판의 전제가 된 경우 대법원이 최종적으로 심사한다(구체적 규범통제).","src":"보충"},{"t":"법규명령 자체가 직접 국민의 권리·의무를 규율하여 집행행위 없이 법적 효과를 발생하면 처분으로서 항고소송의 대상이 된다.","src":"보충"}]},{"머리":"행정규칙","줄":[{"t":"행정규칙은 특별한 사정이 없는 한 대외적으로 국민이나 법원을 구속하는 효력이 없다.","src":"기출 2024-29"},{"t":"상급행정기관의 소속 공무원에 대한 업무처리지침은 일반적으로 행정조직 내부에서만 효력을 가진다.","src":"기출 2025-29"},{"t":"재량준칙은 일반적으로 행정조직 내부에서만 효력을 가질 뿐 대외적인 구속력을 갖는 것은 아니다.","src":"기출 2021-28"},{"t":"재량준칙은 행정의 자기구속법리나 평등원칙 등에 의해 대외적 구속력을 가질 수 있다.","src":"기출 2022-30"},{"t":"재량권 행사의 준칙인 행정규칙이 되풀이 시행되어 행정관행이 형성되고 행정기관이 자기구속을 당하게 되는 경우에는 헌법소원의 대상이 될 수 있다.","src":"기출 2021-28"},{"t":"처분이 행정규칙을 위반하였다고 해서 그러한 사정만으로 곧바로 위법하게 되는 것은 아니다.","src":"기출 2024-29 | 기출 2025-29"},{"t":"행정규칙에 따른 처분의 적법성은 상위법령의 규정과 입법 목적 등에 적합한지 여부에 따라 판단한다.","src":"기출 2024-29"},{"t":"행정규칙의 종류: 조직규칙, 근무규칙(훈령·지시·예규·일일명령), 영조물규칙, 규범해석규칙, 재량준칙, 법령보충적 행정규칙.","src":"보충"}]},{"머리":"법령보충적 행정규칙·고시","줄":[{"t":"법령보충적 행정규칙은 상위법령과 결합하여 대외적 구속력이 있는 법규명령으로서의 효력을 가진다.","src":"기출 2025-29"},{"t":"「장기요양급여 제공기준 및 급여비용 산정방법 등에 관한 고시」는 외부적 구속효가 인정된다.","src":"기출 2022-30"},{"t":"고시가 다른 집행행위의 매개 없이 그 자체로서 직접 국민의 구체적인 권리의무나 법률관계를 규율하는 성격을 가질 때에는 항고소송의 대상이 되는 행정처분이다.","src":"기출 2023-28"},{"t":"보건복지부 고시인 약제급여·비급여목록 및 급여상한금액표에 대해서는 취소소송으로 다툴 수 있다.","src":"기출 2021-28"},{"t":"제약회사는 위 고시 중 자기가 제조·공급하는 약제의 상한금액 인하 부분의 취소를 구할 원고적격이 있다.","src":"기출 2023-39"},{"t":"부령 형식의 제재적 처분기준은 행정청 내부의 사무처리준칙이다(판례). 대통령령 형식의 처분기준은 법규명령으로 보되 그 수치는 최고한도를 정한 것으로 본다.","src":"보충"}]},{"머리":"조례","줄":[{"t":"지방의회는 자치사무에 관하여 법률에 특별한 규정이 없는 한 지방자치단체장의 고유권한을 침해하지 않는 범위 내에서 조례를 제정할 수 있다.","src":"기출 2025-29"},{"t":"조례가 집행행위의 개입 없이 그 자체로서 직접 국민의 구체적인 권리의무에 영향을 미치는 등 법률상 효과를 발생하는 경우에는 항고소송의 대상이 되는 처분이다.","src":"기출 2025-29 | 기출 2021-43"},{"t":"지방자치단체는 법령의 범위에서 그 사무에 관하여 조례를 제정할 수 있다. 주민의 권리 제한 또는 의무 부과에 관한 사항이나 벌칙을 정할 때에는 법률의 위임이 있어야 한다.","src":"지방자치법 제28조 제1항"},{"t":"법령에서 조례로 정하도록 위임한 사항은 그 법령의 하위 법령에서 위임의 내용과 범위를 제한하거나 직접 규정할 수 없다.","src":"지방자치법 제28조 제2항"},{"t":"조례 위반 행위에 대해 조례로 1천만원 이하의 과태료를 정할 수 있다.","src":"지방자치법 제34조 제1항"}]}],"함정":[{"x":"법원이 구체적 규범통제를 통해 위헌·위법으로 선언할 심판대상은 원칙적으로 해당 규정 전체이고, 재판의 전제성이 인정되는 조항에 한정되지 않는다.","o":"심판대상은 원칙적으로 재판의 전제성이 인정되는 조항에 한정된다.","src":"기출 2021-28"},{"x":"대법원판결에 의해 명령·규칙이 헌법 또는 법률에 위반된다는 것이 확정된 경우 대법원은 지체 없이 그 사유를 법무부장관에게 통보하여야 한다.","o":"행정안전부장관에게 통보하여야 한다.","src":"기출 2022-30 | 행정소송법 제6조"},{"x":"상위 법령의 집행을 위하여 필요한 경우에는 상위 법령의 위임이 없더라도 집행명령으로 새로운 국민의 의무를 정할 수 있다.","o":"집행명령은 위임이 없으면 새로운 국민의 의무를 정할 수 없다.","src":"기출 2023-28"},{"x":"처분이 행정규칙을 따른 것이면 적법성이 보장된다.","o":"행정규칙을 따랐다는 사정만으로 적법성이 보장되지 않고, 상위법령에 적합한지로 판단한다.","src":"기출 2024-29"},{"x":"조례는 집행행위의 개입 없이도 그 자체로서 직접 국민의 구체적인 권리의무에 영향을 미치는 등의 법률상 효과를 발생하는 경우에도 항고소송의 대상이 될 수 없다.","o":"그런 경우 조례는 항고소송의 대상이 되는 처분이다.","src":"기출 2025-29"}]},"행정행위의 종류와 성립·효력":{"묶음":[{"머리":"행정행위의 분류 체계","줄":[{"t":"법률행위적 행정행위: 명령적 행위(하명·허가·면제)와 형성적 행위(특허·인가·대리). 준법률행위적 행정행위: 확인·공증·통지·수리.","src":"보충"},{"t":"하명: 작위·부작위·급부·수인의 의무를 명하는 행위.","src":"보충"},{"t":"허가: 법령에 의한 일반적·상대적 금지를 특정한 경우에 해제하여 적법하게 할 수 있게 하는 행위. 원칙적으로 기속행위다.","src":"보충"},{"t":"예외적 허가(예외적 승인): 사회적으로 유해한 행위를 원칙적으로 금지(억제적 금지)하고 예외적으로 허용하는 행위. 재량행위다.","src":"보충"},{"t":"특허: 특정인에게 권리·능력·포괄적 법률관계를 설정하는 형성적 행위. 재량행위다.","src":"보충"},{"t":"인가: 제3자의 법률행위의 효력을 보충하여 완성시키는 행위. 기본행위가 없으면 인가는 무효이고, 기본행위에 하자가 있으면 인가가 있어도 기본행위의 하자를 다툰다.","src":"보충"}]},{"머리":"법적 성질 구별(판례·기출)","줄":[{"t":"구 자동차관리법상 자동차정비조합설립인가: 인가.","src":"기출 2021-31"},{"t":"구 도시계획법상 개발제한구역 내의 건축허가: 예외적 허가.","src":"기출 2021-31"},{"t":"기부금품모집규제법상 기부금품모집허가: 허가.","src":"기출 2021-31"},{"t":"「부동산 거래신고 등에 관한 법률」상 외국인등의 토지거래 허가: 인가(강학상).","src":"기출 2022-32"},{"t":"공유수면매립면허: 특허. 보세구역의 설영특허: 특허.","src":"기출 2022-32"},{"t":"자동차운전면허대장상의 등재행위: 공증(준법률행위적 행정행위)으로 인가가 아니다.","src":"기출 2022-32 | 보충"}]},{"머리":"기속행위와 재량행위","줄":[{"t":"재량행위에 해당하는 것(판례): 구 출입국관리법상 체류자격변경허가, 구 농지법에 따른 농지전용행위를 수반하는 건축허가, 구 공유수면 관리 및 매립에 관한 법률상 공유수면 점용허가.","src":"기출 2025-32"},{"t":"구 국유재산법에 의한 국유재산의 무단점유 등에 대한 변상금부과는 기속행위다. 재량행위가 아니다.","src":"기출 2025-32"},{"t":"국토계획법에 의하여 지정된 도시지역 안에서 토지의 형질변경행위를 수반하는 건축허가는 재량행위다.","src":"기출 2021-29"},{"t":"공유수면 점용허가는 재량행위다.","src":"기출 2021-29 | 기출 2025-32"},{"t":"재량행위의 하자 유형: 재량권의 일탈(법정 한계를 넘음), 남용(목적 위반), 불행사(재량을 행사하지 아니함).","src":"보충"},{"t":"재외동포에 대한 사증발급과 관련한 재량권 불행사는 재량권 일탈·남용에 해당하여 해당 처분을 취소하여야 할 위법사유가 된다.","src":"기출 2021-29"},{"t":"법령상 감경사유가 있는 경우 이를 전혀 고려하지 않은 과징금 부과처분은 위법하다.","src":"기출 2021-29"},{"t":"행정청이 제재처분 양정을 하면서 이익형량을 하였더라도 양정에 정당성·객관성이 결여된 경우에는 재량권 일탈·남용으로 위법하다.","src":"기출 2021-29"},{"t":"행정청의 재량에 속하는 처분이라도 재량권의 한계를 넘거나 그 남용이 있는 때에는 법원은 이를 취소할 수 있다.","src":"행정소송법 제27조"},{"t":"재량행사의 기준: 행정청은 재량이 있는 처분을 할 때 관련 이익을 정당하게 형량하여야 하며, 재량권의 범위를 넘어서는 아니 된다.","src":"행정기본법 제21조"},{"t":"제재처분의 근거 법률에는 제재처분의 주체, 사유, 유형 및 상한을 명확하게 규정하여야 한다.","src":"행정기본법 제22조 제1항"},{"t":"재량이 있는 제재처분 시 고려사항: 위반행위의 동기·목적 및 방법, 위반행위의 결과, 위반행위의 횟수, 그 밖에 이에 준하는 사항으로서 대통령령으로 정하는 사항.","src":"행정기본법 제22조 제2항"},{"t":"제재처분의 제척기간: 법령등 위반행위가 종료된 날부터 5년이 지나면 제재처분(인허가의 정지·취소·철회, 등록 말소, 영업소 폐쇄와 정지를 갈음하는 과징금 부과)을 할 수 없다.","src":"행정기본법 제23조 제1항"},{"t":"제척기간 예외: 거짓이나 그 밖의 부정한 방법으로 인허가를 받거나 신고한 경우, 당사자가 위법성을 알았거나 중대한 과실로 알지 못한 경우, 정당한 사유 없이 조사·출입·검사를 기피·방해·거부하여 기간이 지난 경우, 제재처분을 하지 아니하면 국민의 안전·생명 또는 환경을 심각하게 해치거나 해칠 우려가 있는 경우.","src":"행정기본법 제23조 제2항"},{"t":"쟁송에서 취소·철회된 제재처분의 재처분: 재결·판결이 확정된 날부터 1년(합의제행정기관은 2년)이 지나기 전까지 그 취지에 따른 새로운 제재처분을 할 수 있다.","src":"행정기본법 제23조 제3항"},{"t":"완전히 자동화된 시스템(인공지능 기술 적용 포함)으로 처분할 수 있다. 처분에 재량이 있는 경우는 제외한다.","src":"행정기본법 제20조"}]},{"머리":"행정행위의 효력: 공정력","줄":[{"t":"공정력: 처분은 권한이 있는 기관이 취소·철회하거나 기간의 경과 등으로 소멸되기 전까지 유효한 것으로 통용된다. 실정법상 공정력을 규정한 조문으로 행정기본법 제15조가 있다.","src":"행정기본법 제15조 | 기출 2022-29"},{"t":"무효인 처분은 처음부터 효력이 발생하지 아니하므로 공정력이 없다.","src":"행정기본법 제15조 단서"},{"t":"민사소송에서 어느 행정처분의 당연무효 여부가 선결문제로 되는 때에는 민사법원은 이를 판단하여 당연무효임을 전제로 판결할 수 있다.","src":"기출 2024-30 | 행정소송법 제11조"},{"t":"처분등의 효력 유무 또는 존재 여부가 민사소송의 선결문제로 되어 수소법원이 심리·판단하는 경우, 수소법원은 그 처분등을 행한 행정청에게 선결문제로 된 사실을 통지하여야 한다.","src":"행정소송법 제11조 제2항"},{"t":"연령미달의 결격자가 타인의 이름으로 운전면허시험에 응시·합격하여 교부받은 운전면허는 당연무효가 아니다.","src":"기출 2024-30"},{"t":"구 「원자력법」에 따른 원자로 시설의 부지사전승인처분은 그 자체로서 독립한 행정처분이다.","src":"기출 2024-30"}]},{"머리":"행정행위의 효력: 존속력","줄":[{"t":"불가쟁력(형식적 존속력): 행정행위의 상대방이나 이해관계인에 대한 구속력으로, 법령에 의한 불복기간이 경과하면 그 처분의 효력을 다툴 수 없다.","src":"기출 2022-29 | 기출 2024-30"},{"t":"불가변력(실질적 존속력): 처분청 스스로도 당해 행정행위에 구속되어 직권으로 취소·변경할 수 없는 것. 행정청을 구속하는 효력이다.","src":"기출 2022-29 | 기출 2023-30"},{"t":"불가쟁력은 원칙적으로 모든 행정행위에 인정된다. 불가변력은 준사법적 행위(행정심판 재결 등) 등 일부 행정행위에 인정된다.","src":"기출 2023-30 | 보충"},{"t":"불가변력은 당해 행정행위에 대해서만 인정된다. 동종의 행정행위라도 대상을 달리하면 인정되지 않는다.","src":"기출 2023-30"},{"t":"불가변력이 있는 행정행위라도 쟁송기간이 경과하지 않는 한 행정쟁송에 의한 취소가 가능하다.","src":"기출 2022-29"},{"t":"불가쟁력은 쟁송으로 다툴 수 없게 되는 형식적 확정력일 뿐 기판력과 같은 실질적 확정력이 아니다. 불복기간이 지나 확정되어도 처분의 기초가 된 사실관계나 법률적 판단이 확정되는 것이 아니고, 당사자나 법원이 이에 기속되지 않는다.","src":"기출 2023-30 | 기출 2024-30"},{"t":"집행력은 의무가 부과되는 행정행위에서 문제된다.","src":"기출 2022-29"},{"t":"행정심판의 재결은 준사법적 행위로서 불가변력이 인정된다. 재결에 대해서도 제소기간 안에 취소소송을 제기할 수 있다.","src":"기출 2023-30 | 보충"}]},{"머리":"인허가의제(행정기본법 제24조~제26조)","줄":[{"t":"인허가의제: 하나의 인허가(주된 인허가)를 받으면 법률로 정하는 바에 따라 그와 관련된 여러 인허가(관련 인허가)를 받은 것으로 보는 것.","src":"행정기본법 제24조 제1항"},{"t":"인허가의제를 받으려면 주된 인허가를 신청할 때 관련 인허가에 필요한 서류를 함께 제출하여야 한다. 불가피한 사유로 함께 제출할 수 없는 경우에는 주된 인허가 행정청이 별도로 정하는 기한까지 제출할 수 있다.","src":"행정기본법 제24조 제2항 | 기출 2024-33 | 기출 2025-30"},{"t":"주된 인허가 행정청은 주된 인허가를 하기 전에 관련 인허가에 관하여 미리 관련 인허가 행정청과 협의하여야 한다.","src":"행정기본법 제24조 제3항 | 기출 2024-33 | 기출 2025-30"},{"t":"관련 인허가 행정청은 협의를 요청받은 날부터 20일 이내에 의견을 제출하여야 한다. 그 기간 내에 의견을 제출하지 아니하면 협의가 된 것으로 본다.","src":"행정기본법 제24조 제4항"},{"t":"협의를 요청받은 관련 인허가 행정청은 해당 법령을 위반하여 협의에 응해서는 아니 된다.","src":"행정기본법 제24조 제5항 | 기출 2024-33"},{"t":"관련 인허가에 필요한 심의, 의견 청취 등 절차는 법률에 인허가의제 시에도 해당 절차를 거친다는 명시적 규정이 있는 경우에만 거친다.","src":"행정기본법 제24조 제5항 단서"},{"t":"협의가 된 사항에 대해서는 주된 인허가를 받았을 때 관련 인허가를 받은 것으로 본다. 협의가 되었다는 사실만으로 받은 것으로 보지 않는다.","src":"행정기본법 제25조 제1항"},{"t":"인허가의제의 효과는 주된 인허가의 해당 법률에 규정된 관련 인허가에 한정된다.","src":"행정기본법 제25조 제2항 | 기출 2025-30"},{"t":"인허가의제의 경우 관련 인허가 행정청은 관련 인허가를 직접 한 것으로 보아 관계 법령에 따른 관리·감독 등 필요한 조치를 하여야 한다.","src":"행정기본법 제26조 제1항 | 기출 2024-33 | 기출 2025-30"},{"t":"주된 인허가가 있은 후 이를 변경하는 경우에는 제24조·제25조 및 제26조 제1항을 준용한다.","src":"행정기본법 제26조 제2항"},{"t":"인허가의제 처분기준: 관련 인허가 행정청은 관련 인허가의 처분기준을 주된 인허가 행정청에 제출하고, 주된 인허가 행정청은 통합하여 공표한다.","src":"행정절차법 제20조 제2항"}]}],"함정":[{"x":"공유수면 관리 및 매립에 관한 법률상 공유수면 점용허가는 기속행위이다.","o":"재량행위이다.","src":"기출 2021-29"},{"x":"재외동포에 대한 사증발급과 관련한 재량권 불행사는 그 자체로 재량권 일탈·남용에 해당하지 않으므로 해당 처분을 취소하여야 할 위법사유가 되지 않는다.","o":"재량권 불행사는 재량권 일탈·남용에 해당하여 위법사유가 된다.","src":"기출 2021-29"},{"x":"국토의 계획 및 이용에 관한 법률에 의하여 지정된 도시지역 안에서 토지의 형질변경행위를 수반하는 건축허가의 법적 성질은 기속행위이다.","o":"재량행위이다.","src":"기출 2021-29"},{"x":"행정청이 제재처분 양정을 하면서 이익형량을 하였다면 그 양정에 정당성·객관성이 결여된 경우라도 위법은 아니다.","o":"이익형량을 하였더라도 양정에 정당성·객관성이 결여되면 위법하다.","src":"기출 2021-29"},{"x":"실정법상 공정력을 직접적으로 규정하는 법률은 없다.","o":"행정기본법 제15조가 처분의 효력(공정력)을 규정한다.","src":"기출 2022-29"},{"x":"불가변력은 행정행위의 상대방이나 이해관계인을 구속하는 효력이고 불가쟁력은 행정청을 구속하는 효력이다.","o":"불가쟁력이 상대방·이해관계인을 구속하고, 불가변력이 행정청을 구속한다.","src":"기출 2023-30"},{"x":"불가변력은 모든 행정행위에 다 인정되지만, 불가쟁력은 예외적으로 일부 행정행위의 경우에만 인정된다.","o":"불가쟁력은 원칙적으로 모든 행정행위에 인정되고, 불가변력이 예외적으로 일부 행정행위에 인정된다.","src":"기출 2023-30"},{"x":"행정처분이 불복기간의 경과로 인하여 확정된 경우 처분의 기초가 된 사실관계나 법률적 판단이 확정되고, 당사자들이나 법원이 이에 기속되어 모순되는 주장이나 판단을 할 수 없게 된다.","o":"불복기간이 지나도 사실관계나 법률적 판단이 확정되지 않으며, 법원이 이에 기속되지 않는다(불가쟁력은 기판력이 아니다).","src":"기출 2023-30 | 기출 2024-30"},{"x":"행정심판의 재결은 준사법적 행위로서 불가쟁력이 인정되므로 행정심판 청구인은 제소 기간의 경과 여부를 불문하고 그 재결의 효력을 다툴 수 없게 된다.","o":"재결은 준사법적 행위로서 불가변력이 인정되는 것이며, 재결에 대해서는 제소기간 내에 취소소송을 제기할 수 있다.","src":"기출 2023-30"},{"x":"A와 B 사이에 협의가 되면 건축허가와 산지전용허가를 모두 받은 것으로 본다.","o":"협의가 된 사항에 대해서는 주된 인허가(건축허가)를 받았을 때 관련 인허가(산지전용허가)를 받은 것으로 본다.","src":"기출 2024-33 | 행정기본법 제25조 제1항"},{"x":"인허가의제 제도는 사업시행자의 이익을 위하여 만들어진 것이므로 사업시행자가 반드시 관련 인허가의제 처리를 신청할 의무가 있다.","o":"관련 인허가의제의 처리를 신청할지는 신청인의 선택이다. 의제 신청의무는 없다.","src":"기출 2025-30"}]},"행정행위의 부관":{"묶음":[{"머리":"부관의 종류와 허용성(행정기본법 제17조)","줄":[{"t":"부관의 종류: 조건, 기한, 부담, 철회권의 유보 등.","src":"행정기본법 제17조 제1항"},{"t":"행정청은 처분에 재량이 있는 경우에는 부관을 붙일 수 있다.","src":"행정기본법 제17조 제1항 | 기출 2021-30"},{"t":"행정청은 처분에 재량이 없는 경우에는 법률에 근거가 있는 경우에 부관을 붙일 수 있다.","src":"행정기본법 제17조 제2항 | 기출 2023-32 | 기출 2024-32"},{"t":"토지형질변경행위허가에 부관을 붙일 필요가 있는지 판단함에 있어서는 허가권자에게 재량의 여지가 있다.","src":"기출 2021-30"},{"t":"부관의 요건: 해당 처분의 목적에 위배되지 아니할 것, 해당 처분과 실질적인 관련이 있을 것, 해당 처분의 목적을 달성하기 위하여 필요한 최소한의 범위일 것.","src":"행정기본법 제17조 제4항 | 기출 2024-32"},{"t":"「하천법」상 하천부지 점용허가는 재량행위이므로 부관을 붙일 수 있다.","src":"기출 2024-32 | 보충"}]},{"머리":"사후부관(제17조 제3항)","줄":[{"t":"부관을 붙일 수 있는 처분은 처분을 한 후에도 부관을 새로 붙이거나 종전의 부관을 변경할 수 있다. 사유는 3가지다.","src":"행정기본법 제17조 제3항"},{"t":"사후부관 사유 1호: 법률에 근거가 있는 경우.","src":"행정기본법 제17조 제3항 제1호"},{"t":"사후부관 사유 2호: 당사자의 동의가 있는 경우.","src":"행정기본법 제17조 제3항 제2호 | 기출 2021-30"},{"t":"사후부관 사유 3호: 사정이 변경되어 부관을 새로 붙이거나 종전의 부관을 변경하지 아니하면 해당 처분의 목적을 달성할 수 없다고 인정되는 경우.","src":"행정기본법 제17조 제3항 제3호"}]},{"머리":"부담과 독립쟁송","줄":[{"t":"부담: 주된 행정행위에 부가하여 작위·부작위·급부·수인의무를 명하는 부관. 주된 행정행위의 효력 발생과는 별개로 효력을 발생한다.","src":"보충"},{"t":"부담을 불이행한 것만으로는 주된 행정행위의 효력이 소멸하지 않는다. 철회 사유가 되고 강제집행의 대상이 된다.","src":"기출 2023-32 | 보충"},{"t":"부담은 그 자체로서 독립하여 행정쟁송의 대상이 될 수 있다.","src":"기출 2023-32"},{"t":"어업면허처분 중 면허의 유효기간(기한)만 취소하여 달라는 소송은 허용될 수 없다.","src":"기출 2023-32"},{"t":"기부채납의 부관이 당연무효이거나 취소되지 아니한 이상, 부관으로 인한 증여계약의 중요부분의 착오를 이유로 증여계약을 취소할 수 없다.","src":"기출 2021-30"},{"t":"조건: 효력 발생·소멸이 장래 불확실한 사실에 의존하는 부관(정지조건·해제조건). 기한: 장래 확실한 사실에 의존하는 부관(시기·종기). 철회권의 유보: 일정한 경우 철회할 수 있음을 유보하는 부관.","src":"보충"},{"t":"부담 외의 부관(조건·기한 등)은 독립하여 쟁송할 수 없는 것이 원칙이다. 부담만 독립쟁송이 가능하다.","src":"보충"}]}],"함정":[{"x":"A시장은 토지형질변경행위허가를 한 후에는 甲의 동의가 있는 경우라도 부관을 새로 붙일 수 없다.","o":"당사자의 동의가 있는 경우에는 처분 후에도 부관을 새로 붙일 수 있다.","src":"기출 2021-30 | 행정기본법 제17조 제3항"},{"x":"부담부 행정행위는 부담을 이행하여야 비로소 그 효력이 발생한다.","o":"부담은 주된 행정행위의 효력 발생과 별개다. 부담을 이행하지 않아도 주된 행정행위는 효력이 발생한다. 부담을 이행하여야 효력이 발생하는 것은 정지조건이다.","src":"기출 2023-32"},{"x":"부관은 해당 처분과 실질적인 관련이 있어야 하지만, 해당 처분의 목적에는 구속되지 않는다.","o":"부관은 해당 처분의 목적에 위배되지 아니하여야 하고 실질적인 관련이 있어야 한다.","src":"기출 2024-32 | 행정기본법 제17조 제4항"},{"x":"법률이 예정하는 행정행위의 효과를 일부 배제하는 부관은 독립하여 행정소송의 대상이 될 수 있다.","o":"독립쟁송이 가능한 부관은 부담이다. 법률효과의 일부 배제는 독립하여 행정소송의 대상이 될 수 없다.","src":"기출 2024-32 | 보충"},{"x":"행정처분에 붙인 부담인 부관이 무효가 되면 그 부담의 이행으로 한 사법상 법률행위도 당연히 무효가 된다.","o":"부담이 무효여도 그 이행으로 한 사법상 법률행위가 당연히 무효가 되는 것은 아니다.","src":"기출 2024-32 | 기출 2021-30"},{"x":"「하천법」상 하천부지 점용허가에는 그 성질상 부관을 붙일 수 없다.","o":"재량행위인 하천부지 점용허가에는 부관을 붙일 수 있다.","src":"기출 2024-32"}]},"행정행위의 하자와 취소·철회":{"묶음":[{"머리":"무효와 취소의 구별","줄":[{"t":"무효와 취소의 구별 기준: 중대명백설(판례). 하자가 중대하고 명백하면 무효, 그에 미달하면 취소사유다.","src":"보충"},{"t":"무효인 처분은 처음부터 효력이 발생하지 아니한다.","src":"행정기본법 제15조 단서"},{"t":"무효확인소송에는 제소기간의 제한이 없다. 취소소송은 제소기간 내에 제기하여야 한다.","src":"보충"},{"t":"하자의 치유: 처음에는 흠이 있었으나 사후에 보완되거나 사정이 변하여 적법해지는 것. 쟁송제기 이전에 가능하다.","src":"보충"},{"t":"위법한 행정행위의 전환: 본래 행위로서는 무효이나 다른 행정행위의 요건을 갖춘 경우 그 행위로 인정하는 것.","src":"보충"}]},{"머리":"하자의 승계","줄":[{"t":"하자의 승계 요건(선행행위의 하자를 이유로 후행행위를 다툴 수 있는 경우): 선행행위와 후행행위가 모두 항고소송의 대상인 행정처분이어야 한다.","src":"기출 2022-31"},{"t":"하자의 승계 요건: 선행행위에는 취소사유인 하자가 존재해야 한다. 선행행위가 무효이면 승계 문제가 아니라 당연히 후행행위도 무효다.","src":"기출 2022-31"},{"t":"하자의 승계 요건: 후행행위는 하자가 없이 적법해야 한다.","src":"기출 2022-31"},{"t":"하자의 승계 요건: 선행행위에 불가쟁력이 발생해야 한다.","src":"기출 2022-31"},{"t":"후행행위에 불가변력이 발생해야 하는 것은 요건이 아니다.","src":"기출 2022-31"},{"t":"철거대집행 계고처분 후속의 대집행영장발부통보처분의 취소소송에서는 선행처분인 계고처분의 위법을 이유로 대집행영장발부통보처분이 위법하다고 주장할 수 있다(하자의 승계 인정).","src":"기출 2021-38"},{"t":"선행행위와 후행행위가 서로 결합하여 하나의 법률효과를 목적으로 하는 경우에는 하자가 승계된다. 별개의 효과를 목적으로 하면 승계되지 않는다(원칙). 예외적으로 수인한도·예측가능성 등을 고려해 승계를 인정한다.","src":"보충"}]},{"머리":"직권취소(행정기본법 제18조)","줄":[{"t":"행정청은 위법 또는 부당한 처분의 전부나 일부를 소급하여 취소할 수 있다. 취소사유에는 위법뿐 아니라 부당도 포함된다.","src":"행정기본법 제18조 제1항 | 기출 2025-31 | 기출 2024-31"},{"t":"당사자의 신뢰를 보호할 가치가 있는 등 정당한 사유가 있는 경우에는 장래를 향하여 취소할 수 있다.","src":"행정기본법 제18조 제1항 단서 | 기출 2024-31"},{"t":"권리나 이익을 부여하는 처분(수익적 처분)을 취소하려는 경우에는 취소로 인하여 당사자가 입게 될 불이익을 취소로 달성되는 공익과 비교·형량하여야 한다.","src":"행정기본법 제18조 제2항 | 기출 2025-31"},{"t":"비교·형량이 필요 없는 경우: 거짓이나 그 밖의 부정한 방법으로 처분을 받은 경우, 당사자가 처분의 위법성을 알고 있었거나 중대한 과실로 알지 못한 경우.","src":"행정기본법 제18조 제2항 단서"},{"t":"처분청은 그 처분의 성립에 하자가 있는 경우 이를 취소할 별도의 법적 근거가 없다고 하더라도 직권으로 취소할 수 있다.","src":"기출 2025-31"},{"t":"행정행위의 취소는 일단 유효하게 성립한 행정행위를 성립 당시 존재하던 하자를 사유로 소급하여 효력을 소멸시키는 행정처분이다.","src":"기출 2025-31"},{"t":"행정청의 행정행위 취소가 있더라도 취소사유의 내용, 경위 기타 제반 사정을 종합하여 행정행위의 효력을 장래에 향해 소멸시키는 철회에 해당하는지 살펴보아야 한다.","src":"기출 2025-31"},{"t":"산업재해보상보험법상 연금지급결정을 취소하는 처분이 적법하다고 하여 그에 터 잡은 징수처분이 반드시 적법한 것은 아니다.","src":"기출 2021-32"},{"t":"처분의 위법은 물론 부당한 경우에도 직권취소의 사유가 된다. 수익적 처분에 대한 직권취소의 필요성에 관한 증명책임은 처분청에 있다.","src":"기출 2021-32 | 보충"},{"t":"수익적 처분의 직권취소는 당사자에게 권익을 제한하는 처분이므로 행정절차법상 사전통지·의견청취 절차를 거쳐야 한다.","src":"행정절차법 제21조 | 기출 2021-32"},{"t":"행정소송이 계속되고 있는 때에도 행정청은 직권으로 해당 처분을 변경할 수 있다. 소송 대상 처분이 변경되면 원고는 청구의 취지·원인의 변경을 신청할 수 있다.","src":"기출 2021-32 | 행정소송법 제22조"},{"t":"위법한 처분의 일부에 대해서도 취소할 수 있다.","src":"행정기본법 제18조 제1항 | 기출 2024-31"}]},{"머리":"철회(행정기본법 제19조)","줄":[{"t":"철회: 적법한 처분을 장래를 향하여 효력을 소멸시키는 것.","src":"행정기본법 제19조 | 기출 2025-31"},{"t":"적법한 처분의 철회 사유 1호: 법률에서 정한 철회 사유에 해당하게 된 경우.","src":"행정기본법 제19조 제1항 제1호"},{"t":"철회 사유 2호: 법령등의 변경이나 사정변경으로 처분을 더 이상 존속시킬 필요가 없게 된 경우.","src":"행정기본법 제19조 제1항 제2호"},{"t":"철회 사유 3호: 중대한 공익을 위하여 필요한 경우.","src":"행정기본법 제19조 제1항 제3호 | 기출 2024-31"},{"t":"철회의 전부 또는 일부를 장래를 향하여 할 수 있다.","src":"행정기본법 제19조 제1항"},{"t":"철회하려는 경우에는 철회로 인하여 당사자가 입게 될 불이익을 철회로 달성되는 공익과 비교·형량하여야 한다. 예외 없이 형량이 필요하다.","src":"행정기본법 제19조 제2항 | 기출 2024-31"},{"t":"직권취소와 철회는 처분의 재심사에 의하여 영향을 받지 아니한다.","src":"행정기본법 제37조 제6항"}]},{"머리":"처분의 재심사·이의신청(행정기본법)","줄":[{"t":"처분에 이의가 있는 당사자는 처분을 받은 날부터 30일 이내에 해당 행정청에 이의신청을 할 수 있다. 행정청은 이의신청을 받은 날부터 14일 이내에 결과를 통지하고, 부득이한 사유가 있으면 만료일 다음 날부터 10일의 범위에서 한 차례 연장할 수 있다.","src":"행정기본법 제36조 제1항·제2항"},{"t":"이의신청 결과를 통지받은 후 행정심판 또는 행정소송을 제기하려면 그 결과를 통지받은 날부터 90일 이내에 하여야 한다. 이의신청과 관계없이 행정심판·행정소송을 제기할 수도 있다.","src":"행정기본법 제36조 제3항·제4항"},{"t":"이의신청 적용 제외: 공무원 인사 관계 법령에 따른 징계 등 처분, 국가인권위원회의 진정 결정, 노동위원회의 의결 사항, 형사·행형·보안처분, 외국인의 출입국·난민인정·귀화·국적회복, 과태료 부과 및 징수.","src":"행정기본법 제36조 제8항"},{"t":"처분의 재심사: 처분(제재처분 및 행정상 강제 제외)이 쟁송으로 다툴 수 없게 된 경우(법원의 확정판결이 있는 경우 제외)에도 처분의 근거가 된 사실관계·법률관계가 당사자에게 유리하게 바뀐 경우, 새로운 증거가 있는 경우, 민사소송법 재심사유에 준하는 사유가 있는 경우에는 처분을 한 행정청에 취소·철회·변경을 신청할 수 있다.","src":"행정기본법 제37조 제1항"},{"t":"재심사 신청은 당사자가 중대한 과실 없이 사유를 주장하지 못한 경우에만 가능하고, 사유를 안 날부터 60일 이내에 하여야 하며, 처분이 있은 날부터 5년이 지나면 신청할 수 없다.","src":"행정기본법 제37조 제2항·제3항"},{"t":"재심사 결과는 신청을 받은 날부터 90일(합의제행정기관은 180일) 이내에 통지하고, 연장은 한 차례 같은 기간의 범위에서 가능하다. 처분을 유지하는 결과는 쟁송으로 불복할 수 없다.","src":"행정기본법 제37조 제4항·제5항"}]}],"함정":[{"x":"처분의 위법은 직권취소의 사유가 되지만, 처분의 부당은 직권취소의 사유가 되지 않는다.","o":"위법뿐 아니라 부당한 처분도 직권취소할 수 있다.","src":"기출 2021-32 | 기출 2024-31 | 기출 2025-31"},{"x":"수익적 처분의 직권취소 필요성에 관한 증명책임은 처분의 상대방에 있다.","o":"증명책임은 처분청에 있다.","src":"기출 2021-32 | 보충"},{"x":"수익적 처분에 대한 직권취소의 경우에는 행정절차법상 사전통지가 필요하지 않다.","o":"수익적 처분의 직권취소는 권익을 제한하는 처분이므로 사전통지가 필요하다.","src":"기출 2021-32"},{"x":"행정청은 행정소송이 계속되고 있는 때에는 직권으로 해당 처분을 변경할 수 없다.","o":"행정소송이 계속 중이어도 직권으로 처분을 변경할 수 있다.","src":"기출 2021-32"},{"x":"후행행위에 불가변력이 발생해야 한다.","o":"하자 승계의 요건이 아니다. 요건은 선행·후행 모두 처분일 것, 선행행위 취소사유, 후행행위 적법, 선행행위 불가쟁력이다.","src":"기출 2022-31"},{"x":"위법한 처분의 일부에 대해 취소할 수 없다.","o":"위법 또는 부당한 처분의 전부나 일부를 취소할 수 있다.","src":"기출 2024-31"},{"x":"부당한 처분에 대해서는 취소할 수 없다.","o":"부당한 처분도 취소할 수 있다.","src":"기출 2024-31 | 행정기본법 제18조 제1항"},{"x":"적법한 처분은 중대한 공익을 위하여 필요한 경우에도 그 처분의 전부를 철회할 수 없다.","o":"중대한 공익을 위하여 필요한 경우 처분의 전부 또는 일부를 장래를 향하여 철회할 수 있다.","src":"기출 2024-31 | 행정기본법 제19조"},{"x":"적법한 처분을 철회하는 경우에는 철회로 인하여 당사자가 입게 될 불이익을 철회로 달성되는 공익과 비교·형량할 필요는 없다.","o":"철회하려는 경우 반드시 비교·형량하여야 한다.","src":"기출 2024-31 | 행정기본법 제19조 제2항"},{"x":"행정행위의 취소사유가 있는 경우에는 신뢰보호의 원칙 등을 고려할 필요가 없다.","o":"취소에는 신뢰보호의 원칙 등이 고려되어야 한다(행정기본법 제18조).","src":"기출 2025-31"}]},"그 밖의 행정작용형식(행정계획·공법상계약·행정지도·확약)":{"묶음":[{"머리":"행정계획","줄":[{"t":"행정계획: 특정한 행정목표를 달성하기 위하여 서로 관련되는 행정수단을 종합·조정함으로써 장래의 일정한 시점에 일정한 질서를 실현하기 위한 활동기준으로 설정된 것.","src":"기출 2025-28"},{"t":"행정주체는 구체적인 행정계획을 입안·결정하면서 비교적 광범위한 형성의 자유를 가진다.","src":"기출 2025-28"},{"t":"행정주체가 기반시설을 조성하기 위하여 도시·군계획시설결정을 할 때 행사하는 재량권에는 한계가 있다.","src":"기출 2025-28"},{"t":"자연환경 보호 등을 목적으로 하는 도시관리계획결정은 행정청의 재량적 판단으로서, 내용이 현저히 합리성을 결여하거나 형평·비례원칙에 뚜렷하게 반하는 등의 사정이 없는 한 폭넓게 존중되어야 한다.","src":"기출 2025-28"},{"t":"구 도시계획법상 도시기본계획은 행정청에 대한 지침일 뿐 일반 국민에 대한 직접적인 구속력이 없다.","src":"기출 2025-28 | 보충"},{"t":"행정청은 계획 중 국민의 권리·의무에 직접 영향을 미치는 계획을 수립하거나 변경·폐지할 때 관련된 여러 이익을 정당하게 형량하여야 한다.","src":"행정절차법 제40조의4"},{"t":"행정계획은 사인의 신뢰보호를 위해 일반적으로 계획존속청구권이 인정되는 것이 아니다. 계획변경청구권도 원칙적으로 부정되고, 예외적으로 특별한 사정이 있는 경우에만 인정된다.","src":"기출 2022-33 | 보충"},{"t":"계획재량: 일반 재량보다 넓은 형성의 자유를 갖되, 형량명령(이익형량을 하지 않거나 누락하거나 과소·과대평가한 경우 위법)에 의한 통제를 받는다.","src":"보충"}]},{"머리":"공법상 계약","줄":[{"t":"행정청은 법령등을 위반하지 아니하는 범위에서 행정목적을 달성하기 위하여 필요한 경우에는 공법상 법률관계에 관한 계약을 체결할 수 있다. 이 경우 계약의 목적 및 내용을 명확하게 적은 계약서를 작성하여야 한다.","src":"행정기본법 제27조 제1항 | 기출 2023-33 | 기출 2024-28"},{"t":"행정청은 공법상 계약의 상대방을 선정하고 계약 내용을 정할 때 공법상 계약의 공공성과 제3자의 이해관계를 고려하여야 한다.","src":"행정기본법 제27조 제2항 | 기출 2023-33"},{"t":"공법상 계약에는 법률우위의 원칙이 적용된다.","src":"기출 2024-28"},{"t":"공법상 계약에 따른 권리·의무의 확인 소송은 공법상 당사자소송에 의한다.","src":"기출 2024-28"},{"t":"확약은 일방적 행위라는 점에서 복수당사자의 의사의 합치인 공법상 계약과는 구분된다.","src":"기출 2022-34 | 기출 2024-28"},{"t":"「국가를 당사자로 하는 계약에 관한 법률」에 따라 국가가 당사자가 되는 공공계약은 사법상 계약이다. 공법상 계약이 아니다.","src":"기출 2024-28"},{"t":"계약직공무원에 대한 채용계약해지를 함에 있어서는 「행정절차법」에 의하여 그 근거와 이유를 제시할 필요가 없다.","src":"기출 2022-33"},{"t":"행정절차법에는 공법상 계약에 관한 규정이 없다. 행정절차법이 규정하는 행정절차는 처분, 신고, 확약, 위반사실 등의 공표, 행정계획, 행정상 입법예고, 행정예고 및 행정지도다.","src":"행정절차법 제3조 제1항 | 기출 2021-42"},{"t":"사법상 계약에는 계약자유의 원칙이 적용된다.","src":"기출 2021-33"}]},{"머리":"행정지도","줄":[{"t":"행정지도: 행정기관이 소관 사무의 범위에서 일정한 행정목적을 실현하기 위하여 특정인에게 일정한 행위를 하거나 하지 아니하도록 지도·권고·조언 등을 하는 행정작용.","src":"행정절차법 제2조 제3호"},{"t":"행정지도는 그 목적 달성에 필요한 최소한도에 그쳐야 하며, 상대방의 의사에 반하여 부당하게 강요하여서는 아니 된다.","src":"행정절차법 제48조 제1항 | 기출 2025-33"},{"t":"행정기관은 상대방이 행정지도에 따르지 아니하였다는 것을 이유로 불이익한 조치를 하여서는 아니 된다.","src":"행정절차법 제48조 제2항 | 기출 2023-31 | 기출 2025-33"},{"t":"행정지도를 하는 자는 그 상대방에게 그 행정지도의 취지 및 내용과 신분을 밝혀야 한다.","src":"행정절차법 제49조 제1항 | 기출 2025-33"},{"t":"행정지도가 말로 이루어지는 경우 상대방이 서면의 교부를 요구하면, 직무 수행에 특별한 지장이 없는 한 서면을 교부하여야 한다. 행정지도를 반드시 서면으로 해야 하는 것은 아니다.","src":"행정절차법 제49조 제2항 | 기출 2023-31"},{"t":"행정지도의 상대방은 해당 행정지도의 방식·내용 등에 관하여 행정기관에 의견제출을 할 수 있다.","src":"행정절차법 제50조 | 기출 2023-31 | 기출 2025-33"},{"t":"같은 행정목적을 실현하기 위하여 많은 상대방에게 행정지도를 하려는 경우에는 특별한 사정이 없으면 행정지도에 공통적인 내용이 되는 사항을 공표하여야 한다.","src":"행정절차법 제51조 | 기출 2023-31"},{"t":"행정지도의 원칙(임의성 원칙 등)은 행정절차법이 규정한다. 행정기본법에는 없다.","src":"기출 2023-31 | 행정절차법 제48조"},{"t":"행정지도에도 법률우위의 원칙은 적용된다.","src":"기출 2022-33"},{"t":"국가배상법의 배상청구 요건인 공무원의 직무에는 행정지도와 같은 비권력적 작용도 포함된다.","src":"기출 2025-33"}]},{"머리":"확약","줄":[{"t":"확약: 법령등에서 당사자가 신청할 수 있는 처분을 규정하고 있는 경우, 행정청이 당사자의 신청에 따라 장래에 어떤 처분을 하거나 하지 아니할 것을 내용으로 하는 의사표시.","src":"행정절차법 제40조의2 제1항"},{"t":"확약은 문서로 하여야 한다.","src":"행정절차법 제40조의2 제2항"},{"t":"다른 행정청과의 협의 등의 절차를 거쳐야 하는 처분에 대하여 확약을 하려면 확약을 하기 전에 그 절차를 거쳐야 한다.","src":"행정절차법 제40조의2 제3항"},{"t":"확약에 기속되지 않는 경우: 확약 후 내용을 이행할 수 없을 정도로 법령등이나 사정이 변경된 경우, 확약이 위법한 경우. 이때 행정청의 별도의 의사표시가 있어야 구속력이 상실되는 것은 아니다.","src":"행정절차법 제40조의2 제4항 | 기출 2022-34"},{"t":"확약을 이행할 수 없는 경우 행정청은 지체 없이 당사자에게 그 사실을 통지하여야 한다.","src":"행정절차법 제40조의2 제5항"},{"t":"확약은 종국적 규율이 아니라는 점에서 종국적 규율을 하는 사전결정이나 부분허가와 구분된다.","src":"기출 2022-34"},{"t":"어업권면허에 선행하는 우선순위결정은 강학상 확약에 불과하고 행정처분이 아니다.","src":"기출 2022-34 | 기출 2021-43"},{"t":"확약은 정당한 권한을 가진 행정청에 의해서 그 권한의 범위 내에서만 발해질 수 있다.","src":"기출 2022-34"}]},{"머리":"행정사법·사실행위","줄":[{"t":"행정사법작용: 행정주체가 사법형식으로 공행정을 수행하는 경우에도 기본권과 행정법의 일반원칙 등 공법적 제한을 받는다. 사적자치의 원칙이 통용된다고 공법적 제한을 받지 않는 것이 아니다.","src":"기출 2022-33"},{"t":"권력적 사실행위는 항고소송의 대상인 처분이다. 비권력적 사실행위는 처분이 아니다.","src":"기출 2022-33 | 보충"},{"t":"행정규칙에 의한 불문경고조치는 항고소송의 대상이 되는 행정처분에 해당하지 아니한다.","src":"기출 2025-39"}]}],"함정":[{"x":"국가를 당사자로 하는 계약에 관한 법률이 적용된다.","o":"출제 오답(2021-33 문항의 전제 사례에서 적용되지 않는 것으로 출제)","src":"기출 2021-33"},{"x":"계약의 체결에 관한 다툼은 공법상 당사자소송에 의한다.","o":"출제 오답(2021-33 문항의 계약은 사법상 계약이어서 다툼은 민사소송으로 한다)","src":"기출 2021-33 | 보충"},{"x":"계약절차에는 행정절차법이 적용된다.","o":"출제 오답(행정절차법은 계약을 규율하지 않는다)","src":"기출 2021-33 | 행정절차법 제3조"},{"x":"계약의 해지 통보에 관한 다툼은 취소소송에 의한다.","o":"출제 오답(해지 통보는 처분이 아니므로 민사소송 또는 당사자소송으로 다툰다)","src":"기출 2021-33 | 보충"},{"x":"행정계획은 사인의 신뢰보호를 위해 일반적으로 계획존속청구권이 인정된다.","o":"계획존속청구권은 일반적으로 인정되지 않는다.","src":"기출 2022-33"},{"x":"행정사법작용에는 사적자치의 원칙이 통용되므로 공법적 제한을 받지 않는다.","o":"행정사법작용도 기본권·행정법 일반원칙 등 공법적 제한을 받는다.","src":"기출 2022-33"},{"x":"사실행위는 법적 효과의 제거대상이 될 수 없으므로, 권력적인지 비권력적인지를 불문하고 항고소송의 대상인 처분성이 인정되지 않는다.","o":"권력적 사실행위는 처분성이 인정된다.","src":"기출 2022-33"},{"x":"행정지도는 상대방의 임의적인 협력을 구하는 것이므로, 법률우위의 원칙은 적용되지 않는다.","o":"행정지도에도 법률우위의 원칙이 적용된다.","src":"기출 2022-33"},{"x":"확약 이후에 사실상태 또는 법적 상태가 변경된 경우에도 확약의 구속성이 상실되기 위해서는 행정청의 별도의 의사표시가 있어야 한다.","o":"사정이 변경되어 확약 내용을 이행할 수 없게 된 때에는 별도의 의사표시 없이 확약에 기속되지 않는다.","src":"기출 2022-34 | 행정절차법 제40조의2 제4항"},{"x":"「행정기본법」은 임의성의 원칙 등 행정지도의 원칙에 관하여 규정하고 있다.","o":"행정지도의 원칙은 행정절차법이 규정한다.","src":"기출 2023-31"},{"x":"「행정절차법」은 공법상 계약의 절차에 관한 일반법이다.","o":"행정절차법에는 공법상 계약에 관한 규정이 없다. 공법상 계약은 행정기본법 제27조가 규정한다.","src":"기출 2023-33"},{"x":"행정청은 공법상 계약의 상대방을 선정하고 계약 내용을 정할 때 공법상 계약의 공공성만을 고려하여야 하고 제3자의 이해관계를 고려하여서는 아니 된다.","o":"공공성과 제3자의 이해관계를 모두 고려하여야 한다.","src":"기출 2023-33 | 행정기본법 제27조 제2항"},{"x":"공법상 계약에는 법률우위의 원칙이 적용되지 않는다.","o":"공법상 계약에도 법률우위의 원칙이 적용된다.","src":"기출 2023-33 | 기출 2024-28"},{"x":"행정청이 공법상 계약을 체결할 때 법령등에 따른 관계 행정청의 동의, 승인 등이 필요하다고 하여 이를 모두 거쳐야 하는 것은 아니다.","o":"출제 오답(관계 행정청의 동의·승인 등이 법령에 필요하다고 정해진 경우에는 이를 거쳐야 한다)","src":"기출 2023-33"},{"x":"「국가를 당사자로 하는 계약에 관한 법률」에 따라 국가가 당사자가 되는 공공계약은 공법상 계약에 해당한다.","o":"사법상 계약이다.","src":"기출 2024-28"},{"x":"구) 「도시계획법」상 도시기본계획은 일반 국민에 대한 직접적인 구속력이 있다.","o":"도시기본계획은 일반 국민에 대한 직접적인 구속력이 없다.","src":"기출 2025-28"},{"x":"「국가배상법」이 정한 배상청구의 요건인 공무원의 직무에는 행정지도와 같은 비권력적 작용은 포함되지 않는다.","o":"비권력적 작용도 포함된다.","src":"기출 2025-33"}]},"행정절차법":{"묶음":[{"머리":"총칙·적용범위","줄":[{"t":"행정절차에 관하여 다른 법률에 특별한 규정이 있는 경우를 제외하고는 행정절차법이 정하는 바에 따른다. 다른 법률의 특별 규정이 우선한다.","src":"행정절차법 제3조 제1항 | 기출 2022-35"},{"t":"행정절차법의 적용 대상 절차: 처분, 신고, 확약, 위반사실 등의 공표, 행정계획, 행정상 입법예고, 행정예고, 행정지도.","src":"행정절차법 제3조 제1항 | 기출 2021-42"},{"t":"적용 제외 1호: 국회 또는 지방의회의 의결을 거치거나 동의 또는 승인을 받아 행하는 사항.","src":"행정절차법 제3조 제2항 제1호 | 기출 2021-34"},{"t":"적용 제외 2~4호: 법원 또는 군사법원의 재판에 의하거나 그 집행으로 행하는 사항, 헌법재판소의 심판을 거쳐 행하는 사항, 각급 선거관리위원회의 의결을 거쳐 행하는 사항.","src":"행정절차법 제3조 제2항 제2호~제4호"},{"t":"적용 제외 5호: 감사원이 감사위원회의의 결정을 거쳐 행하는 사항.","src":"행정절차법 제3조 제2항 제5호 | 기출 2021-34"},{"t":"적용 제외 6호: 형사, 행형 및 보안처분 관계 법령에 따라 행하는 사항.","src":"행정절차법 제3조 제2항 제6호"},{"t":"적용 제외 7호: 국가안전보장·국방·외교 또는 통일에 관한 사항 중 행정절차를 거칠 경우 국가의 중대한 이익을 현저히 해칠 우려가 있는 사항.","src":"행정절차법 제3조 제2항 제7호 | 기출 2021-34"},{"t":"적용 제외 8호: 심사청구, 해양안전심판, 조세심판, 특허심판, 행정심판, 그 밖의 불복절차에 따른 사항.","src":"행정절차법 제3조 제2항 제8호 | 기출 2021-34"},{"t":"적용 제외 9호: 병역법에 따른 징집·소집, 외국인의 출입국·난민인정·귀화, 공무원 인사 관계 법령에 따른 징계와 그 밖의 처분, 이해 조정을 목적으로 하는 법령에 따른 알선·조정·중재·재정 또는 그 밖의 처분 등 성질상 행정절차를 거치기 곤란하거나 거칠 필요가 없다고 인정되는 사항과 행정절차에 준하는 절차를 거친 사항으로서 대통령령으로 정하는 사항.","src":"행정절차법 제3조 제2항 제9호"},{"t":"처분의 전제가 되는 사실이 경찰의 수사에 의하여 객관적으로 증명된 사항은 적용 제외 사항이 아니다. 법원의 재판 등에 의하여 객관적으로 증명된 경우는 사전통지 생략 사유(제21조 제4항 제2호)다.","src":"기출 2021-34 | 행정절차법 제21조 제4항"},{"t":"행정청: 행정에 관한 의사를 결정하여 표시하는 국가 또는 지방자치단체의 기관, 그 밖에 법령 또는 자치법규에 따라 행정권한을 가지고 있거나 위임 또는 위탁받은 공공단체 또는 그 기관이나 사인.","src":"행정절차법 제2조 제1호 | 기출 2021-41"},{"t":"당사자등: 행정청의 처분에 대하여 직접 그 상대가 되는 당사자, 행정청이 직권으로 또는 신청에 따라 행정절차에 참여하게 한 이해관계인.","src":"행정절차법 제2조 제4호"},{"t":"신의성실 및 신뢰보호: 행정청은 직무를 수행할 때 신의에 따라 성실히 하여야 하고, 법령등의 해석 또는 관행이 일반적으로 받아들여졌을 때에는 소급하여 불리하게 처리하여서는 아니 된다.","src":"행정절차법 제4조"},{"t":"투명성: 행정작용의 내용은 구체적이고 명확하여야 한다. 법령등의 내용이 명확하지 아니한 경우 상대방은 해석을 요청할 수 있고, 행정청은 특별한 사유가 없으면 요청에 따라야 한다.","src":"행정절차법 제5조"}]},{"머리":"관할·협조·행정응원","줄":[{"t":"행정청이 관할에 속하지 아니하는 사안을 접수하였거나 이송받은 경우에는 지체 없이 관할 행정청에 이송하여야 하고 그 사실을 신청인에게 통지하여야 한다.","src":"행정절차법 제6조 제1항 | 기출 2023-34"},{"t":"행정청의 관할이 분명하지 아니한 경우에는 해당 행정청을 공통으로 감독하는 상급 행정청이 관할을 결정하며, 공통으로 감독하는 상급 행정청이 없으면 각 상급 행정청이 협의하여 결정한다.","src":"행정절차법 제6조 제2항 | 기출 2023-34"},{"t":"행정청은 행정의 원활한 수행을 위하여 서로 협조하여야 한다.","src":"행정절차법 제7조 제1항 | 기출 2023-34"},{"t":"행정응원 요청 사유: 법령등의 이유로 독자적인 직무 수행이 어려운 경우, 인원·장비의 부족 등 사실상의 이유로 독자적인 직무 수행이 어려운 경우, 다른 행정청에 소속되어 있는 전문기관의 협조가 필요한 경우, 다른 행정청이 관리하고 있는 문서·통계 등 행정자료가 직무 수행을 위하여 필요한 경우, 다른 행정청의 응원을 받아 처리하는 것이 보다 능률적이고 경제적인 경우의 5가지.","src":"행정절차법 제8조 제1항 | 기출 2025-34"},{"t":"행정서비스에 대한 국민의 만족도를 높이기 위하여 필요한 경우는 행정응원 사유가 아니라 행정협업의 방식으로 적극 협조하는 사유(제7조 제2항)다.","src":"기출 2025-34 | 행정절차법 제7조 제2항"},{"t":"행정응원을 거부할 수 있는 경우: 다른 행정청이 보다 능률적이거나 경제적으로 응원할 수 있는 명백한 이유가 있는 경우, 행정응원으로 인하여 고유의 직무 수행이 현저히 지장받을 것으로 인정되는 명백한 이유가 있는 경우.","src":"행정절차법 제8조 제2항"},{"t":"응원을 거부하는 경우 그 사유를 응원을 요청한 행정청에 통지하여야 한다.","src":"행정절차법 제8조 제4항 | 기출 2023-34"},{"t":"응원을 위하여 파견된 직원은 응원을 요청한 행정청의 지휘·감독을 받는다.","src":"행정절차법 제8조 제5항"},{"t":"행정응원에 드는 비용은 응원을 요청한 행정청이 부담하며, 부담금액 및 부담방법은 양 행정청이 협의하여 결정한다.","src":"행정절차법 제8조 제6항 | 기출 2023-34"}]},{"머리":"당사자등·대표자·대리인","줄":[{"t":"당사자등이 될 수 있는 자: 자연인, 법인·법인이 아닌 사단 또는 재단, 그 밖에 다른 법령등에 따라 권리·의무의 주체가 될 수 있는 자.","src":"행정절차법 제9조"},{"t":"지위 승계: 당사자등이 사망한 경우의 상속인과 법령에 따라 권리·이익을 승계한 자, 합병 후 존속하거나 새로 설립된 법인등은 당사자등의 지위를 승계하고 행정청에 그 사실을 통지하여야 한다. 처분에 관한 권리·이익을 사실상 양수한 자는 행정청의 승인을 받아 지위를 승계할 수 있다.","src":"행정절차법 제10조"},{"t":"다수의 당사자등이 공동으로 행정절차에 관한 행위를 할 때에는 대표자를 선정할 수 있다. 행정청은 대표자가 선정되지 않거나 너무 많아 절차가 지연될 우려가 있으면 상당한 기간 내에 3인 이내의 대표자를 선정할 것을 요청할 수 있고, 따르지 않으면 직접 선정할 수 있다.","src":"행정절차법 제11조 제1항·제2항"},{"t":"대리인이 될 수 있는 자: 당사자등의 배우자·직계 존속·비속·형제자매, 법인등의 임원 또는 직원, 변호사, 행정청 또는 청문 주재자(청문의 경우)의 허가를 받은 자, 법령등에 따라 대리인이 될 수 있는 자.","src":"행정절차법 제12조 제1항"}]},{"머리":"송달·기간","줄":[{"t":"송달은 우편, 교부 또는 정보통신망 이용 등의 방법으로 하되, 송달받을 자의 주소·거소·영업소·사무소 또는 전자우편주소로 한다. 송달받을 자가 동의하는 경우에는 그를 만나는 장소에서 송달할 수 있다.","src":"행정절차법 제14조 제1항"},{"t":"정보통신망을 이용한 송달은 송달받을 자가 동의하는 경우에만 한다. 이 경우 송달받을 전자우편주소 등을 지정하여야 한다.","src":"행정절차법 제14조 제3항 | 기출 2023-35"},{"t":"행정청은 송달하는 문서의 명칭, 송달받는 자의 성명 또는 명칭, 발송방법 및 발송 연월일을 확인할 수 있는 기록을 보존하여야 한다.","src":"행정절차법 제14조 제6항 | 기출 2023-35"},{"t":"주소등을 통상적인 방법으로 확인할 수 없거나 송달이 불가능한 경우에는 관보, 공보, 게시판, 일간신문 중 하나 이상에 공고하고 인터넷에도 공고하여야 한다. 공고일부터 14일이 지난 때에 효력이 발생한다. 긴급 시 효력 발생 시기를 달리 정하여 공고할 수 있다.","src":"행정절차법 제14조 제4항·제15조 제3항"},{"t":"송달은 다른 법령등에 특별한 규정이 있는 경우를 제외하고는 해당 문서가 송달받을 자에게 도달됨으로써 효력이 발생한다(도달주의). 정보통신망 송달은 송달받을 자가 지정한 컴퓨터 등에 입력된 때 도달된 것으로 본다.","src":"행정절차법 제15조 제1항·제2항 | 기출 2023-35"},{"t":"천재지변이나 그 밖에 당사자등에게 책임이 없는 사유로 기간 및 기한을 지킬 수 없는 경우에는 그 사유가 끝나는 날까지 기간의 진행이 정지된다.","src":"행정절차법 제16조 제1항 | 기출 2023-35"},{"t":"외국에 거주하거나 체류하는 자에 대한 기간 및 기한은 행정청이 우편이나 통신에 걸리는 일수를 고려하여 정하여야 한다.","src":"행정절차법 제16조 제2항 | 기출 2023-35"}]},{"머리":"처분의 신청·처리","줄":[{"t":"처분을 구하는 신청은 문서로 하여야 한다. 다른 법령등에 특별한 규정이 있거나 행정청이 미리 다른 방법을 정하여 공시한 경우는 예외다.","src":"행정절차법 제17조 제1항"},{"t":"행정청은 신청에 필요한 구비서류, 접수기관, 처리기간, 그 밖에 필요한 사항을 게시하거나 편람을 갖추어 두고 누구나 열람할 수 있도록 하여야 한다.","src":"행정절차법 제17조 제3항"},{"t":"행정청은 신청을 받았을 때 접수를 보류·거부하거나 부당하게 되돌려 보내서는 아니 되며, 접수한 경우 신청인에게 접수증을 주어야 한다.","src":"행정절차법 제17조 제4항"},{"t":"신청에 구비서류의 미비 등 흠이 있는 경우 행정청은 보완에 필요한 상당한 기간을 정하여 지체 없이 보완을 요구하여야 하고, 보완하지 아니하면 그 이유를 구체적으로 밝혀 접수된 신청을 되돌려 보낼 수 있다.","src":"행정절차법 제17조 제5항·제6항"},{"t":"행정청은 신청인의 편의를 위하여 다른 행정청에 신청을 접수하게 할 수 있고, 이 경우 접수할 수 있는 신청의 종류를 미리 정하여 공시하여야 한다. 행정청의 편의를 위한 것이 아니다.","src":"행정절차법 제17조 제7항 | 기출 2024-34"},{"t":"신청인은 처분이 있기 전에는 신청의 내용을 보완·변경하거나 취하할 수 있다. 다른 법령등에 특별한 규정이 있거나 성질상 불가능하면 예외다.","src":"행정절차법 제17조 제8항"},{"t":"다수의 행정청이 관여하는 처분을 구하는 신청을 접수한 경우 관계 행정청과의 신속한 협조를 통하여 처분이 지연되지 아니하도록 하여야 한다.","src":"행정절차법 제18조 | 기출 2024-34"},{"t":"처리기간은 종류별로 미리 정하여 공표하여야 한다. 부득이한 사유가 있으면 처리기간의 범위에서 한 번만 연장할 수 있고, 연장 사유와 처리 예정 기한을 지체 없이 신청인에게 통지하여야 한다. 정당한 처리기간 내에 처리하지 아니하면 신청인은 해당 행정청 또는 감독 행정청에 신속한 처리를 요청할 수 있다.","src":"행정절차법 제19조"},{"t":"처분기준은 해당 처분의 성질에 비추어 되도록 구체적으로 정하여 공표하여야 하고, 변경하는 경우에도 같다. 해당 처분의 성질상 공표가 현저히 곤란하거나 공공의 안전 또는 복리를 현저히 해치는 것으로 인정될 만한 상당한 이유가 있는 경우에는 공표하지 아니할 수 있다.","src":"행정절차법 제20조 제1항·제3항 | 기출 2024-34"},{"t":"당사자등은 공표된 처분기준이 명확하지 아니한 경우 해당 행정청에 해석 또는 설명을 요청할 수 있고, 행정청은 특별한 사정이 없으면 요청에 따라야 한다.","src":"행정절차법 제20조 제4항"}]},{"머리":"사전통지(제21조)","줄":[{"t":"행정청은 당사자에게 의무를 부과하거나 권익을 제한하는 처분을 하는 경우에는 미리 처분의 제목, 당사자의 성명 또는 명칭과 주소, 처분하려는 원인이 되는 사실과 처분의 내용 및 법적 근거, 의견을 제출할 수 있다는 뜻과 의견을 제출하지 아니하는 경우의 처리방법, 의견제출기관의 명칭과 주소, 의견제출기한, 그 밖에 필요한 사항을 당사자등에게 통지하여야 한다.","src":"행정절차법 제21조 제1항"},{"t":"청문을 하려면 청문이 시작되는 날부터 10일 전까지 통지하여야 한다.","src":"행정절차법 제21조 제2항"},{"t":"의견제출기한은 의견제출에 필요한 기간을 10일 이상으로 고려하여 정하여야 한다.","src":"행정절차법 제21조 제3항"},{"t":"사전통지 생략 사유: 공공의 안전 또는 복리를 위하여 긴급히 처분을 할 필요가 있는 경우, 법령등에서 요구된 자격이 없거나 없어지게 되면 반드시 일정한 처분을 하여야 하는 경우에 그 사실이 법원의 재판 등에 의하여 객관적으로 증명된 경우, 처분의 성질상 의견청취가 현저히 곤란하거나 명백히 불필요하다고 인정될 만한 상당한 이유가 있는 경우.","src":"행정절차법 제21조 제4항"},{"t":"사전통지를 하지 아니하는 경우 처분을 할 때 당사자등에게 통지하지 아니한 사유를 알려야 한다. 신속한 처분이 필요하면 처분 후 알릴 수 있다.","src":"행정절차법 제21조 제6항"},{"t":"신청에 대한 거부처분은 사전통지의 대상이 아니다. 당사자의 권익을 제한하는 처분이 아니기 때문이다.","src":"기출 2022-35 | 기출 2021-47"}]},{"머리":"의견청취(제22조)","줄":[{"t":"청문을 하는 경우: 다른 법령등에서 청문을 하도록 규정한 경우, 행정청이 필요하다고 인정하는 경우, 인허가 등의 취소·신분 또는 자격의 박탈·법인이나 조합 등의 설립허가의 취소 처분을 하는 경우.","src":"행정절차법 제22조 제1항 | 기출 2021-35 | 기출 2022-35"},{"t":"인허가 등의 취소 시 청문은 2021 기출 당시에는 의견제출기한 내에 당사자등의 신청이 있는 경우에 하는 것으로 출제되었다. 현행법은 신청 없이도 청문을 한다.","src":"기출 2021-35 | 행정절차법 제22조 제1항 제3호"},{"t":"행정청이 청문이 필요하다고 인정하는 경우에는 법령등에 청문 규정이 없더라도 청문을 할 수 있다.","src":"행정절차법 제22조 제1항 제2호 | 기출 2022-35"},{"t":"공청회를 개최하는 경우: 다른 법령등에서 공청회를 개최하도록 규정한 경우, 해당 처분의 영향이 광범위하여 널리 의견을 수렴할 필요가 있다고 행정청이 인정하는 경우, 국민생활에 큰 영향을 미치는 처분으로서 대통령령으로 정하는 처분에 대하여 대통령령으로 정하는 수 이상의 당사자등이 개최를 요구하는 경우.","src":"행정절차법 제22조 제2항 | 기출 2021-35"},{"t":"청문이나 공청회를 하는 경우가 아니면서 의무를 부과하거나 권익을 제한하는 처분을 할 때에는 당사자등에게 의견제출의 기회를 주어야 한다.","src":"행정절차법 제22조 제3항"},{"t":"의견청취를 하지 않을 수 있는 경우: 제21조 제4항 각 호(사전통지 생략 사유)에 해당하는 경우, 당사자가 의견진술의 기회를 포기한다는 뜻을 명백히 표시한 경우.","src":"행정절차법 제22조 제4항"},{"t":"행정청은 청문·공청회 또는 의견제출을 거쳤을 때에는 신속히 처분하여 해당 처분이 지연되지 아니하도록 하여야 한다.","src":"행정절차법 제22조 제5항 | 기출 2021-35"},{"t":"행정청은 처분 후 1년 이내에 당사자등이 요청하면 청문·공청회·의견제출을 위하여 제출받은 서류나 그 밖의 물건을 반환하여야 한다.","src":"행정절차법 제22조 제6항"},{"t":"의견제출: 당사자등은 처분 전에 서면이나 말 또는 정보통신망을 이용하여 의견제출을 할 수 있고 증거자료를 첨부할 수 있다. 정당한 이유 없이 의견제출기한까지 의견제출을 하지 않으면 의견이 없는 것으로 본다.","src":"행정절차법 제27조"},{"t":"행정청은 당사자등이 제출한 의견이 상당한 이유가 있다고 인정하는 경우 이를 반영하여야 한다. 반영하지 아니하고 처분한 경우 당사자등이 처분이 있음을 안 날부터 90일 이내에 이유의 설명을 요청하면 서면으로 이유를 알려야 한다.","src":"행정절차법 제27조의2"}]},{"머리":"이유 제시·방식·정정·고지","줄":[{"t":"행정청은 처분을 할 때 당사자에게 그 근거와 이유를 제시하여야 한다. 이해관계인이 아니라 당사자에게 제시한다.","src":"행정절차법 제23조 제1항 | 기출 2021-35"},{"t":"이유 제시 생략 사유: 신청 내용을 모두 그대로 인정하는 처분인 경우, 단순·반복적인 처분 또는 경미한 처분으로서 당사자가 그 이유를 명백히 알 수 있는 경우, 긴급히 처분을 할 필요가 있는 경우.","src":"행정절차법 제23조 제1항 | 기출 2022-35 | 기출 2024-34"},{"t":"단순·반복적 처분이나 긴급 처분에서 이유 제시를 생략한 경우에도 처분 후 당사자가 요청하면 근거와 이유를 제시하여야 한다.","src":"행정절차법 제23조 제2항"},{"t":"처분은 문서로 하여야 한다. 당사자등의 동의가 있거나 당사자가 전자문서로 신청한 경우에는 전자문서로 할 수 있다.","src":"행정절차법 제24조 제1항"},{"t":"공공의 안전 또는 복리를 위하여 긴급히 처분을 할 필요가 있거나 사안이 경미한 경우에는 말, 전화, 문자 전송, 팩스 또는 전자우편 등 문서가 아닌 방법으로 할 수 있다. 당사자가 요청하면 지체 없이 문서를 주어야 한다.","src":"행정절차법 제24조 제2항 | 기출 2021-35"},{"t":"처분을 하는 문서에는 처분 행정청과 담당자의 소속·성명 및 연락처를 적어야 한다.","src":"행정절차법 제24조 제3항"},{"t":"처분에 오기, 오산 또는 그 밖에 이에 준하는 명백한 잘못이 있을 때에는 직권으로 또는 신청에 따라 지체 없이 정정하고 그 사실을 당사자에게 통지하여야 한다.","src":"행정절차법 제25조 | 기출 2024-34"},{"t":"처분을 할 때에는 당사자에게 행정심판 및 행정소송을 제기할 수 있는지 여부, 청구절차 및 청구기간, 그 밖에 필요한 사항을 알려야 한다.","src":"행정절차법 제26조"}]},{"머리":"청문 절차","줄":[{"t":"청문 주재자는 소속 직원 또는 대통령령으로 정하는 자격을 가진 사람 중에서 공정하게 선정한다.","src":"행정절차법 제28조 제1항"},{"t":"다수 국민의 이해가 상충되는 처분, 다수 국민에게 불편이나 부담을 주는 처분, 그 밖에 전문적이고 공정한 청문을 위하여 필요하다고 인정하는 처분을 하려는 경우에는 청문 주재자를 2명 이상으로 선정할 수 있다. 이 경우 1명이 대표한다.","src":"행정절차법 제28조 제2항 | 기출 2024-36"},{"t":"행정청은 청문이 시작되는 날부터 7일 전까지 청문 주재자에게 청문과 관련한 필요한 자료를 미리 통지하여야 한다.","src":"행정절차법 제28조 제3항"},{"t":"청문 주재자는 독립하여 공정하게 직무를 수행하며, 직무 수행을 이유로 본인의 의사에 반하여 신분상 불이익을 받지 아니한다. 벌칙 적용에서는 공무원으로 본다.","src":"행정절차법 제28조 제4항·제5항"},{"t":"청문 주재자의 제척 사유: 자신이 당사자등이거나 친족관계에 있거나 있었던 경우, 해당 처분과 관련하여 증언이나 감정을 한 경우, 당사자등의 대리인으로 관여하였던 경우, 해당 처분업무를 직접 처리하였던 경우, 해당 처분업무를 처리하는 부서에 근무하는 경우. 공정한 청문 진행이 어려운 사정이 있으면 당사자등은 기피신청을 할 수 있다.","src":"행정절차법 제29조"},{"t":"청문은 당사자가 공개를 신청하거나 청문 주재자가 필요하다고 인정하는 경우 공개할 수 있다. 공익 또는 제3자의 정당한 이익을 현저히 해칠 우려가 있는 경우에는 당사자가 공개를 신청하더라도 공개하여서는 아니 된다.","src":"행정절차법 제30조 | 기출 2024-36"},{"t":"청문 주재자는 청문을 시작할 때 먼저 예정된 처분의 내용, 그 원인이 되는 사실 및 법적 근거 등을 설명하여야 한다. 당사자등은 의견을 진술하고 증거를 제출할 수 있으며 참고인이나 감정인 등에게 질문할 수 있다. 의견서를 제출하면 출석하여 진술한 것으로 본다.","src":"행정절차법 제31조"},{"t":"청문 주재자는 직권으로 또는 당사자의 신청에 따라 필요한 조사를 할 수 있으며, 당사자등이 주장하지 아니한 사실에 대하여도 조사할 수 있다.","src":"행정절차법 제33조 제1항 | 기출 2024-36"},{"t":"청문 주재자는 필요하다고 인정할 때 관계 행정청에 필요한 문서의 제출 또는 의견의 진술을 요구할 수 있고, 관계 행정청은 직무 수행에 특별한 지장이 없으면 따라야 한다.","src":"행정절차법 제33조 제3항 | 기출 2024-36"},{"t":"청문 주재자는 청문조서를 작성하고, 청문을 마치면 청문조서, 의견서, 그 밖의 관계 서류를 행정청에 지체 없이 제출한다. 행정청은 처분 시 청문 결과를 상당한 이유가 있다고 인정하면 반영하여야 한다.","src":"행정절차법 제34조·제35조 제4항·제35조의2"},{"t":"당사자등이 정당한 사유로 청문기일에 출석하지 못하면 10일 이상의 기간을 정하여 의견진술 및 증거제출을 요구하여야 하며, 기간이 지난 후 청문을 마칠 수 있다.","src":"행정절차법 제35조 제3항"},{"t":"누구든지 의견제출 또는 청문을 통하여 알게 된 사생활이나 경영상 또는 거래상의 비밀을 정당한 이유 없이 누설하거나 다른 목적으로 사용하여서는 아니 된다.","src":"행정절차법 제37조 제6항 | 기출 2024-36"},{"t":"당사자등은 의견제출의 경우 사전 통지가 있는 날부터 의견제출기한까지, 청문의 경우 통지가 있는 날부터 청문이 끝날 때까지 조사결과 문서의 열람 또는 복사를 요청할 수 있다. 행정청은 다른 법령에 따라 공개가 제한되는 경우를 제외하고 거부할 수 없다.","src":"행정절차법 제37조 제1항"}]},{"머리":"공청회","줄":[{"t":"공청회 개최 14일 전까지 제목, 일시 및 장소, 주요 내용, 발표자에 관한 사항, 발표신청 방법 및 신청기한, 정보통신망을 통한 의견제출, 그 밖에 필요한 사항을 당사자등에게 통지하고 관보·공보·인터넷 홈페이지·일간신문 등에 공고하여야 한다. 예정대로 개최하지 못해 새로 정한 경우에는 7일 전까지 알려야 한다.","src":"행정절차법 제38조"},{"t":"공청회의 주재자는 공정하게 진행하여야 하며, 발표자는 공청회의 내용과 직접 관련된 사항에 대하여만 발표한다. 발표자 상호간 질의·답변을 할 수 있게 하고 방청인에게도 의견을 제시할 기회를 주어야 한다.","src":"행정절차법 제39조"}]},{"머리":"신고·위반사실 공표","줄":[{"t":"신고서가 기재사항에 흠이 없고 구비서류가 첨부되어 있으며 형식상 요건에 적합하면 접수기관에 도달된 때 신고 의무가 이행된 것으로 본다.","src":"행정절차법 제40조 제2항"},{"t":"위반사실 등의 공표는 법률로 정하는 바에 따른다. 공표 전에 객관적이고 타당한 증거와 근거가 있는지 확인하고, 미리 당사자에게 통지하여 의견제출 기회를 주어야 한다(긴급·의견청취 곤란·명백히 불필요·포기의 경우 예외).","src":"행정절차법 제40조의3 제1항~제3항"},{"t":"공표된 내용이 사실과 다른 것으로 밝혀지거나 공표에 포함된 처분이 취소된 경우에는 정정하여 같은 방법으로 공표된 기간 이상 공표한다. 당사자가 원하지 않으면 공표하지 아니할 수 있다.","src":"행정절차법 제40조의3 제8항"}]},{"머리":"입법예고·행정예고","줄":[{"t":"법령등을 제정·개정 또는 폐지하려는 경우 입법안을 마련한 행정청은 입법예고하여야 한다. 예고하지 않을 수 있는 경우: 입법이 긴급을 요하는 경우, 상위 법령등의 단순한 집행을 위한 경우, 국민의 권리·의무 또는 일상생활과 관련이 없는 경우, 단순한 표현·자구 변경 등 예고의 필요가 없거나 곤란한 경우, 예고함이 공공의 안전 또는 복리를 현저히 해칠 우려가 있는 경우.","src":"행정절차법 제41조 제1항"},{"t":"입법예고기간은 특별한 사정이 없으면 40일(자치법규는 20일) 이상으로 한다.","src":"행정절차법 제43조"},{"t":"법령의 입법안은 관보 및 법제처장이 구축·제공하는 정보시스템을 통해, 자치법규의 입법안은 공보를 통해 공고한다. 대통령령을 입법예고하는 경우 국회 소관 상임위원회에 제출하여야 한다.","src":"행정절차법 제42조"},{"t":"누구든지 예고된 입법안에 의견을 제출할 수 있고, 행정청은 특별한 사유가 없으면 존중하여 처리하여야 하며 처리결과를 통지하여야 한다.","src":"행정절차법 제44조"},{"t":"정책·제도·계획(정책등)을 수립·시행하거나 변경하려는 경우 행정예고를 하여야 한다. 행정예고기간은 20일 이상이다. 긴급한 필요가 있으면 단축할 수 있으나 10일 이상이어야 한다.","src":"행정절차법 제46조"},{"t":"행정예고를 하지 아니할 수 있는 경우: 긴급한 사유로 예고가 현저히 곤란한 경우, 법령등의 단순한 집행을 위한 경우, 국민의 권리·의무 또는 일상생활과 관련이 없는 경우, 예고가 공공의 안전 또는 복리를 현저히 해칠 우려가 상당한 경우.","src":"행정절차법 제46조 제1항"}]},{"머리":"그 밖의 규정","줄":[{"t":"행정절차에 드는 비용은 행정청이 부담한다. 당사자등이 자기를 위하여 스스로 지출한 비용은 그러하지 아니하다.","src":"행정절차법 제54조"}]}],"함정":[{"x":"행정절차에 관하여 다른 법률에 특별한 규정이 있는 경우에도 「행정절차법」이 우선한다.","o":"다른 법률에 특별한 규정이 있으면 그 규정이 우선한다.","src":"기출 2022-35 | 행정절차법 제3조 제1항"},{"x":"행정청은 청문이 필요하다고 인정하는 경우에도 법령등에서 청문을 하도록 규정한 경우가 아니면 청문을 할 수 없다.","o":"행정청이 필요하다고 인정하는 경우에도 청문을 한다.","src":"기출 2022-35 | 행정절차법 제22조 제1항 제2호"},{"x":"신청에 대한 거부처분은 사전통지대상이다.","o":"거부처분은 사전통지 대상이 아니다.","src":"기출 2022-35 | 기출 2021-47"},{"x":"「행정절차법」에는 행정지도에 관한 규정을 두고 있지 않다.","o":"행정절차법 제48조~제51조에 행정지도 규정이 있다.","src":"기출 2022-35"},{"x":"행정청은 처분을 할 때에는 이해관계인에게 그 근거와 이유를 제시하여야 한다.","o":"당사자에게 제시한다.","src":"기출 2021-35 | 행정절차법 제23조"},{"x":"행정응원에 드는 비용은 응원을 하는 행정청이 부담한다.","o":"응원을 요청한 행정청이 부담한다.","src":"기출 2023-34 | 행정절차법 제8조 제6항"},{"x":"정보통신망을 이용한 송달은 송달받을 자의 동의 여부와 상관없이 언제든지 가능하다.","o":"송달받을 자가 동의하는 경우에만 가능하다.","src":"기출 2023-35"},{"x":"행정청은 송달하는 문서의 명칭과 송달받는 자의 성명을 확인할 수 있는 기록을 보존하지 않아도 된다.","o":"문서의 명칭, 송달받는 자, 발송방법 및 발송 연월일을 확인할 수 있는 기록을 보존하여야 한다.","src":"기출 2023-35"},{"x":"송달은 다른 법령등에 특별한 규정이 있는 경우를 제외하고는 해당 문서를 발신한 때 그 효력이 발생한다.","o":"도달된 때 효력이 발생한다.","src":"기출 2023-35"},{"x":"천재지변으로 기한을 지킬 수 없는 경우에는 그 사유가 끝나는 날이 속하는 주말까지 기간의 진행이 정지된다.","o":"그 사유가 끝나는 날까지 기간의 진행이 정지된다.","src":"기출 2023-35"},{"x":"행정청은 처분을 할 때에는 단순·반복적인 처분으로서 당사자가 그 이유를 명백히 알 수 있는 경우에도 당사자에게 그 근거와 이유를 사전에 제시하여야 한다.","o":"이 경우에는 이유 제시를 생략할 수 있다(처분 후 당사자가 요청하면 제시).","src":"기출 2024-34"},{"x":"행정청은 처분에 오기(誤記)가 있어서 직권으로 이를 정정한 경우에는 그 사실을 당사자에게 통지할 필요는 없다.","o":"정정하고 그 사실을 당사자에게 통지하여야 한다.","src":"기출 2024-34"},{"x":"행정청은 행정청의 편의를 위하여 신청인이 다른 행정청에 처분을 구하는 신청을 접수하게 할 수 있다.","o":"신청인의 편의를 위하여 다른 행정청에 접수하게 할 수 있다.","src":"기출 2024-34"},{"x":"행정청은 필요한 처분기준을 정하여 공표하는 것이 해당 처분의 성질상 현저히 곤란한 경우라도 그 처분기준을 공표하여야 한다.","o":"그 경우에는 처분기준을 공표하지 아니할 수 있다.","src":"기출 2024-34"},{"x":"청문 주재자는 직권으로 당사자등이 주장한 사실에 한하여 필요한 조사를 하여야 한다.","o":"당사자등이 주장하지 아니한 사실에 대하여도 조사할 수 있다.","src":"기출 2024-36"}]},"정보공개와 개인정보보호":{"묶음":[{"머리":"정보공개법 총칙","줄":[{"t":"정보: 공공기관이 직무상 작성 또는 취득하여 관리하고 있는 문서(전자문서 포함) 및 전자매체를 비롯한 모든 형태의 매체 등에 기록된 사항. 공개 청구의 대상은 공공기관이 보유·관리하고 있는 정보에 한정된다.","src":"정보공개법 제2조 제1호 | 기출 2022-38"},{"t":"공공기관: 국가기관(국회·법원·헌법재판소·중앙선거관리위원회, 중앙행정기관 및 소속 기관, 행정기관 소속 위원회), 지방자치단체, 공공기관의 운영에 관한 법률 제2조의 공공기관, 지방공사 및 지방공단, 그 밖에 대통령령으로 정하는 기관.","src":"정보공개법 제2조 제3호"},{"t":"사립대학교를 포함한 각급 학교는 대통령령으로 정하는 기관으로서 정보공개의무를 지는 공공기관에 해당한다.","src":"기출 2021-36 | 보충"},{"t":"정보공개 청구권자: 모든 국민. 외국인의 청구는 대통령령으로 정한다.","src":"정보공개법 제5조"},{"t":"정보공개를 청구할 수 있는 외국인: 국내에 일정한 주소를 두고 거주하거나 학술·연구를 위하여 일시적으로 체류하는 사람, 국내에 사무소를 두고 있는 법인 또는 단체.","src":"정보공개법 시행령 제3조 | 기출 2021-36 | 기출 2022-38"},{"t":"정보공개 청구는 청구서를 제출하거나 말로써 할 수 있다. 말로 하는 경우 담당공무원 앞에서 진술하고, 담당공무원이 청구조서를 작성하여 청구인과 함께 기명날인 또는 서명한다.","src":"정보공개법 제10조 | 기출 2024-35"},{"t":"공공기관이 정보공개를 요구받고 공개를 거부하는 경우에는 비공개사유에 해당하는지를 주장·입증하지 아니한 채 개괄적인 사유만을 들어 공개를 거부할 수 없다.","src":"기출 2021-36"},{"t":"정보공개 청구권자의 권리구제 가능성이 없다는 이유로 비공개 대상 정보에 해당하지 않는 정보를 공개하지 않을 수는 없다.","src":"기출 2022-38"}]},{"머리":"비공개 대상 정보(제9조 제1항)","줄":[{"t":"1호: 다른 법률 또는 법률에서 위임한 명령(국회규칙·대법원규칙·헌법재판소규칙·중앙선거관리위원회규칙·대통령령 및 조례로 한정)에 따라 비밀이나 비공개 사항으로 규정된 정보.","src":"정보공개법 제9조 제1항 제1호"},{"t":"2호: 국가안전보장·국방·통일·외교관계 등에 관한 사항으로서 공개될 경우 국가의 중대한 이익을 현저히 해칠 우려가 있다고 인정되는 정보.","src":"정보공개법 제9조 제1항 제2호"},{"t":"3호: 공개될 경우 국민의 생명·신체 및 재산의 보호에 현저한 지장을 초래할 우려가 있다고 인정되는 정보.","src":"정보공개법 제9조 제1항 제3호"},{"t":"4호: 진행 중인 재판에 관련된 정보와 범죄의 예방, 수사, 공소의 제기 및 유지, 형의 집행, 교정, 보안처분에 관한 사항으로서 공개될 경우 직무수행을 현저히 곤란하게 하거나 형사피고인의 공정한 재판을 받을 권리를 침해한다고 인정할 만한 상당한 이유가 있는 정보.","src":"정보공개법 제9조 제1항 제4호"},{"t":"‘진행 중인 재판에 관련된 정보’에 해당하여 공개를 거부하기 위해 반드시 그 정보가 진행 중인 재판의 소송기록 자체에 포함되어야 하는 것은 아니다.","src":"기출 2021-37"},{"t":"5호: 감사·감독·검사·시험·규제·입찰계약·기술개발·인사관리에 관한 사항이나 의사결정 과정 또는 내부검토 과정에 있는 사항 등으로서 공개될 경우 업무의 공정한 수행이나 연구·개발에 현저한 지장을 초래한다고 인정할 만한 상당한 이유가 있는 정보.","src":"정보공개법 제9조 제1항 제5호"},{"t":"의사결정 과정 또는 내부검토 과정을 이유로 비공개할 때에는 통지 시 그 단계 및 종료 예정일을 함께 안내하여야 하며, 과정이 종료되면 청구인에게 통지하여야 한다.","src":"정보공개법 제9조 제1항 제5호 단서"},{"t":"의사결정과정에 제공된 회의관련자료나 의사결정과정이 기록된 회의록은 의사가 결정되거나 집행된 경우에는 더 이상 의사결정과정에 있는 사항 그 자체는 아니나, 의사결정과정에 있는 사항에 준하는 사항으로서 비공개대상정보에 포함될 수 있다.","src":"기출 2021-37"},{"t":"학교폭력대책자치위원회의 회의록은 공개될 경우 업무의 공정한 수행에 현저한 지장을 초래한다고 인정할 만한 상당한 이유가 있는 정보에 해당한다.","src":"기출 2021-37"},{"t":"6호: 성명·주민등록번호 등 개인정보로서 공개될 경우 사생활의 비밀 또는 자유를 침해할 우려가 있다고 인정되는 정보. 법령에 따라 열람할 수 있는 정보, 공표 목적 정보로서 사생활을 부당하게 침해하지 않는 정보, 공개가 공익이나 개인의 권리구제를 위하여 필요하다고 인정되는 정보, 직무를 수행한 공무원의 성명·직위, 공익을 위해 필요한 경우 위탁·위촉 개인의 성명·직업은 제외.","src":"정보공개법 제9조 제1항 제6호"},{"t":"7호: 법인·단체 또는 개인의 경영상·영업상 비밀에 관한 사항으로서 공개될 경우 정당한 이익을 현저히 해칠 우려가 있는 정보. 위해로부터 사람의 생명·신체·건강을 보호하기 위해 공개할 필요가 있는 정보, 위법·부당한 사업활동으로부터 국민의 재산 또는 생활을 보호하기 위해 공개할 필요가 있는 정보는 제외.","src":"정보공개법 제9조 제1항 제7호"},{"t":"법인이 거래하는 금융기관의 계좌번호에 관한 정보는 법인의 영업상 비밀에 관한 사항으로서 비공개 대상 정보에 해당한다.","src":"기출 2022-38"},{"t":"8호: 공개될 경우 부동산 투기, 매점매석 등으로 특정인에게 이익 또는 불이익을 줄 우려가 있다고 인정되는 정보.","src":"정보공개법 제9조 제1항 제8호 | 기출 2024-35"},{"t":"비공개 사유가 기간의 경과 등으로 없어진 경우에는 그 정보를 공개 대상으로 하여야 한다.","src":"정보공개법 제9조 제2항"},{"t":"공개 청구한 정보가 비공개 대상 부분과 공개 가능한 부분이 혼합되어 있고 청구 취지에 어긋나지 않는 범위에서 분리할 수 있으면 비공개 부분을 제외하고 공개하여야 한다(부분 공개).","src":"정보공개법 제14조 | 기출 2021-36"}]},{"머리":"공개 결정 절차","줄":[{"t":"공공기관은 정보공개 청구를 받은 날부터 10일 이내에 공개 여부를 결정하여야 한다.","src":"정보공개법 제11조 제1항 | 기출 2024-35"},{"t":"부득이한 사유가 있으면 기간이 끝나는 날의 다음 날부터 기산하여 10일의 범위에서 연장할 수 있고, 연장 사실과 사유를 청구인에게 지체 없이 문서로 통지한다.","src":"정보공개법 제11조 제2항"},{"t":"공개 청구된 정보의 전부 또는 일부가 제3자와 관련이 있다고 인정할 때 공공기관은 그 사실을 제3자에게 지체 없이 통지하여야 하며, 필요한 경우 의견을 들을 수 있다.","src":"정보공개법 제11조 제3항 | 기출 2024-35"},{"t":"제3자는 통지를 받은 날부터 3일 이내에 비공개를 요청할 수 있다. 비공개 요청에도 공개 결정을 한 경우 제3자는 통지를 받은 날부터 7일 이내에 이의신청을 하거나 행정심판 또는 행정소송을 제기할 수 있고, 공개 결정일과 공개 실시일 사이에 최소한 30일의 간격을 두어야 한다.","src":"정보공개법 제21조"},{"t":"공공기관은 공개를 결정한 경우 공개의 일시 및 장소 등을 밝혀 통지하고, 청구인이 사본 또는 복제물의 교부를 원하는 때에는 이를 교부하여야 한다.","src":"정보공개법 제13조 제1항·제2항 | 기출 2024-35"},{"t":"비공개 결정을 한 경우 지체 없이 문서로 통지하고, 어느 호에 해당하는 비공개 대상인지를 포함한 비공개 이유와 불복의 방법 및 절차를 구체적으로 밝혀야 한다.","src":"정보공개법 제13조 제5항"},{"t":"다른 공공기관이 보유·관리하는 정보의 공개 청구를 받았을 때에는 지체 없이 소관 기관으로 이송하고 청구인에게 문서로 통지한다.","src":"정보공개법 제11조 제4항"},{"t":"공공기관은 국가기관등에 정보공개심의회를 설치·운영하며, 심의회는 위원장 1명을 포함하여 5명 이상 7명 이하의 위원으로 구성하고 위원 중 3분의 2는 외부 전문가로 위촉한다.","src":"정보공개법 제12조"}]},{"머리":"불복 절차","줄":[{"t":"이의신청: 비공개 결정 또는 부분 공개 결정에 불복이 있거나 정보공개 청구 후 20일이 경과하도록 결정이 없는 때, 결정 통지를 받은 날 또는 청구 후 20일이 경과한 날부터 30일 이내에 해당 공공기관에 문서로 이의신청을 할 수 있다.","src":"정보공개법 제18조 제1항 | 기출 2025-35"},{"t":"공공기관은 이의신청을 받은 날부터 7일 이내에 결정하고 결과를 지체 없이 문서로 통지하여야 한다. 부득이한 사유가 있으면 7일의 범위에서 연장할 수 있다.","src":"정보공개법 제18조 제3항 | 기출 2025-35"},{"t":"국가기관등은 이의신청이 있으면 심의회를 개최하여야 한다. 이미 심의를 거친 사항, 단순·반복적인 청구, 법령에 따라 비밀로 규정된 정보에 대한 청구는 개최하지 않을 수 있다.","src":"정보공개법 제18조 제2항"},{"t":"청구인은 이의신청 절차를 거치지 아니하고 행정심판을 청구할 수 있다.","src":"정보공개법 제19조 제2항 | 기출 2021-36"},{"t":"비공개 결정에 대한 불복절차로 이의신청, 행정심판, 행정소송이 있다.","src":"정보공개법 제18조~제20조 | 기출 2022-38"},{"t":"행정소송에서 재판장은 필요하다고 인정하면 당사자를 참여시키지 않고 제출된 공개 청구 정보를 비공개로 열람·심사할 수 있다.","src":"정보공개법 제20조 제2항"}]},{"머리":"개인정보 보호법: 용어와 원칙","줄":[{"t":"개인정보: 살아 있는 개인에 관한 정보로서 개인을 알아볼 수 있는 정보, 다른 정보와 쉽게 결합하여 알아볼 수 있는 정보, 이를 가명처리한 가명정보.","src":"개인정보 보호법 제2조 제1호"},{"t":"가명처리: 개인정보의 일부를 삭제하거나 일부 또는 전부를 대체하는 등의 방법으로 추가 정보가 없이는 특정 개인을 알아볼 수 없도록 처리하는 것.","src":"개인정보 보호법 제2조 제1호의2"},{"t":"개인정보처리자는 개인정보의 처리 목적을 명확하게 하고 그 목적에 필요한 범위에서 최소한의 개인정보만을 적법하고 정당하게 수집하여야 한다.","src":"개인정보 보호법 제3조 제1항"},{"t":"개인정보처리자는 처리 목적에 필요한 범위에서 적합하게 개인정보를 처리하여야 하며, 그 목적 외의 용도로 활용하여서는 아니 된다.","src":"개인정보 보호법 제3조 제2항 | 기출 2023-36"},{"t":"개인정보처리자는 처리 목적에 필요한 범위에서 개인정보의 정확성, 완전성 및 최신성이 보장되도록 하여야 한다.","src":"개인정보 보호법 제3조 제3항 | 기출 2023-36"},{"t":"개인정보처리자는 처리방법 및 종류 등에 따라 정보주체의 권리가 침해받을 가능성과 위험 정도를 고려하여 개인정보를 안전하게 관리하여야 한다.","src":"개인정보 보호법 제3조 제4항"},{"t":"개인정보처리자는 개인정보 처리방침 등 처리에 관한 사항을 공개하여야 하며, 열람청구권 등 정보주체의 권리를 보장하여야 한다.","src":"개인정보 보호법 제3조 제5항 | 기출 2023-36"},{"t":"개인정보처리자는 정보주체의 사생활 침해를 최소화하는 방법으로 개인정보를 처리하여야 한다.","src":"개인정보 보호법 제3조 제6항 | 기출 2023-36"},{"t":"개인정보를 익명 또는 가명으로 처리하여도 수집목적을 달성할 수 있는 경우, 익명처리가 가능하면 익명으로, 익명으로 목적을 달성할 수 없으면 가명으로 처리될 수 있도록 하여야 한다.","src":"개인정보 보호법 제3조 제7항 | 기출 2023-36"},{"t":"정보주체의 권리: 처리에 관한 정보를 제공받을 권리, 동의 여부·범위 등을 선택하고 결정할 권리, 처리 여부를 확인하고 열람(사본 발급 포함) 및 전송을 요구할 권리, 처리 정지·정정·삭제 및 파기를 요구할 권리, 처리로 인한 피해를 신속하고 공정한 절차에 따라 구제받을 권리, 완전히 자동화된 처리에 따른 결정을 거부하거나 설명 등을 요구할 권리.","src":"개인정보 보호법 제4조 | 기출 2022-36"},{"t":"개인정보처리자의 가명정보 처리에 동의할 권리는 정보주체의 권리로 규정되어 있지 않다.","src":"기출 2022-36"},{"t":"가명정보: 통계작성, 과학적 연구, 공익적 기록보존 등을 위하여 정보주체의 동의 없이 처리할 수 있다. 제3자에게 제공할 때 특정 개인을 알아보기 위하여 사용될 수 있는 정보를 포함해서는 아니 된다.","src":"개인정보 보호법 제28조의2"}]},{"머리":"개인정보의 수집·이용·제공","줄":[{"t":"개인정보 수집·이용이 가능한 경우: 정보주체의 동의, 법률 규정 또는 법령상 의무 준수를 위해 불가피한 경우, 공공기관의 법령상 소관 업무 수행을 위해 불가피한 경우, 계약 이행·체결 과정에서 정보주체 요청에 따른 조치를 위해 필요한 경우, 명백히 정보주체 또는 제3자의 급박한 생명·신체·재산 이익을 위해 필요한 경우, 개인정보처리자의 정당한 이익 달성을 위해 필요하고 명백하게 정보주체의 권리보다 우선하는 경우, 공중위생 등 공공의 안전과 안녕을 위하여 긴급히 필요한 경우.","src":"개인정보 보호법 제15조 제1항"},{"t":"동의를 받을 때 알릴 사항: 수집·이용 목적, 수집하려는 항목, 보유 및 이용 기간, 동의를 거부할 권리가 있다는 사실 및 거부에 따른 불이익이 있는 경우 그 내용.","src":"개인정보 보호법 제15조 제2항"},{"t":"제3자 제공 시 알릴 사항: 제공받는 자, 제공받는 자의 이용 목적, 제공하는 항목, 제공받는 자의 보유 및 이용 기간, 동의 거부권 및 불이익.","src":"개인정보 보호법 제17조 제2항"},{"t":"개인정보의 목적 외 이용·제공 허용 사유(정보주체 또는 제3자 이익을 부당하게 침해할 우려가 있을 때 제외): 정보주체의 별도 동의, 다른 법률에 특별한 규정, 급박한 생명·신체·재산 이익, 법령상 소관 업무 수행 불가 시 보호위원회 심의·의결(공공기관), 조약 이행, 범죄의 수사와 공소 제기·유지, 법원의 재판업무, 형 및 감호·보호처분의 집행, 공중위생 등 긴급.","src":"개인정보 보호법 제18조 제2항"},{"t":"민감정보: 사상·신념, 노동조합·정당의 가입·탈퇴, 정치적 견해, 건강, 성생활 등에 관한 정보. 정보주체에게 알리고 다른 개인정보 처리 동의와 별도로 동의를 받거나 법령에서 처리를 요구·허용하는 경우에만 처리할 수 있다.","src":"개인정보 보호법 제23조"},{"t":"고유식별정보: 정보주체에게 알리고 별도로 동의를 받거나 법령에서 구체적으로 처리를 요구·허용하는 경우에만 처리할 수 있고, 유출 등이 되지 않도록 암호화 등 안전성 확보 조치를 하여야 한다.","src":"개인정보 보호법 제24조"},{"t":"선택적으로 동의할 수 있는 사항에 동의하지 않는다는 이유로 재화 또는 서비스 제공을 거부하여서는 아니 된다.","src":"개인정보 보호법 제22조 제5항"},{"t":"만 14세 미만 아동의 법정대리인은 개인정보처리자에게 그 아동의 개인정보 열람 등 요구를 할 수 있다.","src":"개인정보 보호법 제38조 제2항"}]},{"머리":"영상정보처리기기","줄":[{"t":"고정형 영상정보처리기기를 공개된 장소에 설치·운영할 수 있는 경우: 법령에서 구체적으로 허용하고 있는 경우, 범죄의 예방 및 수사를 위하여 필요한 경우, 시설의 안전 및 관리·화재 예방을 위하여 정당한 권한을 가진 자가 설치·운영하는 경우, 교통단속을 위하여 정당한 권한을 가진 자가 설치·운영하는 경우, 교통정보의 수집·분석 및 제공을 위하여 정당한 권한을 가진 자가 설치·운영하는 경우, 촬영된 영상정보를 저장하지 아니하는 경우로서 대통령령으로 정하는 경우(출입자 수·성별·연령대 등 통계값 산출을 위한 일시 처리 등).","src":"개인정보 보호법 제25조 제1항 | 기출 2025-36"},{"t":"촬영 사실을 명확히 표시하여 정보주체가 촬영 사실을 알 수 있도록 하였음에도 촬영 거부 의사를 밝히지 아니한 경우는 이동형 영상정보처리기기의 촬영 허용 사유이고, 고정형 설치·운영 허용 사유가 아니다.","src":"개인정보 보호법 제25조의2 제1항 제2호 | 기출 2025-36"},{"t":"불특정 다수가 이용하는 목욕실, 화장실, 발한실, 탈의실 등 사생활을 현저히 침해할 우려가 있는 장소의 내부를 볼 수 있도록 고정형 영상정보처리기기를 설치·운영하여서는 아니 된다. 교도소·정신보건시설 등 대통령령으로 정하는 시설은 예외다.","src":"개인정보 보호법 제25조 제2항"},{"t":"고정형 영상정보처리기기운영자는 설치 목적 및 장소, 촬영 범위 및 시간, 관리책임자 연락처 등이 포함된 안내판을 설치하여야 하고, 설치 목적과 다른 목적으로 임의 조작하거나 다른 곳을 비춰서는 아니 되며, 녹음기능은 사용할 수 없다.","src":"개인정보 보호법 제25조 제4항·제5항"},{"t":"공공기관의 장이 고정형 영상정보처리기기를 설치·운영하려면 공청회·설명회의 개최 등 대통령령으로 정하는 절차를 거쳐 관계 전문가 및 이해관계인의 의견을 수렴하여야 한다.","src":"개인정보 보호법 제25조 제3항"}]},{"머리":"열람·정정·삭제·처리정지·유출·손해배상","줄":[{"t":"정보주체는 개인정보처리자가 처리하는 자신의 개인정보에 대한 열람을 요구할 수 있다. 열람 제한·거절 사유: 법률에 따라 열람이 금지·제한되는 경우, 다른 사람의 생명·신체를 해할 우려나 재산 등 이익을 부당하게 침해할 우려가 있는 경우, 공공기관의 조세 부과·징수, 학교 성적 평가·입학자 선발, 학력·기능·채용 시험, 보상금 산정 평가, 진행 중인 감사·조사 업무에 중대한 지장을 초래하는 경우.","src":"개인정보 보호법 제35조"},{"t":"열람한 정보주체는 정정 또는 삭제를 요구할 수 있다. 다른 법령에서 그 개인정보가 수집 대상으로 명시되어 있는 경우에는 삭제를 요구할 수 없다.","src":"개인정보 보호법 제36조 제1항"},{"t":"정보주체는 개인정보 처리의 정지를 요구하거나 동의를 철회할 수 있다.","src":"개인정보 보호법 제37조 제1항"},{"t":"개인정보 유출등을 알게 되었을 때 지체 없이 정보주체에게 유출된 항목, 시점과 경위, 피해 최소화 방법, 대응조치 및 피해 구제절차, 신고 접수 담당부서 및 연락처 등을 알려야 하며, 보호위원회 또는 전문기관에 신고하여야 한다.","src":"개인정보 보호법 제34조"},{"t":"정보주체가 개인정보처리자의 위반으로 손해를 입으면 손해배상을 청구할 수 있고, 개인정보처리자는 고의 또는 과실이 없음을 입증하지 아니하면 책임을 면할 수 없다.","src":"개인정보 보호법 제39조 제1항"},{"t":"개인정보처리자의 고의 또는 중대한 과실로 유출등이 된 경우 법원은 손해액의 5배를 넘지 않는 범위에서 손해배상액을 정할 수 있다.","src":"개인정보 보호법 제39조 제3항"},{"t":"개인정보 처리 업무를 위탁하는 경우 위탁업무 수행 목적 외 처리 금지, 기술적·관리적 보호조치 등을 포함한 문서로 하여야 하며, 위탁자는 수탁자를 교육하고 감독하여야 한다. 수탁자가 재위탁하려면 위탁자의 동의를 받아야 한다.","src":"개인정보 보호법 제26조"}]}],"함정":[{"x":"국내에 학술·연구를 위하여 일시적으로 체류하는 외국인은 정보공개를 청구할 권리가 없다.","o":"학술·연구를 위하여 일시적으로 체류하는 외국인은 정보공개를 청구할 수 있다.","src":"기출 2021-36 | 정보공개법 시행령 제3조"},{"x":"공개 청구한 정보가 비공개대상인 부분과 공개 가능한 부분이 혼합되어 있는 경우 부분 공개는 할 수 없다.","o":"분리할 수 있으면 비공개 부분을 제외하고 공개하여야 한다.","src":"기출 2021-36 | 정보공개법 제14조"},{"x":"사립대학교는 정보공개의무를 지는 공공기관에 해당하지 않는다.","o":"사립대학교도 정보공개의무를 지는 공공기관이다.","src":"기출 2021-36"},{"x":"청구인은 공공기관의 비공개 결정에 대하여 불복이 있는 경우 이의신청 절차를 거치지 아니하고는 행정심판을 청구할 수 없다.","o":"이의신청을 거치지 않고 행정심판을 청구할 수 있다.","src":"기출 2021-36 | 정보공개법 제19조 제2항"},{"x":"‘진행 중인 재판에 관련된 정보’에 해당한다는 사유로 정보공개를 거부하기 위하여는 반드시 그 정보가 진행 중인 재판의 소송기록 자체에 포함되어야 한다.","o":"소송기록 자체에 포함된 정보일 필요는 없다.","src":"기출 2021-37"},{"x":"정보공개 청구권자의 권리구제 가능성이 없는 경우에는 비공개 대상 정보에 해당하지 않는 정보라도 공개하지 않을 수 있다.","o":"비공개 대상에 해당하지 않으면 권리구제 가능성이 없어도 공개하여야 한다.","src":"기출 2022-38"},{"x":"개인정보처리자는 개인정보를 익명 또는 가명으로 처리하여서는 아니 된다.","o":"익명 또는 가명으로 처리해도 수집목적을 달성할 수 있으면 익명, 가명의 순으로 처리될 수 있도록 하여야 한다.","src":"기출 2023-36 | 개인정보 보호법 제3조 제7항"},{"x":"공개될 경우 부동산 투기, 매점매석 등으로 특정인에게 이익 또는 불이익을 줄 우려가 있다고 인정되는 정보라도 공공기관이 보유·관리하는 정보라면 이를 공개하여야 한다.","o":"이런 정보는 공개하지 아니할 수 있다(제9조 제1항 제8호).","src":"기출 2024-35"},{"x":"개인정보처리자의 가명정보 처리에 동의할 권리가 정보주체의 권리이다.","o":"가명정보 처리 동의권은 정보주체의 권리로 열거되어 있지 않다.","src":"기출 2022-36 | 개인정보 보호법 제4조"},{"x":"촬영 사실을 명확히 표시하여 정보주체가 촬영 사실을 알 수 있도록 하였음에도 촬영 거부 의사를 밝히지 아니한 경우에는 고정형 영상정보처리기기를 설치·운영할 수 있다.","o":"이 경우는 이동형 영상정보처리기기의 촬영 허용 사유이다.","src":"기출 2025-36"}]},"행정상 강제(행정대집행·이행강제금·직접강제·즉시강제)":{"묶음":[{"머리":"행정상 강제의 종류(행정기본법 제30조)","줄":[{"t":"행정대집행: 의무자가 타인이 대신하여 행할 수 있는 행정상 의무를 이행하지 아니하는 경우, 법률로 정하는 다른 수단으로는 이행 확보가 곤란하고 불이행을 방치하면 공익을 크게 해칠 것으로 인정될 때 행정청이 스스로 하거나 제3자에게 하게 하고 비용을 의무자로부터 징수하는 것.","src":"행정기본법 제30조 제1항 제1호"},{"t":"이행강제금의 부과: 의무자가 행정상 의무를 이행하지 아니하는 경우 행정청이 적절한 이행기간을 부여하고, 그 기한까지 이행하지 아니하면 금전급부의무를 부과하는 것.","src":"행정기본법 제30조 제1항 제2호"},{"t":"직접강제: 의무자가 행정상 의무를 이행하지 아니하는 경우 행정청이 의무자의 신체나 재산에 실력을 행사하여 그 행정상 의무의 이행이 있었던 것과 같은 상태를 실현하는 것.","src":"행정기본법 제30조 제1항 제3호 | 기출 2024-38"},{"t":"강제징수: 의무자가 금전급부의무를 이행하지 아니하는 경우 행정청이 의무자의 재산에 실력을 행사하여 그 의무가 실현된 것과 같은 상태를 실현하는 것.","src":"행정기본법 제30조 제1항 제4호"},{"t":"즉시강제: 현재의 급박한 행정상의 장해를 제거하기 위한 경우로서 행정청이 미리 의무 이행을 명할 시간적 여유가 없거나, 그 성질상 의무 이행을 명하는 것만으로는 행정목적 달성이 곤란한 경우에 곧바로 국민의 신체 또는 재산에 실력을 행사하여 행정목적을 달성하는 것.","src":"행정기본법 제30조 제1항 제5호"},{"t":"행정상 강제는 법률로 정하는 바에 따라 필요한 최소한의 범위에서 할 수 있다.","src":"행정기본법 제30조 제1항"},{"t":"형사, 행형 및 보안처분 관계 법령에 따라 행하는 사항이나 외국인의 출입국·난민인정·귀화·국적회복에 관한 사항에는 행정상 강제 규정(행정기본법 제5절)을 적용하지 아니한다.","src":"행정기본법 제30조 제3항 | 기출 2025-38"},{"t":"행정의무의 이행확보에 관하여서는 따로 법률로 정하는 것을 제외하고는 행정대집행법이 정하는 바에 의한다.","src":"행정대집행법 제1조"}]},{"머리":"대집행의 요건과 절차","줄":[{"t":"대집행 요건: 법률 또는 법률에 의거한 행정청의 명령에 의한 의무로서 타인이 대신하여 행할 수 있는 행위(대체적 작위의무)를 이행하지 아니하고, 다른 수단으로 이행 확보가 곤란하며, 불이행을 방치함이 심히 공익을 해칠 것으로 인정될 때.","src":"행정대집행법 제2조"},{"t":"1단계 계고: 상당한 이행기한을 정하여 그 기한까지 이행되지 아니할 때에는 대집행을 한다는 뜻을 미리 문서로 계고하여야 한다. 의무의 성질·내용 등을 고려하여 사회통념상 필요한 기간이 확보되도록 하여야 한다.","src":"행정대집행법 제3조 제1항"},{"t":"2단계 대집행영장 통지: 계고 후에도 이행하지 않으면 대집행영장으로 대집행을 할 시기, 집행책임자의 성명, 대집행에 요하는 비용의 개산에 의한 견적액을 의무자에게 통지한다.","src":"행정대집행법 제3조 제2항"},{"t":"비상시 또는 위험이 절박한 경우 급속한 실시를 요하여 계고·영장 절차를 취할 여유가 없을 때에는 그 절차를 거치지 않고 대집행을 할 수 있다.","src":"행정대집행법 제3조 제3항"},{"t":"철거명령과 계고처분은 계고서라는 명칭의 1장의 문서로 이루어질 수 있다.","src":"기출 2021-38"},{"t":"철거대집행 계고처분 후 행한 제2차 계고는 대집행기한의 연기통지에 불과하고 새로운 철거의무를 부과한 것이 아니다.","src":"기출 2021-38"},{"t":"대집행의 주체는 행정청이다. 행정청은 스스로 하거나 제3자로 하여금 하게 할 수 있다. 처분청 스스로만 하여야 하는 것이 아니다.","src":"행정대집행법 제2조 | 기출 2021-38 | 기출 2022-37"},{"t":"대집행영장에 의한 통지는 취소소송의 대상이 된다.","src":"기출 2022-37"},{"t":"계고처분의 후속절차인 대집행에 위법이 있더라도 그 후속절차의 위법을 이유로 선행절차인 계고처분이 부적법하다고 할 수 없다.","src":"기출 2022-37"},{"t":"후행처분인 대집행영장발부통보처분의 취소소송에서 선행처분인 계고처분의 위법을 이유로 대집행영장발부통보처분이 위법하다는 주장을 할 수 있다(하자의 승계).","src":"기출 2021-38"},{"t":"행정청이 대집행의 방법으로 건물철거의무의 이행을 실현할 수 있는 경우, 건물철거 대집행 과정에서 부수적으로 건물 점유자들에 대한 퇴거 조치를 할 수 있다.","src":"기출 2021-38"}]},{"머리":"대집행 실행과 비용징수","줄":[{"t":"행정청(대집행을 실행하는 제3자 포함)은 해가 뜨기 전이나 해가 진 후에는 대집행을 하여서는 아니 된다.","src":"행정대집행법 제4조 제1항"},{"t":"야간 대집행 예외: 의무자가 동의한 경우, 해가 지기 전에 대집행을 착수한 경우, 해가 뜬 후부터 해가 지기 전까지 대집행하면 목적 달성이 불가능한 경우, 그 밖에 비상시 또는 위험이 절박한 경우.","src":"행정대집행법 제4조 제1항 | 기출 2023-37 | 기출 2025-37"},{"t":"행정청은 대집행 과정에서의 안전 확보를 위하여 필요하다고 인정하는 경우 현장에 긴급 의료장비나 시설을 갖추는 등 필요한 조치를 하여야 한다.","src":"행정대집행법 제4조 제2항"},{"t":"현장에 파견되는 집행책임자는 집행책임자라는 것을 표시한 증표를 휴대하여 대집행시에 이해관계인에게 제시하여야 한다.","src":"행정대집행법 제4조 제3항"},{"t":"비용 징수: 실제에 요한 비용액과 납기일을 정하여 의무자에게 문서로 납부를 명하여야 한다.","src":"행정대집행법 제5조"},{"t":"대집행에 요한 비용은 국세징수법의 예에 의하여 징수할 수 있다.","src":"행정대집행법 제6조 제1항 | 기출 2025-37"},{"t":"대집행에 요한 비용에 대하여 행정청은 사무비의 소속에 따라 국세에 다음가는 순위의 선취득권을 가진다.","src":"행정대집행법 제6조 제2항 | 기출 2023-37 | 기출 2025-37"},{"t":"비용을 징수하였을 때 그 징수금은 사무비의 소속에 따라 국고 또는 지방자치단체의 수입으로 한다.","src":"행정대집행법 제6조 제3항"},{"t":"대집행에 대하여는 행정심판을 제기할 수 있다. 이는 법원에 대한 출소의 권리를 방해하지 아니한다.","src":"행정대집행법 제7조·제8조 | 기출 2022-37 | 기출 2023-37 | 기출 2025-37"}]},{"머리":"이행강제금","줄":[{"t":"이행강제금 부과의 근거 법률에 명확히 규정할 사항: 부과·징수 주체, 부과 요건, 부과 금액, 부과 금액 산정기준, 연간 부과 횟수나 횟수의 상한. 제4호·제5호는 입법목적을 훼손할 우려가 큰 경우로서 대통령령으로 정하는 경우 제외.","src":"행정기본법 제31조 제1항"},{"t":"부과 금액 가중·감경 고려사항: 의무 불이행의 동기·목적 및 결과, 의무 불이행의 정도 및 상습성, 그 밖에 행정목적 달성에 필요하다고 인정되는 사유.","src":"행정기본법 제31조 제2항 | 기출 2025-38"},{"t":"이행강제금을 부과하기 전에 미리 의무자에게 적절한 이행기간을 정하여 그 기한까지 이행하지 아니하면 이행강제금을 부과한다는 뜻을 문서로 계고하여야 한다.","src":"행정기본법 제31조 제3항 | 기출 2025-38"},{"t":"계고에서 정한 기한까지 이행하지 않은 경우 이행강제금의 부과 금액·사유·시기를 문서로 명확하게 적어 통지하여야 한다.","src":"행정기본법 제31조 제4항"},{"t":"의무를 이행할 때까지 반복하여 부과할 수 있다. 의무자가 의무를 이행하면 새로운 이행강제금의 부과를 즉시 중지하되, 이미 부과한 이행강제금은 징수하여야 한다.","src":"행정기본법 제31조 제5항"},{"t":"이행강제금을 납부기한까지 내지 아니하면 국세강제징수의 예 또는 「지방행정제재·부과금의 징수 등에 관한 법률」에 따라 징수한다.","src":"행정기본법 제31조 제6항 | 기출 2025-38"},{"t":"이행강제금 부과처분은 항고소송의 대상이 되는 처분이다. 건축법상 이행강제금도 같다.","src":"기출 2021-39"},{"t":"이행강제금은 대체적 작위의무의 위반에 대하여도 부과할 수 있다.","src":"기출 2021-39 | 보충"},{"t":"건축법상 이행강제금의 납부의무는 상속인에게 승계될 수 없는 일신전속적인 성질의 것이다.","src":"기출 2021-39"},{"t":"병무청장이 병역법에 따라 병역의무 기피자의 인적사항을 인터넷 홈페이지에 공개하는 결정은 항고소송의 대상이 되는 행정처분이다.","src":"기출 2021-39"}]},{"머리":"직접강제와 즉시강제","줄":[{"t":"직접강제는 행정대집행이나 이행강제금 부과의 방법으로는 행정상 의무 이행을 확보할 수 없거나 그 실현이 불가능한 경우에 실시하여야 한다.","src":"행정기본법 제32조 제1항"},{"t":"직접강제를 실시하기 위하여 현장에 파견되는 집행책임자는 집행책임자임을 표시하는 증표를 보여 주어야 한다. 직접강제의 계고 및 통지에는 이행강제금의 계고·통지 규정을 준용한다.","src":"행정기본법 제32조 제2항·제3항"},{"t":"즉시강제는 다른 수단으로는 행정목적을 달성할 수 없는 경우에만 허용되며, 이 경우에도 최소한으로만 실시하여야 한다.","src":"행정기본법 제33조 제1항 | 기출 2025-38"},{"t":"즉시강제 집행책임자는 증표를 보여 주고 즉시강제의 이유와 내용을 고지하여야 한다.","src":"행정기본법 제33조 제2항"},{"t":"재산의 소유자·점유자를 알 수 없거나 현장에서 소재를 즉시 확인하기 어려운 경우 즉시강제를 실시한 후 집행책임자의 이름 및 이유와 내용을 고지할 수 있다. 소유자·점유자를 알 수 없는 경우, 국외 거주나 행방불명 등인 경우에는 게시판이나 인터넷 홈페이지 게시 등 공고로 고지를 갈음할 수 있다.","src":"행정기본법 제33조 제3항"}]}],"함정":[{"x":"철거대집행 계고처분 후 행한 제2차 계고는 대집행기한의 연기통지가 아니라 새로운 철거의무를 부과한 것이다.","o":"제2차 계고는 대집행기한의 연기통지에 불과하다.","src":"기출 2021-38"},{"x":"대집행은 처분청 스스로 하여야 하며, 대집행 권한을 제3자에게 위임·위탁할 수 없다.","o":"행정청이 스스로 하거나 제3자로 하여금 하게 할 수 있다.","src":"기출 2021-38 | 기출 2022-37"},{"x":"후행처분인 대집행영장발부통보처분의 취소소송에서, 선행처분인 계고처분의 위법을 이유로 대집행영장발부통보처분이 위법하다는 주장을 할 수 없다.","o":"하자의 승계가 인정되어 주장할 수 있다.","src":"기출 2021-38"},{"x":"행정청이 대집행의 방법으로 건물철거의무의 이행을 실현할 수 있는 경우, 건물철거 대집행 과정에서 부수적으로 건물의 점유자들에 대한 퇴거 조치를 할 수 없다.","o":"부수적으로 점유자들에 대한 퇴거 조치를 할 수 있다.","src":"기출 2021-38"},{"x":"건축법상 이행강제금 부과처분은 항고소송으로 다툴 수는 없다.","o":"이행강제금 부과처분은 항고소송의 대상이다.","src":"기출 2021-39"},{"x":"이행강제금은 대체적 작위의무의 위반에 대하여 부과될 수 없다.","o":"대체적 작위의무 위반에도 이행강제금을 부과할 수 있다.","src":"기출 2021-39"},{"x":"대집행에 요한 비용은 국세징수법의 예에 의하여 징수할 수 없다.","o":"국세징수법의 예에 의하여 징수할 수 있다.","src":"기출 2021-39 | 행정대집행법 제6조"},{"x":"병무청장이 병역법에 따라 병역의무 기피자의 인적사항을 인터넷 홈페이지에 공개하는 결정은 항고소송의 대상이 되는 행정처분이 아니다.","o":"항고소송의 대상이 되는 처분이다.","src":"기출 2021-39"},{"x":"의무자가 동의한 경우라도 행정청은 해가 뜨기 전에는 대집행을 착수할 수 없다.","o":"의무자가 동의한 경우에는 해가 뜨기 전에도 대집행을 할 수 있다.","src":"기출 2023-37 | 기출 2025-37"},{"x":"해가 지기 전에 대집행을 착수한 경우라도 해가 진 후에는 행정청은 즉시 대집행을 중단해야 한다.","o":"해가 지기 전에 착수한 경우에는 해가 진 후에도 대집행을 계속할 수 있다.","src":"기출 2023-37 | 기출 2025-37"},{"x":"대집행에 대하여는 행정심판을 제기할 수 없다.","o":"행정심판을 제기할 수 있다.","src":"기출 2023-37 | 행정대집행법 제7조"},{"x":"대집행에 요한 비용은 「민사집행법」의 예에 의하여 징수하여야 한다.","o":"국세징수법의 예에 의하여 징수할 수 있다.","src":"기출 2023-37"},{"x":"대집행은 대집행의 대상이 되는 의무를 명하는 처분청이 그 주체가 되며 타인에게 위탁할 수 없다.","o":"타인(제3자)으로 하여금 하게 할 수 있다.","src":"기출 2022-37"},{"x":"직접강제는 다른 모든 수단으로는 행정목적을 달성할 수 없는 경우에만 허용되며, 이 경우에도 최소한으로만 실시하여야 한다.","o":"이는 즉시강제의 요건이다. 직접강제는 대집행이나 이행강제금으로 이행 확보가 불가능하거나 실현이 불가능한 경우에 실시한다.","src":"기출 2025-38 | 행정기본법 제32조·제33조"}]},"행정벌과 새로운 의무이행확보수단(과징금 등)":{"묶음":[{"머리":"행정형벌과 행정질서벌","줄":[{"t":"행정형벌: 행정법상 의무 위반에 대해 형법상 형명(사형·징역·금고·벌금·구류·과료·몰수)이 있는 벌을 과하는 것. 행정질서벌: 과태료를 과하는 것.","src":"보충"},{"t":"행정형벌에는 원칙적으로 형법총칙이 적용되고, 형사소송절차에 따라 법원이 부과한다. 과태료는 질서위반행위규제법과 비송사건절차에 따른다.","src":"보충"},{"t":"행정법규 위반에 대해 벌금 이외에 과징금을 부과하는 것은 이중처벌금지의 원칙에 반하지 않는다.","src":"기출 2022-39"},{"t":"양벌규정: 법인의 대표자·대리인·사용인·종업원이 업무에 관하여 위반행위를 한 경우 행위자 외에 법인 또는 개인에게도 벌금형을 과하는 규정이다.","src":"보충"}]},{"머리":"질서위반행위규제법: 성립요건","줄":[{"t":"질서위반행위: 법률(지방자치단체의 조례 포함)상의 의무를 위반하여 과태료를 부과하는 행위. 대통령령으로 정하는 사법상·소송법상 의무 위반이나 징계사유에 해당하는 행위는 제외.","src":"질서위반행위규제법 제2조 제1호"},{"t":"법률에 따르지 아니하고는 어떤 행위도 질서위반행위로 과태료를 부과하지 아니한다(법정주의).","src":"질서위반행위규제법 제6조 | 기출 2023-38"},{"t":"고의 또는 과실이 없는 질서위반행위는 과태료를 부과하지 아니한다.","src":"질서위반행위규제법 제7조 | 기출 2023-38"},{"t":"자신의 행위가 위법하지 아니한 것으로 오인하고 행한 질서위반행위는 그 오인에 정당한 이유가 있는 때에 한하여 과태료를 부과하지 아니한다.","src":"질서위반행위규제법 제8조"},{"t":"14세가 되지 아니한 자의 질서위반행위는 다른 법률에 특별한 규정이 있는 경우를 제외하고는 과태료를 부과하지 아니한다.","src":"질서위반행위규제법 제9조 | 기출 2023-38"},{"t":"심신장애로 판단·행위 능력이 없는 자의 행위는 과태료를 부과하지 아니하고, 능력이 미약한 자의 행위는 과태료를 감경한다. 스스로 심신장애 상태를 일으킨 경우에는 적용하지 아니한다.","src":"질서위반행위규제법 제10조"},{"t":"법인의 대표자, 법인 또는 개인의 대리인·사용인 및 그 밖의 종업원이 업무에 관하여 법률상의 의무를 위반한 때에는 법인 또는 그 개인에게 과태료를 부과한다.","src":"질서위반행위규제법 제11조 제1항"},{"t":"2인 이상이 질서위반행위에 가담한 때에는 각자가 질서위반행위를 한 것으로 본다. 신분에 의하여 성립하는 질서위반행위에 신분이 없는 자가 가담한 때에도 신분이 없는 자에 대하여 질서위반행위가 성립한다. 신분에 의하여 과태료를 감경·가중하거나 부과하지 않는 경우 그 신분의 효과는 신분이 없는 자에게 미치지 않는다.","src":"질서위반행위규제법 제12조 | 기출 2024-37"},{"t":"하나의 행위가 2 이상의 질서위반행위에 해당하는 경우에는 각 질서위반행위에 대하여 정한 과태료 중 가장 중한 과태료를 부과한다. 그 외 2 이상의 질서위반행위가 경합하면 각각 부과한다.","src":"질서위반행위규제법 제13조 | 기출 2024-37"},{"t":"과태료 산정 시 고려사항: 질서위반행위의 동기·목적·방법·결과, 위반 이후 당사자의 태도와 정황, 당사자의 연령·재산상태·환경, 그 밖에 필요하다고 인정되는 사유.","src":"질서위반행위규제법 제14조"}]},{"머리":"질서위반행위규제법: 적용 범위","줄":[{"t":"질서위반행위의 성립과 과태료 처분은 행위 시의 법률에 따른다. 행위 후 법률이 변경되어 질서위반행위에 해당하지 아니하게 되거나 과태료가 변경 전보다 가볍게 된 때에는 특별한 규정이 없는 한 변경된 법률을 적용한다.","src":"질서위반행위규제법 제3조 제1항·제2항 | 기출 2024-37"},{"t":"과태료 처분이나 재판이 확정된 후 법률이 변경되어 질서위반행위에 해당하지 아니하게 된 때에는 특별한 규정이 없는 한 과태료의 징수 또는 집행을 면제한다.","src":"질서위반행위규제법 제3조 제3항"},{"t":"대한민국 영역 안에서 질서위반행위를 한 자, 영역 밖에서 질서위반행위를 한 대한민국 국민, 영역 밖에 있는 대한민국의 선박 또는 항공기 안에서 질서위반행위를 한 외국인에게 적용한다.","src":"질서위반행위규제법 제4조 | 기출 2023-38 | 기출 2024-37"}]},{"머리":"과태료의 부과·징수·재판","줄":[{"t":"과태료를 부과하려는 때에는 미리 당사자에게 통지하고, 10일 이상의 기간을 정하여 의견을 제출할 기회를 주어야 한다. 기일까지 의견 제출이 없으면 의견이 없는 것으로 본다.","src":"질서위반행위규제법 제16조"},{"t":"행정청은 의견 제출 절차를 마친 후 서면(당사자 동의 시 전자문서)으로 과태료를 부과하여야 한다.","src":"질서위반행위규제법 제17조"},{"t":"의견 제출 기한 이내에 자진 납부하려는 경우 과태료를 감경할 수 있고, 감경된 과태료를 납부하면 부과 및 징수절차는 종료한다.","src":"질서위반행위규제법 제18조"},{"t":"행정청은 질서위반행위가 종료된 날(다수인 가담 시 최종행위 종료일)부터 5년이 경과하면 과태료를 부과할 수 없다.","src":"질서위반행위규제법 제19조 제1항"},{"t":"행정청의 과태료 부과에 불복하는 당사자는 부과 통지를 받은 날부터 60일 이내에 해당 행정청에 서면으로 이의제기를 할 수 있다. 이의제기가 있으면 행정청의 과태료 부과처분은 효력을 상실한다.","src":"질서위반행위규제법 제20조"},{"t":"이의제기를 받은 행정청은 14일 이내에 의견 및 증빙서류를 첨부하여 관할 법원에 통보하여야 한다. 이의제기가 철회되거나 이유 있어 과태료를 부과할 필요가 없다고 인정되는 경우는 제외.","src":"질서위반행위규제법 제21조"},{"t":"과태료 사건은 당사자의 주소지의 지방법원 또는 그 지원의 관할로 한다.","src":"질서위반행위규제법 제25조"},{"t":"납부기한까지 과태료를 납부하지 아니한 때 납부기한을 경과한 날부터 체납된 과태료의 100분의 3에 상당하는 가산금을 징수하고, 매 1개월이 경과할 때마다 1천분의 12에 상당하는 중가산금을 가산하며 중가산금은 60개월을 초과하지 못한다.","src":"질서위반행위규제법 제24조"},{"t":"과태료는 부과처분이나 재판이 확정된 후 5년간 징수하지 아니하거나 집행하지 아니하면 시효로 소멸한다.","src":"질서위반행위규제법 제15조"},{"t":"과태료 재판은 검사의 명령으로써 집행한다.","src":"질서위반행위규제법 제42조 | 기출 2024-37"}]},{"머리":"과징금","줄":[{"t":"과징금: 행정청은 법령등에 따른 의무를 위반한 자에 대하여 법률로 정하는 바에 따라 그 위반행위에 대한 제재로서 과징금을 부과할 수 있다.","src":"행정기본법 제28조 제1항"},{"t":"과징금 근거 법률에 명확히 규정할 사항: 부과·징수 주체, 부과 사유, 상한액, 가산금을 징수하려는 경우 그 사항, 과징금 또는 가산금 체납 시 강제징수를 하려는 경우 그 사항.","src":"행정기본법 제28조 제2항"},{"t":"과징금은 한꺼번에 납부하는 것이 원칙이다. 재해 등으로 재산에 현저한 손실을 입은 경우, 사업 여건 악화로 사업이 중대한 위기에 처한 경우, 한꺼번에 내면 자금 사정에 현저한 어려움이 예상되는 경우, 그 밖에 이에 준하는 경우 납부기한을 연기하거나 분할 납부하게 할 수 있고, 필요하면 담보를 제공하게 할 수 있다.","src":"행정기본법 제29조"},{"t":"제재적 행정처분으로서의 과징금은 현실적인 행위자가 아닌 법령상 책임자에게 부과할 수 있다.","src":"기출 2022-39"},{"t":"과징금은 국가의 형벌권을 실행하는 과벌이 아니다.","src":"기출 2022-39"},{"t":"제재적 행정처분으로서의 과징금은 원칙적으로 위반자의 고의 또는 과실을 요하지 않는다.","src":"기출 2022-39 | 보충"},{"t":"법령으로 정한 ‘과징금을 부과하는 위반행위와 과징금의 금액’에 열거되지 않은 위반행위에 대해 사업정지처분을 갈음하여 과징금을 부과할 수 없다.","src":"기출 2022-39"},{"t":"과징금 부과처분에서 법령상 감경사유가 있는 경우 이를 전혀 고려하지 않으면 위법하다.","src":"기출 2021-29"},{"t":"변상금(국유재산법): 무단점유자에 대하여 사용료나 대부료의 100분의 120에 상당하는 금액을 징수한다.","src":"국유재산법 제72조 제1항"}]},{"머리":"그 밖의 이행확보수단","줄":[{"t":"위반사실 등의 공표: 법률로 정하는 바에 따라 의무를 위반한 자의 성명·법인명, 위반사실 등을 일반에게 공표하는 수단이다. 공표 전에 증거와 근거를 확인하고 당사자에게 통지하여 의견제출 기회를 주어야 한다.","src":"행정절차법 제40조의3"},{"t":"병역의무 기피자 인적사항 공개 결정은 항고소송의 대상이 되는 처분이다.","src":"기출 2021-39"},{"t":"관허사업의 제한, 공급 거부, 시정명령 등도 행정의 실효성 확보 수단으로 사용된다. 법률의 근거가 있어야 한다.","src":"보충"}]}],"함정":[{"x":"제재적 행정처분으로서의 과징금은 원칙적으로 위반자의 고의 또는 과실을 요한다.","o":"제재적 행정처분으로서의 과징금은 원칙적으로 고의·과실을 요하지 않는다.","src":"기출 2022-39 | 보충"},{"x":"다른 법률에 특별한 규정이 없는 한 14세가 되지 아니한 자의 질서위반행위에 대해서도 과태료를 부과한다.","o":"14세가 되지 아니한 자의 질서위반행위에는 과태료를 부과하지 아니한다(다른 법률에 특별한 규정이 있으면 예외).","src":"기출 2023-38 | 질서위반행위규제법 제9조"},{"x":"신분에 의하여 성립하는 질서위반행위에 신분이 없는 자가 가담한 때에는 신분이 없는 자에 대하여는 질서위반행위가 성립하지 아니한다.","o":"신분이 없는 자에 대하여도 질서위반행위가 성립한다.","src":"기출 2024-37 | 질서위반행위규제법 제12조 제2항"}]},"국가배상":{"묶음":[{"머리":"국가배상책임의 요건(제2조)","줄":[{"t":"국가나 지방자치단체는 공무원 또는 공무를 위탁받은 사인이 직무를 집행하면서 고의 또는 과실로 법령을 위반하여 타인에게 손해를 입히거나 자동차손해배상 보장법에 따라 손해배상의 책임이 있을 때 이 법에 따라 배상하여야 한다.","src":"국가배상법 제2조 제1항"},{"t":"공무를 위탁받은 사인의 직무집행행위에 대해서도 국가배상책임이 성립할 수 있다.","src":"국가배상법 제2조 제1항 | 기출 2022-43"},{"t":"국가배상법 제2조의 직무행위에는 입법작용과 사법작용이 포함된다.","src":"기출 2024-39"},{"t":"인사업무담당 공무원이 다른 공무원의 공무원증을 위조한 행위는 직무집행행위에 해당한다(외형상 직무행위).","src":"기출 2023-42"},{"t":"경찰관이 범죄수사를 함에 있어 법규상 또는 조리상의 한계를 위반하였다면 이는 법령을 위반한 경우에 해당한다.","src":"기출 2023-42"},{"t":"행정지도와 같은 비권력적 작용도 국가배상법상 공무원의 직무에 포함된다.","src":"기출 2025-33"},{"t":"부작위에 의한 국가배상책임의 성립요건인 직무상 작위의무는 조리에 의해서도 성립할 수 있다.","src":"기출 2024-39"},{"t":"가해행위인 처분에 대해 취소판결이 확정되더라도 기판력에 의해 국가배상책임이 인정되는 것은 아니다. 처분이 항고소송에서 취소되었다고 공무원의 고의·과실 여부와 관계없이 곧바로 불법행위를 구성하지 않는다.","src":"기출 2022-43 | 기출 2023-42"},{"t":"국가가 배상책임을 이행한 경우 공무원에게 고의 또는 중대한 과실이 있으면 그 공무원에게 구상할 수 있다. 경과실에는 구상할 수 없다.","src":"국가배상법 제2조 제2항 | 기출 2024-39"},{"t":"국가배상법은 민법 제756조 제1항 단서의 사용자 면책조항에 상응하는 규정을 두고 있지 않다.","src":"기출 2024-39"}]},{"머리":"군인 등 이중배상금지(제2조 제1항 단서)","줄":[{"t":"피해자가 군인·군무원·경찰공무원 또는 예비군대원이어야 한다.","src":"국가배상법 제2조 제1항 단서 | 기출 2021-46"},{"t":"전투·훈련 등 직무 집행과 관련하여 전사·순직하거나 공상을 입은 손해에 한한다. 본인이나 유족이 다른 법령에 따라 재해보상금·유족연금·상이연금 등의 보상을 지급받을 수 있을 때 이 법 및 민법에 따른 손해배상을 청구할 수 없다.","src":"국가배상법 제2조 제1항 단서 | 기출 2021-46"},{"t":"전투·훈련 또는 이에 준하는 직무집행뿐 아니라 일반 직무집행에 관하여도 적용된다.","src":"기출 2021-46"},{"t":"전사하거나 순직한 군인·군무원·경찰공무원 또는 예비군대원의 유족은 자신의 정신적 고통에 대한 위자료를 청구할 수 있다.","src":"국가배상법 제2조 제3항"},{"t":"병역법상 공익근무요원은 군인에 해당하지 아니하여 이중배상이 금지되는 자에 속하지 않는다.","src":"기출 2021-46"},{"t":"전투훈련 중 민간인이 군인과 공동불법행위를 한 경우 민간인은 자신의 부담 부분만을 피해 군인에게 배상하면 된다(대법원 전원합의체 판례).","src":"기출 2021-46"}]},{"머리":"영조물 설치·관리상 하자(제5조)","줄":[{"t":"도로·하천, 그 밖의 공공의 영조물의 설치나 관리에 하자가 있기 때문에 타인에게 손해를 발생하게 하였을 때 국가나 지방자치단체는 그 손해를 배상하여야 한다.","src":"국가배상법 제5조 제1항"},{"t":"영조물 설치·관리상의 하자는 공공의 목적에 공여된 영조물이 그 용도에 따라 통상 갖추어야 할 안전성을 갖추지 못한 상태에 있음을 말한다.","src":"기출 2023-42"},{"t":"공공의 영조물에는 행정주체가 적법한 권한에 기하여 관리하고 있는 공물뿐 아니라 사실상 관리하고 있는 공물도 포함된다.","src":"기출 2024-39"},{"t":"손해의 원인에 대하여 책임을 질 자가 따로 있으면 국가나 지방자치단체는 그 자에게 구상할 수 있다.","src":"국가배상법 제5조 제2항"},{"t":"제5조 제1항에도 제2조 제1항 단서(군인 등), 제3조(배상기준), 제3조의2(공제액)가 준용된다.","src":"국가배상법 제5조 제1항"}]},{"머리":"배상의 범위·권리","줄":[{"t":"사망 시 유족배상: 사망 당시의 월급액이나 월실수입액 또는 평균임금에 장래의 취업가능기간을 곱한 금액 및 대통령령으로 정하는 장례비.","src":"국가배상법 제3조 제1항"},{"t":"신체 침해 시: 요양비, 요양기간 중 손실액의 휴업배상, 완치 후 장해가 있는 경우 노동력 상실 정도에 따른 장해배상.","src":"국가배상법 제3조 제2항"},{"t":"물건 멸실·훼손 시: 교환가액 또는 수리비, 수리기간 중 손실액의 휴업배상.","src":"국가배상법 제3조 제3항"},{"t":"생명·신체에 대한 침해와 물건의 멸실·훼손 외의 손해는 불법행위와 상당한 인과관계가 있는 범위에서 배상한다.","src":"국가배상법 제3조 제4항"},{"t":"피해자가 손해를 입은 동시에 이익을 얻은 경우 손해배상액에서 그 이익에 상당하는 금액을 뺀다. 유족배상·장해배상·장래 요양비 등을 한꺼번에 신청하는 경우 중간이자를 뺀다.","src":"국가배상법 제3조의2"},{"t":"생명·신체의 침해로 인한 국가배상을 받을 권리는 양도하거나 압류하지 못한다.","src":"국가배상법 제4조 | 기출 2022-43 | 기출 2023-42"},{"t":"공무원의 선임·감독 또는 영조물의 설치·관리를 맡은 자와 비용을 부담하는 자가 다르면 비용부담자도 배상책임을 진다. 손해를 배상한 자는 내부관계에서 책임 있는 자에게 구상할 수 있다.","src":"국가배상법 제6조"},{"t":"외국인이 피해자인 경우에는 해당 국가와 상호 보증이 있을 때에만 국가배상법이 적용된다.","src":"국가배상법 제7조 | 기출 2022-43"},{"t":"국가나 지방자치단체의 손해배상책임에 관하여 국가배상법에 규정된 사항 외에는 민법에 따른다. 민법 외의 법률에 다른 규정이 있으면 그 규정에 따른다.","src":"국가배상법 제8조"},{"t":"손해배상 소송은 배상심의회에 배상신청을 하지 아니하고도 제기할 수 있다.","src":"국가배상법 제9조"},{"t":"피해자나 그 법정대리인이 손해 및 가해자를 알지 못한 경우 국가배상청구권의 소멸시효 기간은 5년이다.","src":"기출 2022-43"},{"t":"배상심의회: 법무부에 본부심의회, 국방부에 군인·군무원 손해에 대한 특별심의회, 지구심의회를 둔다. 지구심의회는 배상신청을 받으면 4주일 이내에 배상결정을 하고, 결정을 한 날부터 1주일 이내에 결정정본을 신청인에게 송달한다.","src":"국가배상법 제10조·제13조·제14조"}]}],"함정":[{"x":"병역법상 공익근무요원은 군인에 해당하여 이중배상이 금지되는 자에 속한다.","o":"공익근무요원은 군인에 해당하지 않아 이중배상금지 대상이 아니다.","src":"기출 2021-46"},{"x":"가해행위인 처분에 대해 취소판결이 확정된 경우에는 기판력에 의해 국가배상소송에서도 국가배상책임이 인정된다.","o":"취소판결의 기판력은 국가배상소송에 미치지 않는다. 공무원의 고의·과실을 별도로 판단한다.","src":"기출 2022-43"},{"x":"행정처분이 후에 항고소송에서 취소되면 그 기판력에 의하여 당해 행정처분은 공무원의 고의·과실 여부와 관계없이 곧바로 불법행위를 구성한다.","o":"처분이 취소되었다고 곧바로 불법행위가 되는 것이 아니다.","src":"기출 2023-42"},{"x":"국가가 국가배상책임을 이행한 경우 공무원에게 경과실이 있으면 국가는 그 공무원에게 구상할 수 있다.","o":"고의 또는 중대한 과실이 있는 경우에만 구상할 수 있다.","src":"기출 2024-39 | 국가배상법 제2조 제2항"}]},"손실보상":{"묶음":[{"머리":"사업인정","줄":[{"t":"토지등을 수용하거나 사용할 수 있는 공익사업: 국방·군사, 철도·도로 등 허가·인가·승인·지정을 받은 공익사업, 국가·지방자치단체가 설치하는 공공용 시설, 학교·도서관·박물관·미술관 건립, 공공기관 등이 임대·양도 목적으로 시행하는 주택 건설·택지·산업단지 조성, 부속시설 사업, 이주단지 조성, 별표 법률의 사업.","src":"토지보상법 제4조"},{"t":"사업시행자는 토지등을 수용하거나 사용하려면 국토교통부장관의 사업인정을 받아야 한다.","src":"토지보상법 제20조"},{"t":"국토교통부장관은 사업인정을 하려면 관계 중앙행정기관의 장, 시·도지사 및 중앙토지수용위원회와 협의하고 사업인정에 이해관계가 있는 자의 의견을 들어야 한다.","src":"토지보상법 제21조"},{"t":"국토교통부장관은 사업인정을 하였을 때 지체 없이 사업시행자, 토지소유자 및 관계인, 관계 시·도지사에게 통지하고 사업시행자의 성명이나 명칭, 사업의 종류, 사업지역 및 수용·사용할 토지의 세목을 관보에 고시하여야 한다.","src":"토지보상법 제22조 제1항"},{"t":"사업인정은 고시한 날부터 그 효력이 발생한다.","src":"토지보상법 제22조 제3항 | 기출 2024-50"},{"t":"사업인정은 항고소송의 대상이 되는 처분이다.","src":"기출 2024-50"},{"t":"사업인정고시가 된 날부터 1년 이내에 재결신청을 하지 아니하면 사업인정고시일부터 1년이 되는 날의 다음 날에 사업인정은 효력을 상실한다. 이때 사업시행자는 토지소유자나 관계인이 입은 손실을 보상하여야 한다.","src":"토지보상법 제23조"},{"t":"사업인정고시 후 사업의 전부 또는 일부를 폐지·변경함으로써 수용·사용할 필요가 없게 된 때에는 사업시행자는 지체 없이 시·도지사에게 신고하고 토지소유자 및 관계인에게 통지하여야 하며, 손실을 보상하여야 한다.","src":"토지보상법 제24조"},{"t":"사업인정에 불가쟁력이 발생한 경우 사업인정이 당연무효가 아닌 한 사업인정의 하자를 이유로 수용재결의 취소를 구할 수 없다.","src":"기출 2024-50"},{"t":"사업인정처분이 당연무효이면 그것이 유효함을 전제로 이루어진 수용재결도 무효이다.","src":"기출 2021-45"}]},{"머리":"재결","줄":[{"t":"협의가 성립되지 아니하거나 협의를 할 수 없을 때 사업시행자는 사업인정고시가 된 날부터 1년 이내에 관할 토지수용위원회에 재결을 신청할 수 있다.","src":"토지보상법 제28조 제1항"},{"t":"사업인정고시 후 협의가 성립되지 아니하였을 때 토지소유자와 관계인은 서면으로 사업시행자에게 재결 신청을 청구할 수 있다. 사업시행자는 청구를 받은 날부터 60일 이내에 재결을 신청하여야 하고, 기간을 넘기면 지연된 기간에 대해 법정이율로 산정한 금액을 재결한 보상금에 가산하여 지급한다.","src":"토지보상법 제30조"},{"t":"토지수용위원회는 재결신청서를 접수하면 공고하고 공고한 날부터 14일 이상 관계 서류의 사본을 일반인이 열람할 수 있도록 하여야 한다.","src":"토지보상법 제31조"},{"t":"토지수용위원회의 재결은 서면으로 하며, 재결서에는 주문 및 그 이유와 재결일을 적고 위원장 및 회의에 참석한 위원이 기명날인한 후 정본을 사업시행자, 토지소유자 및 관계인에게 송달하여야 한다.","src":"토지보상법 제34조"},{"t":"토지수용위원회는 심리를 시작한 날부터 14일 이내에 재결을 하여야 한다. 특별한 사유가 있으면 14일의 범위에서 한 차례만 연장할 수 있다.","src":"토지보상법 제35조"},{"t":"재결사항: 수용하거나 사용할 토지의 구역 및 사용방법, 손실보상, 수용 또는 사용의 개시일과 기간, 그 밖에 법령에서 규정한 사항. 신청한 범위에서 재결하되 손실보상은 증액재결을 할 수 있다.","src":"토지보상법 제50조"},{"t":"중앙토지수용위원회는 국가 또는 시·도가 사업시행자인 사업, 수용·사용할 토지가 둘 이상의 시·도에 걸쳐 있는 사업의 재결을 관장하고, 그 밖의 사업은 지방토지수용위원회가 관장한다.","src":"토지보상법 제51조"},{"t":"사업시행자는 수용 또는 사용의 개시일까지 관할 토지수용위원회가 재결한 보상금을 지급하거나 공탁하여야 하며, 하지 않으면 재결은 효력을 상실하고 사업시행자는 손실을 보상하여야 한다.","src":"토지보상법 제40조·제42조"},{"t":"사업시행자는 수용의 개시일에 토지나 물건의 소유권을 취득하며, 그 토지나 물건에 관한 다른 권리는 이와 동시에 소멸한다. 사용의 개시일에는 사용권을 취득하며 다른 권리는 사용 기간 중에는 행사하지 못한다. 재결로 인정된 권리는 소멸되거나 행사가 정지되지 않는다.","src":"토지보상법 제45조"},{"t":"수용에 의한 사업시행자의 토지소유권 취득은 법률의 규정에 의한 원시취득이다.","src":"기출 2024-50"},{"t":"사업시행자와 토지소유자 및 관계인 간 협의가 성립되어 토지수용위원회의 협의 성립 확인을 받으면 재결로 보며, 그 확인된 협의의 성립이나 내용을 다툴 수 없다.","src":"토지보상법 제29조"}]},{"머리":"불복(이의신청·소송)","줄":[{"t":"이의신청: 중앙토지수용위원회의 재결에 이의가 있는 자는 중앙토지수용위원회에, 지방토지수용위원회의 재결에 이의가 있는 자는 해당 지방토지수용위원회를 거쳐 중앙토지수용위원회에 이의를 신청할 수 있다. 재결서의 정본을 받은 날부터 30일 이내에 하여야 한다.","src":"토지보상법 제83조"},{"t":"수용재결에 불복할 때 이의신청을 거치지 않고도 행정소송을 제기할 수 있다. 이의신청은 필수적 전심절차가 아니다(임의적).","src":"기출 2025-42 | 기출 2021-45 | 토지보상법 제85조 제1항"},{"t":"행정소송 제기기간: 재결서를 받은 날부터 90일 이내, 이의신청을 거쳤을 때에는 이의신청에 대한 재결서를 받은 날부터 60일 이내.","src":"토지보상법 제85조 제1항 | 기출 2021-45"},{"t":"보상금의 증감에 관한 소송에서 토지소유자 또는 관계인이 제기할 때에는 사업시행자를, 사업시행자가 제기할 때에는 토지소유자 또는 관계인을 피고로 한다.","src":"토지보상법 제85조 제2항 | 기출 2021-45"},{"t":"사업시행자가 이의신청에 따라 늘어난 보상금을 지급할 때는 재결서 정본을 받은 날부터 30일 이내에 지급하여야 하며, 사업시행자가 행정소송을 제기하기 전에 늘어난 보상금을 공탁하여야 한다.","src":"토지보상법 제84조·제85조"},{"t":"수용재결에 대한 취소소송의 제기는 사업의 진행 및 토지의 수용 또는 사용을 정지시키지 아니한다.","src":"기출 2021-45"},{"t":"수용재결은 행정심판의 재결이 아니라 원처분이다. 수용재결에 대한 이의신청에 대한 재결이 행정심판의 성질을 가진다.","src":"기출 2024-50 | 보충"},{"t":"이의신청에 대한 재결이 확정되면 민사소송법상 확정판결이 있은 것으로 보며, 재결서 정본은 집행력 있는 판결의 정본과 동일한 효력을 가진다.","src":"토지보상법 제86조"}]},{"머리":"보상의 원칙·기준","줄":[{"t":"공익사업으로 인한 손실은 사업시행자가 보상하여야 한다. 사업시행자는 공사에 착수하기 이전에 토지소유자와 관계인에게 보상액 전액을 지급하여야 한다(사전보상).","src":"토지보상법 제61조·제62조"},{"t":"손실보상은 다른 법률에 특별한 규정이 없으면 현금으로 지급한다. 개인별로 하여야 하며, 동일인 소유 토지등이 여러 개인 경우 요구가 있으면 일괄보상한다.","src":"토지보상법 제63조~제65조"},{"t":"동일 소유자의 일단의 토지 일부를 취득하거나 사용하는 경우 잔여지 가치 상승 등 이익을 취득·사용으로 인한 손실과 상계할 수 없다.","src":"토지보상법 제66조"},{"t":"보상액의 산정은 협의에 의한 경우 협의 성립 당시의 가격을, 재결에 의한 경우 수용 또는 사용의 재결 당시의 가격을 기준으로 한다. 수용개시 당시 가격이 아니다.","src":"토지보상법 제67조 제1항 | 기출 2022-40 | 기출 2025-42"},{"t":"보상액을 산정할 때 해당 공익사업으로 인하여 토지등의 가격이 변동되었을 때에는 이를 고려하지 아니한다.","src":"토지보상법 제67조 제2항 | 기출 2025-42"},{"t":"취득하는 토지는 부동산 가격공시법에 따른 공시지가를 기준으로 하되 이용계획, 지가변동률, 생산자물가상승률, 위치·형상·환경·이용상황 등을 고려하여 평가한 적정가격으로 보상한다.","src":"토지보상법 제70조 제1항"},{"t":"사업인정 후 취득의 경우 공시지가는 사업인정고시일 전의 시점을 공시기준일로 하는 공시지가로서 협의 성립 또는 재결 당시 공시된 공시지가 중 사업인정고시일과 가장 가까운 시점에 공시된 것으로 한다.","src":"토지보상법 제70조 제4항"},{"t":"토지에 대한 보상액은 가격시점에서의 현실적인 이용상황과 일반적인 이용방법에 의한 객관적 상황을 고려해 산정하고, 일시적 이용상황과 주관적 가치, 특별한 용도 사용을 전제로 한 경우 등은 고려하지 않는다.","src":"토지보상법 제70조 제2항"},{"t":"재결에서 정한 보상금액이 일부 보상항목은 과소하고 다른 보상항목은 과다할 경우 법원은 보상항목 상호간의 유용을 허용하여 보상금을 결정할 수 있다.","src":"기출 2022-40"}]},{"머리":"보상 항목","줄":[{"t":"사용하는 토지: 인근 유사토지의 지료·임대료, 사용방법, 사용기간 및 토지의 가격 등을 고려한 적정가격으로 보상한다. 사용 기간이 3년 이상, 형질 변경, 소유자의 건축물이 있는 경우 소유자는 매수 또는 수용을 청구할 수 있다.","src":"토지보상법 제71조·제72조"},{"t":"잔여지 손실·공사비 보상: 일단의 토지 일부가 취득·사용됨으로 잔여지 가격이 감소하거나 통로·도랑·담장 등 공사가 필요하면 보상한다. 사업완료일부터 1년이 지난 후에는 청구할 수 없다.","src":"토지보상법 제73조"},{"t":"잔여지 매수·수용 청구: 잔여지를 종래의 목적에 사용하는 것이 현저히 곤란할 때 사업시행자에게 매수를 청구하고, 사업인정 이후에는 토지수용위원회에 수용을 청구할 수 있다. 수용 청구는 매수 협의가 성립되지 아니한 경우에만 할 수 있고, 사업완료일까지 하여야 한다.","src":"토지보상법 제74조 | 기출 2022-40"},{"t":"건축물등은 이전에 필요한 비용(이전비)으로 보상한다. 이전이 어렵거나 종래 목적대로 사용할 수 없게 된 경우, 이전비가 물건 가격을 넘는 경우, 사업시행자가 공익사업에 직접 사용할 목적으로 취득하는 경우에는 물건의 가격으로 보상한다.","src":"토지보상법 제75조"},{"t":"광업권·어업권·양식업권 및 물 등의 사용에 관한 권리는 투자비용, 예상 수익 및 거래가격 등을 고려한 적정가격으로 보상한다.","src":"토지보상법 제76조"},{"t":"영업손실: 영업을 폐업하거나 휴업함에 따른 손실은 영업이익과 시설의 이전비용 등을 고려하여 보상한다. 농업의 손실은 실제 경작자에게, 휴직·실직 근로자의 임금손실은 평균임금 등을 고려하여 보상한다.","src":"토지보상법 제77조"},{"t":"공익사업시행지구 밖에 있는 토지등이 공익사업의 시행으로 본래의 기능을 다할 수 없게 되는 경우에도 일정한 요건 하에 그 손실(영업손실 등)을 보상받을 수 있다.","src":"토지보상법 제79조 제2항 | 기출 2022-40"},{"t":"이주대책: 사업시행자는 주거용 건축물을 제공함으로써 생활의 근거를 상실하게 되는 자(이주대책대상자)를 위하여 이주대책을 수립·실시하거나 이주정착금을 지급하여야 한다. 이주대책을 수립하려면 미리 관할 지방자치단체의 장과 협의하여야 한다.","src":"토지보상법 제78조 제1항·제2항"},{"t":"이주대책에는 이주정착지에 대한 도로·급수시설·배수시설 등 통상적인 수준의 생활기본시설이 포함되어야 하고 필요한 비용은 사업시행자가 부담한다.","src":"토지보상법 제78조 제4항"},{"t":"이주대책대상자는 사업시행자가 이주대책 대상자 확인·결정 처분을 한 때 비로소 수분양권을 취득한다. 사업시행자가 이주대책 구체적 계획을 수립·공고하는 것만으로 수분양권을 취득하지 않는다.","src":"기출 2022-40 | 보충"},{"t":"주거용 건물의 거주자에 대해서는 주거 이전에 필요한 비용과 가재도구 등 동산의 운반에 필요한 비용을 보상한다.","src":"토지보상법 제78조 제6항 | 기출 2024-27"},{"t":"이주정착금·주거이전비 보상을 둘러싼 소송은 공법상 당사자소송으로 다툰다.","src":"기출 2024-27"},{"t":"환매권: 취득한 토지가 사업의 폐지·변경 등으로 필요 없게 된 경우 일정 기간 안에 보상금 상당 금액을 지급하고 환매할 수 있다.","src":"보충"}]},{"머리":"손실보상 일반이론","줄":[{"t":"헌법 제23조 제3항: 공공필요에 의한 재산권의 수용·사용 또는 제한 및 그에 대한 보상은 법률로써 하되, 정당한 보상을 지급하여야 한다. 정당한 보상은 완전보상을 의미한다(판례).","src":"보충"},{"t":"손실보상은 적법한 공권력 행사로 인한 특별한 희생에 대한 보상이고, 국가배상은 위법한 행위로 인한 손해의 배상이다.","src":"보충"},{"t":"경찰관의 적법한 직무집행으로 손실을 입은 자는 손실발생의 원인에 대하여 책임이 없는 경우 정당한 보상을 받고, 책임이 있는 자는 자신의 책임에 상응하는 정도를 초과하는 손실에 대해서만 보상을 받는다.","src":"경찰관 직무집행법 제11조의2 | 기출 2024-47"}]}],"함정":[{"x":"수용재결에 대한 이의신청은 행정소송을 하기 위한 필수적인 전심절차이다.","o":"이의신청은 임의적 절차다. 이의신청 없이 행정소송을 제기할 수 있다.","src":"기출 2021-45 | 기출 2025-42"},{"x":"이주대책대상자는 사업시행자가 이주대책에 대한 구체적인 계획을 수립하여 공고한 때에 수분양권을 취득한다.","o":"사업시행자가 이주대책 대상자 확인·결정 처분을 한 때 수분양권을 취득한다.","src":"기출 2022-40 | 보충"},{"x":"수용재결은 행정심판의 재결의 성질을 갖는다.","o":"수용재결은 원처분으로서 행정심판의 재결이 아니다.","src":"기출 2024-50"},{"x":"사업시행자는 사용의 개시일에 토지의 사용권을 취득하며, 그 토지에 관한 다른 권리는 재결로 인정되지 아니하더라도 사용 기간 중에 행사할 수 있다.","o":"재결로 인정되지 않은 다른 권리는 사용 기간 중에는 행사하지 못한다.","src":"기출 2025-42 | 토지보상법 제45조 제2항"},{"x":"재결에 의한 경우 보상액의 산정은 수용개시 당시의 가격을 기준으로 한다.","o":"재결에 의한 경우 수용 또는 사용의 재결 당시의 가격을 기준으로 한다.","src":"기출 2025-42"},{"x":"사업인정처분이 당연무효이더라도 그것이 유효함을 전제로 이루어진 수용재결이 무효가 되는 것이 아니다.","o":"사업인정이 당연무효이면 수용재결도 무효다.","src":"기출 2025-42 | 기출 2021-45"},{"x":"보상액을 산정할 경우에 해당 공익사업으로 인하여 토지등의 가격이 변동되었을 때에는 이를 고려하여야 한다.","o":"이를 고려하지 아니한다.","src":"기출 2025-42 | 토지보상법 제67조 제2항"}]},"행정심판":{"묶음":[{"머리":"행정심판의 대상과 종류","줄":[{"t":"행정청의 처분 또는 부작위에 대하여는 다른 법률에 특별한 규정이 있는 경우 외에는 행정심판법에 따라 행정심판을 청구할 수 있다.","src":"행정심판법 제3조 제1항"},{"t":"대통령의 처분 또는 부작위에 대하여는 다른 법률에서 행정심판을 청구할 수 있도록 정한 경우 외에는 행정심판을 청구할 수 없다.","src":"행정심판법 제3조 제2항 | 기출 2025-40"},{"t":"행정심판의 종류는 취소심판(위법 또는 부당한 처분의 취소·변경), 무효등확인심판(효력 유무 또는 존재 여부의 확인), 의무이행심판(신청에 대한 위법 또는 부당한 거부처분이나 부작위에 대하여 일정한 처분을 하도록 하는 심판)의 3가지다.","src":"행정심판법 제5조"},{"t":"행정심판법은 당사자심판에 관해서 규정하고 있지 않다.","src":"기출 2025-40"},{"t":"부작위: 행정청이 당사자의 신청에 대하여 상당한 기간 내에 일정한 처분을 하여야 할 법률상 의무가 있는데도 처분을 하지 아니하는 것.","src":"행정심판법 제2조 제2호 | 기출 2023-40"},{"t":"특별행정심판이나 행정심판 절차 특례는 사안의 전문성과 특수성을 살리기 위하여 특히 필요한 경우 외에는 다른 법률로 정할 수 없다. 특별행정심판에서 규정하지 않은 사항은 행정심판법에 따른다.","src":"행정심판법 제4조"},{"t":"행정심판으로 적법하게 청구된 것: 국세부과처분에 대한 국세청장에의 심사청구(특별행정심판), 지방토지수용위원회의 수용재결에 대한 중앙토지수용위원회에의 이의신청.","src":"기출 2022-42"},{"t":"국가공무원 면직처분에 대한 불복은 징계위원회 재심사청구가 아니라 소청심사위원회에 소청을 제기한다.","src":"국가공무원법 제9조·제76조 | 기출 2022-42"},{"t":"지방노동위원회의 구제명령 불이행에 대한 이행강제금부과처분에 대한 중앙노동위원회 재심신청은 2022 기출에서 적법한 행정심판 청구에서 제외되었다.","src":"기출 2022-42"}]},{"머리":"행정심판위원회","줄":[{"t":"감사원, 국가정보원장, 국회사무총장·법원행정처장·헌법재판소사무처장·중앙선거관리위원회사무총장, 국가인권위원회 등 독립성이 인정되는 행정청의 처분에 대한 심판청구는 그 행정청에 두는 행정심판위원회에서 심리·재결한다.","src":"행정심판법 제6조 제1항"},{"t":"그 밖의 국가행정기관의 장 또는 소속 행정청, 시·도지사 또는 시·도의 의회, 지방자치단체조합 등의 처분에 대한 심판청구는 국민권익위원회에 두는 중앙행정심판위원회에서 심리·재결한다.","src":"행정심판법 제6조 제2항 | 기출 2022-41"},{"t":"시·도 소속 행정청, 시·도 관할구역의 시·군·자치구의 장·소속 행정청 또는 시·군·자치구 의회의 처분에 대한 심판청구는 시·도지사 소속으로 두는 행정심판위원회에서 심리·재결한다.","src":"행정심판법 제6조 제3항 | 기출 2022-41"},{"t":"위원회(중앙 제외)는 위원장 1명을 포함하여 50명 이내의 위원으로 구성하며, 회의는 위원장과 위원장이 회의마다 지정하는 8명의 위원으로 구성한다. 구성원 과반수의 출석과 출석위원 과반수의 찬성으로 의결한다.","src":"행정심판법 제7조"},{"t":"중앙행정심판위원회는 위원장 1명을 포함하여 70명 이내(상임위원 4명 이내)로 구성하며, 회의는 위원장, 상임위원 및 위원장이 지정하는 비상임위원 총 9명으로 구성한다. 위원장은 국민권익위원회 부위원장 중 1명이다.","src":"행정심판법 제8조"},{"t":"위원의 제척 사유: 위원 또는 배우자 등이 사건의 당사자이거나 공동 권리자·의무자인 경우, 당사자와 친족이거나 친족이었던 경우, 사건에 관하여 증언·감정을 한 경우, 당사자의 대리인으로 관여한 경우, 사건의 대상이 된 처분 또는 부작위에 관여한 경우.","src":"행정심판법 제10조 제1항"}]},{"머리":"당사자·참가인","줄":[{"t":"청구인 적격: 취소심판은 처분의 취소 또는 변경을 구할 법률상 이익이 있는 자(처분의 효과가 소멸한 뒤에도 취소로 회복되는 법률상 이익이 있는 자 포함), 무효등확인심판은 효력 유무 또는 존재 여부의 확인을 구할 법률상 이익이 있는 자, 의무이행심판은 처분을 신청한 자로서 거부처분 또는 부작위에 대하여 일정한 처분을 구할 법률상 이익이 있는 자.","src":"행정심판법 제13조 | 기출 2023-40"},{"t":"법인이 아닌 사단 또는 재단으로서 대표자나 관리인이 정하여져 있는 경우 그 사단이나 재단의 이름으로 심판청구를 할 수 있다.","src":"행정심판법 제14조"},{"t":"여러 명의 청구인이 공동으로 심판청구를 할 때에는 청구인들 중에서 3명 이하의 선정대표자를 선정할 수 있다.","src":"행정심판법 제15조 제1항 | 기출 2023-40"},{"t":"청구인이 경제적 능력으로 인해 대리인을 선임할 수 없는 경우에는 행정심판위원회에 국선대리인을 선임하여 줄 것을 신청할 수 있다.","src":"기출 2023-40"},{"t":"청구인의 대리인이 될 수 있는 자: 청구인의 배우자, 청구인 또는 배우자의 사촌 이내의 혈족, 법인의 소속 임직원, 변호사, 다른 법률에 따라 심판청구를 대리할 수 있는 자, 위원회의 허가를 받은 자.","src":"행정심판법 제18조 제1항"},{"t":"피청구인은 처분을 한 행정청(의무이행심판은 청구인의 신청을 받은 행정청)이다. 권한이 다른 행정청에 승계된 경우 승계한 행정청이 피청구인이다.","src":"행정심판법 제17조 제1항"},{"t":"행정심판 결과에 이해관계가 있는 제3자나 행정청은 위원회 의결이 있기 전까지 심판참가를 할 수 있고, 위원회는 참가를 요구할 수도 있다.","src":"행정심판법 제20조·제21조"}]},{"머리":"청구기간·청구방식","줄":[{"t":"행정심판은 처분이 있음을 알게 된 날부터 90일 이내에 청구하여야 한다.","src":"행정심판법 제27조 제1항 | 기출 2023-40"},{"t":"처분이 있었던 날부터 180일이 지나면 청구하지 못한다. 정당한 사유가 있는 경우에는 예외다.","src":"행정심판법 제27조 제3항"},{"t":"천재지변, 전쟁, 사변, 그 밖의 불가항력으로 청구기간 내에 청구할 수 없었을 때에는 사유가 소멸한 날부터 14일(국외에서 청구하는 경우 30일) 이내에 청구할 수 있다.","src":"행정심판법 제27조 제2항"},{"t":"행정청이 심판청구 기간을 90일보다 긴 기간으로 잘못 알린 경우 그 잘못 알린 기간에 청구가 있으면 90일 이내에 청구된 것으로 본다.","src":"행정심판법 제27조 제5항 | 기출 2021-44 | 기출 2022-41"},{"t":"행정청이 심판청구 기간을 알리지 아니한 경우에는 처분이 있었던 날부터 180일 이내에 심판청구를 할 수 있다.","src":"행정심판법 제27조 제6항"},{"t":"청구기간 규정(제1항~제6항)은 무효등확인심판청구와 부작위에 대한 의무이행심판청구에는 적용하지 않는다.","src":"행정심판법 제27조 제7항"},{"t":"심판청구는 서면으로 하며 피청구인이나 위원회에 제출한다. 심판청구서가 피청구인이나 위원회에 제출되었을 때 행정심판이 청구된 것으로 본다.","src":"행정심판법 제23조·제28조"},{"t":"피청구인은 심판청구서를 받으면 10일 이내에 심판청구서(또는 답변서)를 위원회에 보내야 한다. 답변서에는 처분의 근거와 이유, 청구 취지·이유에 대응하는 답변을 적는다.","src":"행정심판법 제24조"},{"t":"피청구인은 심판청구가 이유 있다고 인정하면 직권으로 처분을 취소·변경하거나 확인을 하거나 신청에 따른 처분을 할 수 있다.","src":"행정심판법 제25조"},{"t":"처분을 할 때에는 처분의 상대방에게 행정심판을 청구할 수 있는지, 심판청구 절차 및 청구 기간을 알려야 한다. 이해관계인이 요구하면 지체 없이 알려 주어야 한다.","src":"행정심판법 제58조"}]},{"머리":"집행정지와 임시처분","줄":[{"t":"심판청구는 처분의 효력이나 그 집행 또는 절차의 속행에 영향을 주지 아니한다(집행부정지 원칙).","src":"행정심판법 제30조 제1항"},{"t":"집행정지 요건: 처분, 처분의 집행 또는 절차의 속행 때문에 중대한 손해가 생기는 것을 예방할 필요성이 긴급하다고 인정될 것. 공공복리에 중대한 영향을 미칠 우려가 없을 것. 처분의 효력정지는 집행 또는 절차의 속행의 정지로 목적을 달성할 수 있을 때는 허용되지 않는다.","src":"행정심판법 제30조 제2항·제3항"},{"t":"임시처분: 처분 또는 부작위가 위법·부당하다고 상당히 의심되는 경우로서 당사자가 받을 우려가 있는 중대한 불이익이나 급박한 위험을 막기 위하여 임시지위를 정하여야 할 필요가 있을 때 결정한다.","src":"행정심판법 제31조 제1항"},{"t":"임시처분은 집행정지로 목적을 달성할 수 있는 경우에는 허용되지 아니한다.","src":"행정심판법 제31조 제3항 | 기출 2021-44"}]},{"머리":"심리","줄":[{"t":"행정심판의 심리는 구술심리나 서면심리로 한다. 당사자가 구술심리를 신청한 경우에는 서면심리만으로 결정할 수 있다고 인정되는 경우 외에는 구술심리를 하여야 한다.","src":"행정심판법 제40조 제1항 | 기출 2022-41"},{"t":"위원회는 필요하면 당사자가 주장하지 아니한 사실에 대하여도 심리할 수 있다(직권심리).","src":"행정심판법 제39조"},{"t":"위원회는 직권으로 또는 당사자의 신청에 따라 증거조사(신문, 문서·물건 제출 요구와 영치, 감정, 출입·검증)를 할 수 있다.","src":"행정심판법 제36조"},{"t":"청구인은 위원회 의결이 있을 때까지 서면으로 심판청구를 취하할 수 있다.","src":"행정심판법 제42조"},{"t":"항고소송에서의 처분사유의 추가·변경 법리는 행정심판에도 적용된다. 처분청은 당초 처분 사유와 기본적 사실관계의 동일성이 인정되는 한도 내에서 다른 사유를 추가·변경할 수 있다.","src":"기출 2025-40 | 기출 2022-41"},{"t":"위원회는 당사자의 권리 및 권한의 범위에서 당사자의 동의를 받아 심판청구의 신속하고 공정한 해결을 위하여 조정을 할 수 있다. 조정이 공공복리에 적합하지 아니하거나 처분의 성질에 반하는 경우에는 할 수 없다.","src":"행정심판법 제43조의2 | 기출 2021-44"}]},{"머리":"재결","줄":[{"t":"재결 구분: 심판청구가 적법하지 아니하면 각하, 이유가 없다고 인정하면 기각, 취소심판이 이유 있으면 처분을 취소·변경하거나 변경할 것을 피청구인에게 명함(취소·변경·변경명령), 무효등확인심판이 이유 있으면 효력 유무 또는 존재 여부를 확인, 의무이행심판이 이유 있으면 지체 없이 신청에 따른 처분을 하거나 처분을 할 것을 피청구인에게 명함.","src":"행정심판법 제43조 | 기출 2022-41 | 기출 2023-44"},{"t":"사정재결: 청구가 이유 있다고 인정하는 경우에도 인용하는 것이 공공복리에 크게 위배된다고 인정하면 심판청구를 기각하는 재결을 할 수 있다. 이 경우 재결의 주문에서 처분 또는 부작위가 위법하거나 부당하다는 것을 구체적으로 밝혀야 한다.","src":"행정심판법 제44조 제1항 | 기출 2021-44 | 기출 2023-44"},{"t":"사정재결을 할 때 청구인에 대하여 상당한 구제방법을 취하거나 취할 것을 피청구인에게 명할 수 있다. 사정재결은 무효등확인심판에는 적용하지 아니한다.","src":"행정심판법 제44조 제2항·제3항 | 기출 2025-40"},{"t":"재결은 심판청구서를 받은 날부터 60일 이내에 하여야 한다. 부득이한 사정이 있으면 위원장이 직권으로 30일을 연장할 수 있고, 재결 기간이 끝나기 7일 전까지 당사자에게 알려야 한다.","src":"행정심판법 제45조"},{"t":"재결은 서면으로 하며, 재결서에는 사건번호와 사건명, 당사자·대표자 또는 대리인의 이름과 주소, 주문, 청구의 취지, 이유, 재결한 날짜가 포함되어야 한다.","src":"행정심판법 제46조 | 기출 2023-44"},{"t":"위원회는 심판청구의 대상이 되는 처분 또는 부작위 외의 사항에 대하여는 재결하지 못하고, 처분보다 청구인에게 불리한 재결을 하지 못한다.","src":"행정심판법 제47조 | 기출 2021-44 | 기출 2023-44"},{"t":"재결은 청구인에게 재결서의 정본이 송달되었을 때에 효력이 생긴다.","src":"행정심판법 제48조 제2항 | 기출 2023-44"},{"t":"심판청구에 대한 재결이 있으면 그 재결 및 같은 처분 또는 부작위에 대하여 다시 행정심판을 청구할 수 없다.","src":"행정심판법 제51조"}]},{"머리":"재결의 기속력·직접처분·간접강제","줄":[{"t":"심판청구를 인용하는 재결은 피청구인과 그 밖의 관계 행정청을 기속한다.","src":"행정심판법 제49조 제1항"},{"t":"재결에 의하여 취소되거나 무효 또는 부존재로 확인되는 처분이 당사자의 신청을 거부하는 것이면 그 처분을 한 행정청은 재결의 취지에 따라 다시 이전의 신청에 대한 처분을 하여야 한다.","src":"행정심판법 제49조 제2항 | 기출 2025-40"},{"t":"신청을 거부하거나 부작위로 방치한 처분의 이행을 명하는 재결이 있으면 행정청은 지체 없이 이전의 신청에 대하여 재결의 취지에 따라 처분을 하여야 한다.","src":"행정심판법 제49조 제3항"},{"t":"신청에 따른 처분이 절차의 위법 또는 부당을 이유로 재결로 취소된 경우에도 재처분 의무가 있다.","src":"행정심판법 제49조 제4항"},{"t":"직접처분: 위원회는 피청구인이 제49조 제3항에도 불구하고 처분을 하지 아니하는 경우 당사자가 신청하면 기간을 정하여 서면으로 시정을 명하고, 그 기간에 이행하지 아니하면 직접 처분을 할 수 있다(의무이행심판의 처분명령재결). 처분의 성질이나 그 밖의 불가피한 사유로 직접 처분을 할 수 없는 경우는 제외.","src":"행정심판법 제50조 제1항"},{"t":"직접 처분을 한 경우 그 사실을 해당 행정청에 통보하여야 하며, 통보를 받은 행정청은 위원회가 한 처분을 자기가 한 처분으로 보아 관리·감독 등 필요한 조치를 하여야 한다.","src":"행정심판법 제50조 제2항"},{"t":"위원회의 간접강제: 피청구인이 제49조 제2항(제4항 준용 포함) 또는 제3항에 따른 처분을 하지 아니하면 청구인의 신청에 의하여 상당한 기간을 정하고, 그 기간 내에 이행하지 않으면 지연기간에 따라 일정한 배상을 하도록 명하거나 즉시 배상을 할 것을 명할 수 있다.","src":"행정심판법 제50조의2 제1항"},{"t":"위원회는 사정의 변경이 있는 경우 당사자의 신청에 의하여 간접강제 결정의 내용을 변경할 수 있다. 결정 전에 신청 상대방의 의견을 들어야 한다.","src":"행정심판법 제50조의2 제2항·제3항"},{"t":"청구인은 간접강제 결정에 불복하는 경우 그 결정에 대하여 행정소송을 제기할 수 있다.","src":"행정심판법 제50조의2 제4항 | 기출 2024-42"},{"t":"간접강제 결정서 정본은 소송제기와 관계없이 「민사집행법」에 따른 강제집행에서 집행권원과 같은 효력을 가진다. 간접강제 결정에 기초한 강제집행에 관하여 특별한 규정이 없는 사항은 「민사집행법」을 준용한다.","src":"행정심판법 제50조의2 제5항·제6항 | 기출 2024-42"},{"t":"법령의 규정에 따라 공고하거나 고시한 처분이 재결로써 취소되거나 변경되면 처분을 한 행정청은 지체 없이 그 취소 또는 변경 사실을 공고·고시하여야 한다.","src":"행정심판법 제49조 제5항"},{"t":"중앙행정심판위원회는 처분의 근거가 되는 명령 등이 법령에 근거가 없거나 상위 법령에 위배되거나 국민에게 과도한 부담을 주는 등 크게 불합리하면 관계 행정기관에 개정·폐지 등 시정조치를 요청할 수 있다.","src":"행정심판법 제59조"}]}],"함정":[{"x":"행정심판위원회는 당사자의 동의가 없더라도 심판청구의 신속하고 공정한 해결을 위하여 조정을 할 수 있다.","o":"조정은 당사자의 동의를 받아야 한다.","src":"기출 2021-44 | 행정심판법 제43조의2"},{"x":"집행정지로 목적을 달성할 수 있는 경우에도 임시처분이 허용된다.","o":"집행정지로 목적을 달성할 수 있는 경우에는 임시처분이 허용되지 않는다.","src":"기출 2021-44 | 행정심판법 제31조 제3항"},{"x":"처분청이 심판청구기간을 법정기간보다 긴 기간으로 잘못 고지한 경우, 심판청구기간은 당해 처분이 있은 날부터 180일이 된다.","o":"잘못 알린 기간에 청구가 있으면 90일 이내에 청구된 것으로 본다.","src":"기출 2021-44 | 행정심판법 제27조 제5항"},{"x":"행정심판위원회는 심판청구의 대상이 되는 처분보다 청구인에게 불리한 재결을 할 수 있다.","o":"불리한 재결을 하지 못한다.","src":"기출 2021-44 | 행정심판법 제47조 제2항"},{"x":"심판청구기간을 법상 규정된 기간보다 긴 기간으로 잘못 고지한 경우에도 규정된 행정심판기간 내에 심판청구를 하여야 한다.","o":"잘못 알린 기간에 청구하면 규정된 기간 내에 청구된 것으로 본다.","src":"기출 2022-41"},{"x":"시·도지사의 처분에 대한 심판청구는 시·도지사 소속으로 두는 행정심판위원회에서 심리·재결한다.","o":"시·도지사의 처분에 대한 심판청구는 중앙행정심판위원회에서 심리·재결한다(시·도 소속 행정청의 처분은 시·도지사 소속 위원회).","src":"기출 2022-41 | 행정심판법 제6조"},{"x":"심리는 구술심리나 서면심리로 하고, 당사자가 구술심리를 신청한 경우에는 서면심리는 할 수 없다.","o":"서면심리만으로 결정할 수 있다고 인정되는 경우에는 구술심리 신청이 있어도 서면심리만으로 결정할 수 있다.","src":"기출 2022-41 | 행정심판법 제40조"},{"x":"항고소송에서의 처분사유의 추가·변경의 법리는 행정심판에 적용되지 않는다.","o":"행정심판에도 적용된다.","src":"기출 2022-41 | 기출 2025-40"},{"x":"행정심판은 처분이 있음을 알게 된 날부터 180일 이내에 청구하여야 한다.","o":"처분이 있음을 알게 된 날부터 90일 이내에 청구한다. 180일은 처분이 있은 날부터의 기간이다.","src":"기출 2023-40"},{"x":"거부처분 취소심판의 경우 행정심판위원회는 직접 처분을 할 수 있다.","o":"취소재결이 있으면 처분청이 재처분의무를 진다. 직접 처분은 의무이행심판에서 처분명령재결을 하였는데도 이행하지 않을 때 가능하다.","src":"기출 2024-42 | 행정심판법 제49조·제50조"},{"x":"의무이행심판의 인용재결이 처분명령재결인 경우 행정심판위원회는 직접 처분을 할 수 없다.","o":"시정을 명하고 이행하지 않으면 직접 처분을 할 수 있다.","src":"기출 2024-42 | 행정심판법 제50조"},{"x":"행정심판위원회는 사정의 변경이 있어 당사자가 신청하는 경우에도 간접강제 결정의 내용을 변경할 수 없다.","o":"사정의 변경이 있으면 당사자의 신청에 의하여 간접강제 결정의 내용을 변경할 수 있다.","src":"기출 2024-42 | 행정심판법 제50조의2 제2항"},{"x":"간접강제 결정에 기초한 강제집행에 관하여 「행정심판법」에 특별한 규정이 없는 사항에 대하여는 「행정기본법」의 규정을 준용한다.","o":"「민사집행법」의 규정을 준용한다.","src":"기출 2024-42 | 행정심판법 제50조의2 제6항"},{"x":"무효등확인심판에는 사정재결을 할 수 있다.","o":"사정재결은 무효등확인심판에는 적용하지 아니한다.","src":"기출 2025-40 | 행정심판법 제44조 제3항"},{"x":"행정심판위원회는 사정재결을 할 수 없다.","o":"공공복리에 크게 위배된다고 인정하면 사정재결을 할 수 있다.","src":"기출 2023-44"}]},"항고소송(취소소송 등)":{"묶음":[{"머리":"항고소송의 종류와 대상","줄":[{"t":"항고소송은 취소소송(위법한 처분등을 취소 또는 변경), 무효등 확인소송(처분등의 효력 유무 또는 존재 여부 확인), 부작위위법확인소송(부작위가 위법하다는 것을 확인)의 3가지다.","src":"행정소송법 제4조"},{"t":"처분등: 행정청이 행하는 구체적 사실에 관한 법집행으로서의 공권력의 행사 또는 그 거부와 그 밖에 이에 준하는 행정작용 및 행정심판에 대한 재결.","src":"행정소송법 제2조 제1항 제1호 | 기출 2023-41"},{"t":"취소소송은 처분등을 대상으로 한다. 재결취소소송은 재결 자체에 고유한 위법이 있음을 이유로 하는 경우에 한한다(원처분주의).","src":"행정소송법 제19조"},{"t":"무효인 처분에 대하여는 무효확인소송뿐 아니라 무효선언을 구하는 의미의 취소소송도 제기할 수 있다. 취소소송의 형식을 취하면 제소기간 등 취소소송 요건을 갖추어야 한다.","src":"기출 2022-50 | 기출 2024-40"},{"t":"신청에 대한 거부행위도 취소소송의 대상이 되는 처분이 될 수 있다.","src":"기출 2022-50"},{"t":"지목변경신청 반려행위, 건축물 용도변경신청 거부행위, 건축물대장 작성신청 반려행위, 토지대장 직권말소행위는 항고소송의 대상이 되는 행정처분이다.","src":"기출 2023-29"},{"t":"토지대장상의 소유자명의변경신청 거부행위는 항고소송의 대상이 되는 처분이 아니다.","src":"기출 2023-29 | 보충"},{"t":"청소년유해매체물 결정 및 고시처분은 항고소송의 대상이 되는 처분이다. 두밀분교를 폐교하는 경기도의 조례는 항고소송의 대상이 되는 처분이다.","src":"기출 2021-43"},{"t":"어업권 면허에 선행하는 우선순위결정은 확약에 불과하여 항고소송의 대상이 아니다.","src":"기출 2021-43 | 기출 2022-34"},{"t":"2021 기출에서 구 농지법상 이행강제금 부과처분은 항고소송의 대상에서 제외된 것으로 출제되었다.","src":"기출 2021-43"},{"t":"고시가 다른 집행행위 없이 그 자체로 국민의 구체적인 권리의무를 규율하는 성격이면 처분이다. 보건복지부 고시인 약제급여·비급여목록 및 급여상한금액표는 취소소송으로 다툴 수 있다.","src":"기출 2021-28 | 기출 2023-28"},{"t":"행정규칙에 의한 불문경고조치는 항고소송의 대상이 되는 행정처분에 해당하지 아니한다(2025 기출).","src":"기출 2025-39"}]},{"머리":"거부처분","줄":[{"t":"거부처분이 성립하려면 신청인에게 그 행위발동을 요구할 수 있는 법규상 또는 조리상 신청권이 있어야 한다.","src":"기출 2021-47"},{"t":"거부처분은 당사자의 권익을 제한하는 처분이 아니므로 행정절차법상 사전통지의 대상이 아니다.","src":"기출 2021-47 | 기출 2022-35"},{"t":"거부처분에 대하여는 집행정지를 구할 이익이 없어 집행정지가 허용되지 않는다.","src":"기출 2021-47 | 보충"},{"t":"거부처분취소판결의 취지에 따라 행정청이 처분을 하지 않는 경우 당사자는 제1심 수소법원에 간접강제를 신청할 수 있다. 직접강제를 신청할 수 없다.","src":"행정소송법 제34조 | 기출 2021-47"},{"t":"행정소송법은 의무이행소송을 명문으로 인정하지 않는다.","src":"기출 2021-47 | 기출 2025-41"},{"t":"거부처분 무효확인소송을 제기한 경우 무효인 사유를 주장·증명할 책임은 원고에게 있다. 취소소송의 사정판결 규정은 준용되지 않는다.","src":"기출 2024-40"}]},{"머리":"원고적격·협의의 소익","줄":[{"t":"취소소송은 처분등의 취소를 구할 법률상 이익이 있는 자가 제기할 수 있다. 처분의 효과가 기간의 경과, 집행 등으로 소멸된 뒤에도 취소로 회복되는 법률상 이익이 있는 자는 제기할 수 있다.","src":"행정소송법 제12조 | 기출 2023-39"},{"t":"제약회사는 보건복지부 고시인 약제급여·비급여 목록 및 급여 상한금액표 중 자신이 제조·공급하는 약제의 상한금액 인하 부분의 취소를 구할 원고적격이 있다.","src":"기출 2023-39"},{"t":"처분의 효과가 소멸된 뒤에도 그 처분의 취소로 회복되는 법률상 이익이 있으면 취소소송을 제기할 수 있다.","src":"기출 2023-39 | 행정소송법 제12조"},{"t":"지방법무사회가 법무사의 사무원 채용승인 신청을 거부한 경우, 채용승인을 신청한 법무사가 아닌 사무원이 될 자도 취소소송을 제기할 수 있다.","src":"기출 2023-39"},{"t":"기존의 시외버스운송사업자는 동일노선을 운행하는 다른 회사에 대한 시외버스운송사업계획변경인가 처분으로 수익감소가 예상되는 경우 그 처분의 취소를 구할 법률상 이익이 있다(경업자소송).","src":"기출 2023-39"},{"t":"「주택법」상 입주자는 건축물의 하자를 이유로 그 건축물에 대한 사용검사처분의 취소를 구할 법률상 이익이 없다.","src":"기출 2023-39"},{"t":"국가기관도 취소소송의 당사자가 될 수 있다.","src":"기출 2025-39"}]},{"머리":"피고적격·관할","줄":[{"t":"취소소송은 다른 법률에 특별한 규정이 없는 한 처분등을 행한 행정청을 피고로 한다. 처분등이 있은 뒤 권한이 다른 행정청에 승계된 때에는 승계한 행정청이 피고다. 행정청이 없게 된 때에는 사무가 귀속되는 국가 또는 공공단체를 피고로 한다.","src":"행정소송법 제13조"},{"t":"처분등을 할 정당한 권한이 없는 행정청도 처분명의자라면 항고소송의 피고가 될 수 있다(처분명의자가 피고).","src":"기출 2022-50 | 보충"},{"t":"대리권을 수여받은 데 불과하여 그 자신의 명의로 행정처분을 할 권한이 없는 행정청이 대리관계를 밝힘이 없이 자신의 명의로 처분을 하였다면 처분명의자인 해당 행정청이 피고가 되는 것이 원칙이다.","src":"기출 2025-39"},{"t":"교육에 관한 조례의 무효확인소송은 그 조례의 공포권이 있는 시·도 교육감을 피고로 하여야 한다.","src":"기출 2025-39"},{"t":"내부위임의 경우 수임관청이 자기 이름으로 처분을 하면 수임관청이 피고다.","src":"기출 2022-45 | 기출 2024-45"},{"t":"원고가 피고를 잘못 지정한 때에는 법원은 원고의 신청에 의하여 결정으로 피고의 경정을 허가할 수 있다. 경정 결정이 있으면 새로운 피고에 대한 소송은 처음 소를 제기한 때 제기된 것으로 본다.","src":"행정소송법 제14조"},{"t":"취소소송의 제1심 관할법원은 피고의 소재지를 관할하는 행정법원이다. 중앙행정기관 등을 피고로 하는 경우에는 대법원소재지를 관할하는 행정법원에 제기할 수 있다.","src":"행정소송법 제9조"}]},{"머리":"제소기간·행정심판과의 관계","줄":[{"t":"취소소송은 처분등이 있음을 안 날부터 90일 이내에 제기하여야 하고, 처분등이 있은 날부터 1년이 지나면 제기하지 못한다. 정당한 사유가 있으면 예외다. 90일은 불변기간이다.","src":"행정소송법 제20조"},{"t":"행정심판청구가 있은 때의 제소기간은 재결서의 정본을 송달받은 날부터 기산한다. 재결이 있은 날부터 1년이 지나면 제기하지 못한다.","src":"행정소송법 제20조 제1항 단서·제2항"},{"t":"행정심판 재결에서 처분이 일부취소(감액)된 경우 취소소송의 대상은 감액된 원처분이고, 제소기간은 재결서 정본을 송달받은 날부터 기산한다.","src":"기출 2024-43 | 행정소송법 제20조"},{"t":"취소소송은 법령의 규정에 의하여 처분에 대한 행정심판을 제기할 수 있는 경우에도 이를 거치지 아니하고 제기할 수 있다(임의적 전치). 다른 법률에 재결을 거치지 않으면 제기할 수 없다는 규정이 있는 경우에는 그에 따른다(필요적 전치).","src":"행정소송법 제18조 제1항 | 기출 2025-41"},{"t":"필요적 전치의 경우에도 행정심판청구가 있은 날부터 60일이 지나도 재결이 없는 때, 처분의 집행 등으로 생길 중대한 손해를 예방하여야 할 긴급한 필요가 있는 때, 행정심판기관이 의결·재결을 하지 못할 사유가 있는 때, 그 밖의 정당한 사유가 있는 때에는 재결을 거치지 않고 제기할 수 있다.","src":"행정소송법 제18조 제2항"},{"t":"필요적 전치의 경우에도 동종사건에 관하여 이미 행정심판의 기각재결이 있은 때, 서로 내용상 관련되는 처분 중 어느 하나가 이미 재결을 거친 때, 사실심 변론종결 후 처분이 변경되어 변경된 처분에 관하여 소를 제기하는 때, 행정청이 심판을 거칠 필요가 없다고 잘못 알린 때에는 행정심판을 제기함이 없이 소송을 제기할 수 있다.","src":"행정소송법 제18조 제3항"}]},{"머리":"집행정지","줄":[{"t":"취소소송의 제기는 처분등의 효력이나 그 집행 또는 절차의 속행에 영향을 주지 아니한다(집행부정지 원칙).","src":"행정소송법 제23조 제1항"},{"t":"집행정지 요건: 취소소송이 제기되었을 것, 처분등이나 그 집행 또는 절차의 속행으로 인하여 생길 회복하기 어려운 손해를 예방하기 위한 긴급한 필요가 있을 것, 공공복리에 중대한 영향을 미칠 우려가 없을 것, 본안이 계속 중일 것. 신청인이 이유를 소명한다.","src":"행정소송법 제23조 제2항~제4항"},{"t":"처분의 효력정지는 처분등의 집행 또는 절차의 속행을 정지함으로써 목적을 달성할 수 있는 경우에는 허용되지 아니한다.","src":"행정소송법 제23조 제2항 단서 | 기출 2024-41"},{"t":"집행정지는 처분의 전부 또는 일부에 대하여 할 수 있다. 처분이 가분적이면 일부에 대한 집행정지도 허용된다.","src":"행정소송법 제23조 제2항 | 기출 2024-41"},{"t":"집행정지의 결정 또는 기각의 결정에 대하여는 즉시항고할 수 있다. 집행정지결정에 대한 즉시항고에는 결정의 집행을 정지하는 효력이 없다.","src":"행정소송법 제23조 제5항 | 기출 2024-41"},{"t":"집행정지는 부작위위법확인소송에는 인정되지 않는다(준용 규정에 없다).","src":"행정소송법 제38조 제2항 | 기출 2024-41"},{"t":"집행정지결정이 확정된 후 집행정지가 공공복리에 중대한 영향을 미치거나 정지사유가 없어진 때에는 당사자의 신청 또는 직권으로 취소할 수 있다.","src":"행정소송법 제24조"},{"t":"집행정지결정은 제3자에 대하여도 효력이 있고, 당사자인 행정청과 그 밖의 관계행정청을 기속한다.","src":"행정소송법 제29조 제2항·제23조 제6항"}]},{"머리":"심리·판결","줄":[{"t":"법원은 필요하다고 인정할 때 직권으로 증거조사를 할 수 있고, 당사자가 주장하지 아니한 사실에 대하여도 판단할 수 있다.","src":"행정소송법 제26조"},{"t":"행정청의 재량에 속하는 처분이라도 재량권의 한계를 넘거나 그 남용이 있는 때에는 법원은 이를 취소할 수 있다.","src":"행정소송법 제27조 | 기출 2023-41"},{"t":"사정판결: 원고의 청구가 이유 있다고 인정하는 경우에도 처분등을 취소하는 것이 현저히 공공복리에 적합하지 아니하다고 인정하는 때 법원은 청구를 기각할 수 있다. 이 경우 판결의 주문에서 처분등이 위법함을 명시하여야 한다. 처분이 위법한 것으로 인정되는 경우에도 공공복리를 위하여 청구가 기각될 수 있다.","src":"행정소송법 제28조 제1항 | 기출 2022-50"},{"t":"사정판결을 하려면 미리 원고가 입게 될 손해의 정도와 배상방법 그 밖의 사정을 조사하여야 하고, 원고는 피고 행정청이 속하는 국가 또는 공공단체를 상대로 손해배상, 제해시설의 설치 등 구제방법의 청구를 병합하여 제기할 수 있다. 사정판결의 경우 소송비용은 피고가 부담한다.","src":"행정소송법 제28조 제2항·제3항·제32조"},{"t":"과세처분취소소송에서 적법하게 부과될 정당한 세액이 산출되면 법원은 정당한 세액을 초과하는 부분만 취소할 수 있다.","src":"기출 2022-50 | 보충"},{"t":"법원은 처분의 변경이 있는 경우 원고의 신청에 의하여 청구의 취지 또는 원인의 변경을 허가할 수 있다. 신청은 처분의 변경이 있음을 안 날부터 60일 이내에 하여야 한다.","src":"행정소송법 제22조"},{"t":"처분등을 취소하는 확정판결은 제3자에 대하여도 효력이 있다(형성력, 대세효).","src":"행정소송법 제29조 제1항 | 기출 2023-41 | 기출 2025-41"},{"t":"처분등을 취소하는 확정판결은 그 사건에 관하여 당사자인 행정청과 그 밖의 관계행정청을 기속한다. 판결에 의하여 취소되는 처분이 신청을 거부하는 것이면 판결의 취지에 따라 다시 이전의 신청에 대한 처분을 하여야 하고, 신청에 따른 처분이 절차의 위법을 이유로 취소되는 경우에도 같다.","src":"행정소송법 제30조"},{"t":"거부처분취소판결에 따른 재처분을 하지 않으면 제1심 수소법원은 당사자의 신청에 의하여 상당한 기간을 정하고, 그 기간 내에 이행하지 않으면 지연기간에 따라 일정한 배상을 할 것을 명하거나 즉시 손해배상을 할 것을 명할 수 있다(간접강제).","src":"행정소송법 제34조"},{"t":"처분등을 취소하는 판결에 의하여 권리 또는 이익의 침해를 받은 제3자는 자기에게 책임 없는 사유로 소송에 참가하지 못해 방어방법을 제출하지 못한 때 재심을 청구할 수 있다. 확정판결이 있음을 안 날부터 30일 이내, 확정된 날부터 1년 이내에 제기한다.","src":"행정소송법 제31조"}]},{"머리":"무효등 확인소송·부작위위법확인소송","줄":[{"t":"무효등 확인소송은 처분등의 효력 유무 또는 존재 여부의 확인을 구할 법률상 이익이 있는 자가 제기할 수 있다.","src":"행정소송법 제35조 | 기출 2023-41"},{"t":"부작위위법확인소송은 처분의 신청을 한 자로서 부작위의 위법의 확인을 구할 법률상 이익이 있는 자만이 제기할 수 있다.","src":"행정소송법 제36조"},{"t":"부작위위법확인소송에 준용되는 취소소송 규정: 제9조, 제10조, 제13조~제19조, 제20조, 제25조~제27조, 제29조~제31조, 제33조, 제34조. 사정판결(제28조)과 집행정지(제23조)는 준용되지 않는다.","src":"행정소송법 제38조 제2항 | 기출 2025-43"},{"t":"부작위위법확인소송에는 제3자의 소송참가(제16조), 소송비용에 관한 재판의 효력(제33조), 거부처분취소판결의 간접강제(제34조)가 준용된다.","src":"행정소송법 제38조 제2항 | 기출 2025-43"},{"t":"무효등 확인소송에는 제9조, 제10조, 제13조~제17조, 제19조, 제22조~제26조, 제29조~제31조, 제33조가 준용된다. 사정판결(제28조)과 간접강제(제34조), 제소기간(제20조)은 준용되지 않는다.","src":"행정소송법 제38조 제1항 | 기출 2025-41"},{"t":"행정처분의 무효 확인을 구하는 소에는 특단의 사정이 없는 한 취소를 구하는 취지도 포함되어 있다.","src":"기출 2025-41"},{"t":"소송의 변경: 법원은 취소소송을 당사자소송 또는 취소소송 외의 항고소송으로 변경하는 것이 상당하다고 인정할 때 청구의 기초에 변경이 없는 한 사실심 변론종결시까지 원고의 신청에 의하여 허가할 수 있다.","src":"행정소송법 제21조"}]}],"함정":[{"x":"거부처분은 당사자의 권익을 제한하는 처분에 해당하므로 원칙적으로 행정절차법상 사전통지의 대상이 된다.","o":"거부처분은 사전통지의 대상이 아니다.","src":"기출 2021-47"},{"x":"거부처분에 대하여는 행정소송법상 집행정지를 구할 이익이 있어 집행정지가 허용된다.","o":"거부처분은 집행정지를 구할 이익이 없다.","src":"기출 2021-47"},{"x":"거부처분의 취소판결의 취지에 따라 행정청이 처분을 하지 않는 경우, 당사자는 수소법원에 직접강제를 신청할 수 있다.","o":"간접강제를 신청할 수 있다.","src":"기출 2021-47 | 행정소송법 제34조"},{"x":"거부처분에 대하여는 행정소송법상 명문의 규정으로 의무이행소송이 허용된다.","o":"행정소송법은 의무이행소송을 규정하고 있지 않다.","src":"기출 2021-47 | 기출 2025-41"},{"x":"무효인 처분에 대하여는 무효확인청구소송을 제기하여야 하고 취소소송을 제기할 수는 없다.","o":"무효선언을 구하는 의미의 취소소송도 제기할 수 있다.","src":"기출 2022-50"},{"x":"신청에 대한 거부행위는 취소소송의 대상이 될 수 없다.","o":"거부행위도 처분으로서 취소소송의 대상이 될 수 있다.","src":"기출 2022-50"},{"x":"처분등을 할 정당한 권한을 가진 행정청만이 피고적격을 갖는다.","o":"정당한 권한이 없어도 처분명의자인 행정청이 피고가 된다.","src":"기출 2022-50"},{"x":"과세처분취소소송에서 적법하게 부과될 정당한 세액이 산출되더라도 법원은 정당한 세액을 초과하는 부분만 취소할 수는 없고 전부를 취소하여야 한다.","o":"정당한 세액을 초과하는 부분만 취소할 수 있다.","src":"기출 2022-50"},{"x":"처분의 효과가 소멸된 뒤에는 그 처분의 취소로 인하여 회복되는 법률상 이익이 있어도 그 처분에 대한 취소소송을 제기할 수 없다.","o":"회복되는 법률상 이익이 있으면 제기할 수 있다.","src":"기출 2023-39 | 행정소송법 제12조"},{"x":"지방법무사회가 법무사의 사무원 채용승인 신청을 거부한 경우 채용승인을 신청한 법무사가 아닌 자는 취소소송을 제기하지 못한다.","o":"사무원이 될 자도 취소소송을 제기할 수 있다.","src":"기출 2023-39"},{"x":"기존의 시외버스운송사업자인 甲회사는 동일노선을 운행하는 乙회사에 대한 시외버스운송사업계획변경인가 처분으로 인하여 甲회사의 수익감소가 예상되는 경우라도 그 처분의 취소를 구할 법률상의 이익이 없다.","o":"수익감소가 예상되는 기존 사업자는 취소를 구할 법률상 이익이 있다.","src":"기출 2023-39"},{"x":"「주택법」상 입주자는 건축물의 하자를 이유로 그 건축물에 대한 사용검사처분의 취소를 구할 법률상 이익이 있다.","o":"입주자는 사용검사처분의 취소를 구할 법률상 이익이 없다.","src":"기출 2023-39"},{"x":"甲이 무효의 선언을 구하는 의미의 취소소송을 제기한 경우 제소기간의 제한이 없다.","o":"무효선언을 구하는 취소소송은 취소소송이므로 제소기간의 제한이 있다.","src":"기출 2024-40"},{"x":"처분이 가분적이더라도 처분의 일부에 대한 집행정지는 허용되지 않는다.","o":"처분이 가분적이면 일부에 대한 집행정지도 허용된다.","src":"기출 2024-41 | 행정소송법 제23조 제2항"},{"x":"집행정지의 결정에 대한 즉시항고에는 결정의 집행을 정지하는 효력이 인정된다.","o":"즉시항고에는 결정의 집행을 정지하는 효력이 없다.","src":"기출 2024-41 | 행정소송법 제23조 제5항"},{"x":"지방자치단체장이 국유 일반재산을 대부하여 달라는 신청을 거부한 것은 행정처분이 아니므로 항고소송으로 그 취소를 구할 수 없다.","o":"출제 오답(바른 내용 미확인)","src":"기출 2025-39"}]},"행정소송 총설과 당사자소송":{"묶음":[{"머리":"행정소송의 종류","줄":[{"t":"행정소송은 항고소송, 당사자소송, 민중소송, 기관소송의 네 가지다.","src":"행정소송법 제3조 | 기출 2023-41"},{"t":"당사자소송: 행정청의 처분등을 원인으로 하는 법률관계에 관한 소송 그 밖에 공법상의 법률관계에 관한 소송으로서 그 법률관계의 한쪽 당사자를 피고로 하는 소송.","src":"행정소송법 제3조 제2호"},{"t":"민중소송: 국가 또는 공공단체의 기관이 법률에 위반되는 행위를 한 때 직접 자기의 법률상 이익과 관계없이 그 시정을 구하기 위하여 제기하는 소송.","src":"행정소송법 제3조 제3호"},{"t":"기관소송: 국가 또는 공공단체의 기관 상호간에 권한의 존부 또는 그 행사에 관한 다툼이 있을 때 제기하는 소송. 헌법재판소의 관장사항은 제외.","src":"행정소송법 제3조 제4호"},{"t":"민중소송 및 기관소송은 법률이 정한 경우에 법률에 정한 자에 한하여 제기할 수 있다.","src":"행정소송법 제45조"},{"t":"행정소송에 대하여는 다른 법률에 특별한 규정이 있는 경우를 제외하고는 행정소송법이 정하는 바에 의한다. 행정소송법에 특별한 규정이 없는 사항은 법원조직법, 민사소송법 및 민사집행법을 준용한다.","src":"행정소송법 제8조"},{"t":"행정소송법은 의무이행소송을 규정하고 있지 않다.","src":"기출 2025-41"}]},{"머리":"당사자소송","줄":[{"t":"당사자소송은 국가·공공단체 그 밖의 권리주체를 피고로 한다. 행정청이 피고가 아니다.","src":"행정소송법 제39조"},{"t":"당사자소송의 재판관할에는 제9조를 준용한다. 국가 또는 공공단체가 피고인 경우 관계행정청의 소재지를 피고의 소재지로 본다.","src":"행정소송법 제40조"},{"t":"당사자소송에 관하여 법령에 제소기간이 정하여져 있는 때에는 그 기간은 불변기간으로 한다.","src":"행정소송법 제41조"},{"t":"당사자소송에는 피고경정(제14조), 공동소송(제15조), 제3자의 소송참가(제16조), 행정청의 소송참가(제17조), 처분변경으로 인한 소의 변경(제22조), 행정심판기록 제출명령(제25조), 직권심리(제26조), 취소판결의 기속력 일부(제30조 제1항), 소송비용 부담·재판의 효력(제32조·제33조)이 준용된다. 집행정지와 사정판결은 준용되지 않는다.","src":"행정소송법 제44조"},{"t":"공법상 계약에 따른 권리·의무의 확인 소송은 공법상 당사자소송에 의한다.","src":"기출 2024-28"},{"t":"공법상 당사자소송으로 다투는 것: 서울시립무용단 단원의 해촉, 공익사업으로 이주하는 세입자의 주거이전비 보상 소송, 공법상 근무관계에 관한 소송.","src":"기출 2024-27"},{"t":"항고소송과 당사자소송 상호간의 소의 변경은 청구의 기초에 변경이 없는 한 사실심 변론종결시까지 법원의 허가로 할 수 있다.","src":"행정소송법 제21조·제42조"}]},{"머리":"소송의 병합·참가·선결문제","줄":[{"t":"취소소송과 관련청구소송(처분등과 관련되는 손해배상·부당이득반환·원상회복 등 청구소송, 처분등과 관련되는 취소소송)이 각각 다른 법원에 계속되는 경우 관련청구소송이 계속된 법원이 상당하다고 인정하면 취소소송이 계속된 법원으로 이송할 수 있다. 취소소송에는 사실심의 변론종결시까지 관련청구소송을 병합할 수 있다.","src":"행정소송법 제10조"},{"t":"법원은 소송의 결과에 따라 권리 또는 이익의 침해를 받을 제3자가 있는 경우 당사자 또는 제3자의 신청 또는 직권에 의하여 그 제3자를 소송에 참가시킬 수 있다. 다른 행정청을 참가시킬 필요가 있다고 인정할 때에도 같다.","src":"행정소송법 제16조·제17조"},{"t":"처분등의 효력 유무 또는 존재 여부가 민사소송의 선결문제로 되어 수소법원이 심리·판단하는 경우 제17조, 제25조, 제26조, 제33조를 준용하며 수소법원은 처분등을 행한 행정청에게 그 사실을 통지하여야 한다.","src":"행정소송법 제11조"},{"t":"처분등을 취소하는 확정판결은 제3자에 대하여도 효력이 있다.","src":"행정소송법 제29조 제1항"},{"t":"행정소송의 종류에서 정한 항고소송의 대상인 처분에 대해서도 재량권의 한계를 넘거나 남용이 있으면 법원은 취소할 수 있다.","src":"행정소송법 제27조 | 기출 2023-41"}]}],"함정":[{"x":"처분등을 취소하는 확정판결은 당사자에 대해서만 효력이 있다.","o":"처분등을 취소하는 확정판결은 제3자에 대하여도 효력이 있다.","src":"기출 2023-41 | 행정소송법 제29조 제1항"},{"x":"취소소송은 법령의 규정에 의하여 당해 처분에 대한 행정심판을 제기할 수 있는 경우에는 이를 거치지 아니하고 제기할 수 없다.","o":"행정심판을 거치지 않고 제기할 수 있다(임의적 전치). 다른 법률에 규정이 있으면 필요적 전치다.","src":"기출 2025-41 | 행정소송법 제18조"},{"x":"처분등을 취소하는 확정판결은 제3자에 대하여는 효력이 없다.","o":"제3자에 대하여도 효력이 있다.","src":"기출 2025-41"},{"x":"거부처분취소판결의 간접강제에 관한 규정은 무효등 확인소송의 경우에 준용한다.","o":"무효등 확인소송에는 간접강제 규정이 준용되지 않는다. 부작위위법확인소송에는 준용된다.","src":"기출 2025-41 | 행정소송법 제38조"},{"x":"「행정소송법」에서는 의무이행소송을 인정하고 있다.","o":"행정소송법은 의무이행소송을 인정하지 않는다.","src":"기출 2025-41"}]},"행정조직법(행정기관과 권한의 위임·대리)":{"묶음":[{"머리":"행정기관의 종류와 설치","줄":[{"t":"행정청: 행정에 관한 의사를 결정하여 표시하는 국가 또는 지방자치단체의 기관.","src":"행정절차법 제2조 제1호 | 기출 2021-41"},{"t":"행정청에는 법령등에 따라 행정권한을 가지고 있거나 위임 또는 위탁받은 공공단체 또는 그 기관이나 사인(私人)도 포함된다. 법령에 따라 행정권한을 위탁받은 사인도 행정청이 될 수 있다.","src":"행정절차법 제2조 제1호 | 기출 2021-41"},{"t":"중앙행정기관의 설치와 직무범위는 법률로 정한다.","src":"정부조직법 제2조 제1항 | 기출 2025-44"},{"t":"행정각부의 설치·조직과 직무범위는 법률로 정한다(헌법).","src":"헌법 제96조 | 기출 2023-43"},{"t":"행정기관에는 소관사무의 일부를 독립하여 수행할 필요가 있는 때에는 법률로 정하는 바에 따라 행정위원회 등 합의제행정기관을 둘 수 있다. 정부조직법은 합의제행정기관 설치의 법적 근거를 두고 있다.","src":"정부조직법 제5조 | 기출 2021-41 | 기출 2025-44"},{"t":"지방자치단체는 소관 사무의 일부를 독립하여 수행할 필요가 있으면 법령이나 조례로 정하는 바에 따라 합의제행정기관을 설치할 수 있다.","src":"기출 2021-41"},{"t":"행정기관의 장은 소관사무를 통할하고 소속공무원을 지휘·감독한다.","src":"정부조직법 제7조 제1항 | 기출 2021-41 | 기출 2025-44"},{"t":"행정기관 또는 소속기관을 설치하거나 공무원의 정원을 증원할 때에는 반드시 예산상의 조치가 병행되어야 한다.","src":"정부조직법 제9조 | 기출 2023-43"},{"t":"중앙행정기관은 부·처·청과 법률에 따라 설치되는 위원회 등이다. 보조기관은 차관·차장·실장·국장·과장, 보좌기관은 정책의 기획·계획의 입안 등을 보좌하는 기관이다.","src":"정부조직법 제2조"},{"t":"행정기관의 종류: 행정청(의사 결정·표시), 보조기관, 보좌기관, 자문기관, 의결기관, 집행기관, 감사기관 등.","src":"보충"},{"t":"징계위원회 같은 의결기관으로서의 위원회는 의결권만 갖고, 정해진 의사를 대외적으로 표시할 권한은 없다. 대외적 표시는 행정청이 한다.","src":"기출 2022-46"},{"t":"상급행정기관의 하급행정기관에 대한 승인·동의·지시는 국민의 권리·의무에 직접 영향을 미치지 않는 한 행정처분이 아니다.","src":"기출 2025-44"}]},{"머리":"국무총리 소속 행정기관","줄":[{"t":"법제처는 국무총리 소속 행정기관이다.","src":"정부조직법 제25조 | 기출 2023-45 | 기출 2025-44"},{"t":"국무총리 소속 기관(현행 정부조직법): 기획예산처, 인사혁신처, 법제처, 식품의약품안전처, 국가데이터처, 지식재산처 (국무조정실, 국무총리비서실 포함).","src":"정부조직법 제20조~제28조"},{"t":"국세청은 재정경제부장관 소속이다. 특허청(현 지식재산처)·통계청(현 국가데이터처)은 현재 국무총리 소속 처로 개편되었다. 2023 기출 당시 정답은 법제처였다.","src":"정부조직법 제28조·제27조·제30조 | 기출 2023-45"},{"t":"대통령경호처는 대통령 소속(경호)이다. 국무총리 소속이 아니다.","src":"정부조직법 제16조 | 기출 2023-45"},{"t":"대통령은 정부의 수반으로서 법령에 따라 모든 중앙행정기관의 장을 지휘·감독하며, 국무총리와 중앙행정기관의 장의 위법·부당한 명령이나 처분을 중지 또는 취소할 수 있다. 국무총리는 대통령의 명을 받아 중앙행정기관의 장을 지휘·감독하며 대통령의 승인을 받아 중지·취소할 수 있다.","src":"정부조직법 제11조·제18조"}]},{"머리":"권한의 위임·위탁·내부위임","줄":[{"t":"행정기관은 법령으로 정하는 바에 따라 소관사무의 일부를 보조기관 또는 하급행정기관에 위임하거나 다른 행정기관·지방자치단체 또는 그 기관에 위탁 또는 위임할 수 있다.","src":"정부조직법 제6조 제1항 | 기출 2023-43"},{"t":"위임 또는 위탁을 받은 기관은 특히 필요한 경우 법령으로 정하는 바에 따라 일부를 보조기관 또는 하급행정기관에 재위임할 수 있다.","src":"정부조직법 제6조 제1항 | 기출 2021-40"},{"t":"권한의 위임은 위임기관의 권한의 일부에 한하여 인정된다. 위임은 권한의 법적 귀속을 변경하므로 법률이 위임을 허용하고 있는 경우에 한하여 인정된다.","src":"기출 2024-45 | 기출 2023-43"},{"t":"위임(법정 위임)은 권한 자체가 수임자에게 이전된다. 대리는 권한 자체가 이전되지 않는다.","src":"기출 2024-45 | 보충"},{"t":"위임: 법률에 규정된 행정기관의 장의 권한 중 일부를 보조기관 또는 하급행정기관의 장이나 지방자치단체의 장에게 맡겨 그의 권한과 책임 아래 행사하도록 하는 것.","src":"행정권한의 위임 및 위탁에 관한 규정 제2조 제1호 | 기출 2021-40"},{"t":"위탁: 법률에 규정된 행정기관의 장의 권한 중 일부를 다른 행정기관의 장에게 맡겨 그의 권한과 책임 아래 행사하도록 하는 것.","src":"행정권한의 위임 및 위탁에 관한 규정 제2조 제2호"},{"t":"민간위탁: 법률에 규정된 행정기관의 사무 중 일부를 지방자치단체가 아닌 법인·단체 또는 그 기관이나 개인에게 맡겨 그의 명의로 그의 책임 아래 행사하도록 하는 것. 조사·검사·검정·관리 사무 등 국민의 권리·의무와 직접 관계되지 않는 사무를 위탁할 수 있다.","src":"행정권한의 위임 및 위탁에 관한 규정 제2조 제3호·제11조"},{"t":"내부위임: 법률이 위임을 허용하고 있지 아니한 경우에도 행정관청의 내부적인 사무처리의 편의를 도모하기 위하여 그의 보조기관 또는 하급행정관청으로 하여금 그의 권한을 사실상 행사하게 하는 것. 법적 근거가 필요 없다.","src":"기출 2021-40 | 기출 2023-43"},{"t":"내부위임에 따라 수임관청이 자신의 이름으로 처분을 한 경우 그 처분에 대한 항고소송(무효확인소송 포함)의 피고는 수임관청이다. 위임관청이 아니다.","src":"기출 2022-45 | 기출 2024-45"},{"t":"위임기관은 수임기관의 수임사무 처리에 대하여 지휘·감독하고, 그 처리가 위법하거나 부당하다고 인정될 때에는 이를 취소하거나 정지시킬 수 있다.","src":"행정권한의 위임 및 위탁에 관한 규정 제6조 | 기출 2021-40 | 기출 2025-45"},{"t":"수임사무의 처리에 관하여 위임기관은 수임기관에 대하여 사전승인을 받거나 협의를 할 것을 요구할 수 없다.","src":"행정권한의 위임 및 위탁에 관한 규정 제7조 | 기출 2021-40 | 기출 2024-45 | 기출 2025-45"},{"t":"수임사무 처리에 관한 책임은 수임기관에 있으며 위임기관은 감독책임을 진다. 권한을 행사할 때에는 수임기관의 명의로 하여야 한다.","src":"행정권한의 위임 및 위탁에 관한 규정 제8조"},{"t":"위임·위탁 전에 수임기관의 수임능력 여부를 점검하고 필요한 인력 및 예산을 이관하여야 한다. 위임기관은 수임사무 처리 상황을 수시로 감사할 수 있다.","src":"행정권한의 위임 및 위탁에 관한 규정 제3조·제9조"},{"t":"지방자치단체의 장 등이 수임사무의 일부를 재위임하려면 위임기관의 승인을 받아 규칙으로 정하는 바에 따라 시장·군수·구청장 또는 읍·면·동장 등에게 다시 위임할 수 있다.","src":"행정권한의 위임 및 위탁에 관한 규정 제4조 | 기출 2022-45 | 기출 2025-45"},{"t":"국가사무가 도지사에게 기관위임된 경우 도지사가 이를 군수에게 재위임하려면 도 조례가 아니라 위임기관의 승인을 받아 규칙으로 하여야 한다.","src":"기출 2024-45 | 행정권한의 위임 및 위탁에 관한 규정 제4조"},{"t":"국가사무가 지방자치단체의 장에게 위임된 기관위임사무는 원칙적으로 자치조례의 제정 범위에 속하지 않는다.","src":"기출 2025-45"},{"t":"지방자치단체가 국가사무를 수임한 경우 그 처리에 드는 경비는 위임한 국가기관이 부담한다. 수임한 지방자치단체가 부담하지 않는다.","src":"기출 2025-45 | 보충"}]},{"머리":"권한의 대리","줄":[{"t":"임의대리: 피대리 행정청의 수권에 의하여 대리관계가 성립한다. 일반적·포괄적 수권은 허용되지 않는다.","src":"보충"},{"t":"법정대리: 법정사실의 발생으로 법상 당연히 대리관계가 성립하는 것(협의의 법정대리), 또는 일정한 자가 대리자를 지정하는 지정대리가 있다.","src":"기출 2022-45 | 보충"},{"t":"법정사실이 발생하여 당연히 특정한 자에게 대리권이 부여되는 것은 협의의 법정대리이고, 지정대리는 법정사실 발생 시 일정한 자가 대리자를 지정하는 것이다.","src":"기출 2022-45"},{"t":"대리권을 수여받은 데 불과하여 자신의 명의로는 행정처분을 할 권한이 없는 행정청이 대리관계를 밝힘이 없이 그 자신의 명의로 처분을 하였다면 처분명의자인 해당 행정청이 항고소송의 피고가 된다.","src":"기출 2025-39"}]},{"머리":"훈령과 행정청 간의 관계","줄":[{"t":"훈령: 상급관청이 하급관청의 권한행사를 지휘하기 위하여 발하는 명령.","src":"기출 2022-46"},{"t":"공무원이 대외적 구속력이 없는 훈령에 위반한 경우에도 그 행위가 위법하게 되는 것은 아니며, 징계책임이 부과될 수 있을 뿐이다.","src":"기출 2022-46"},{"t":"상급관청은 직권에 의해 하급관청의 위법·부당한 행위의 취소를 명할 수 있다(감독권).","src":"기출 2022-46"},{"t":"주관쟁의결정권: 하급관청 사이에 권한의 분쟁이 있는 경우 상급관청이 그 분쟁을 해결하고 결정하는 권한.","src":"기출 2022-46"},{"t":"상급관청의 지휘·감독권에는 감시권, 인가권, 훈령권, 취소·정지권, 주관쟁의결정권이 있다.","src":"보충"},{"t":"행정청의 관할이 분명하지 아니한 경우 공통으로 감독하는 상급 행정청이 관할을 결정하고, 공통 상급 행정청이 없으면 각 상급 행정청이 협의하여 결정한다.","src":"행정절차법 제6조 제2항"}]}],"함정":[{"x":"행정기관은 위임을 받은 사무의 전부 또는 일부를 보조기관 또는 하급행정기관에 재위임할 수 없다.","o":"특히 필요한 경우 법령으로 정하는 바에 따라 일부를 재위임할 수 있다.","src":"기출 2021-40 | 정부조직법 제6조 제1항"},{"x":"법령에 따라 행정권한을 위탁받은 사인은 행정청이 될 수 없다.","o":"위탁받은 사인도 행정청이 될 수 있다.","src":"기출 2021-41 | 행정절차법 제2조 제1호"},{"x":"내부위임의 경우 수임관청이 자신의 명의로 행정처분을 하였더라도 항고소송에서의 피고는 위임관청이 된다.","o":"수임관청이 자기 이름으로 처분을 하면 수임관청이 피고다.","src":"기출 2022-45 | 기출 2024-45"},{"x":"권한의 위임은 반드시 법적 근거를 요하는 것은 아니다.","o":"권한의 위임은 법적 근거를 요한다. 내부위임은 법적 근거가 필요 없다.","src":"기출 2022-45 | 기출 2023-43"},{"x":"지정대리란 법정사실이 발생하면 법상 당연히 특정한 자에게 대리권이 부여되어 대리관계가 성립하는 것을 말한다.","o":"이는 협의의 법정대리의 설명이다. 지정대리는 법정사실 발생 시 일정한 자가 대리자를 지정하는 것이다.","src":"기출 2022-45"},{"x":"징계위원회 같은 의결기관으로서의 위원회는 의결권은 물론이고 정해진 의사를 대외적으로 표시할 권한을 갖는다.","o":"의결기관은 의결권만 갖고 대외적 표시권한은 행정청에 있다.","src":"기출 2022-46"},{"x":"행정권한의 내부위임은 법률이 위임을 허용하고 있는 경우에 한하여 인정된다.","o":"내부위임은 법률의 위임 허용이 없어도 인정된다.","src":"기출 2023-43"},{"x":"권한의 위임은 권한 자체를 수임자에게 이전하지 않는 점에서 권한 자체가 이전되는 권한의 대리와 구별된다.","o":"위임은 권한이 수임자에게 이전되고, 대리는 권한이 이전되지 않는다.","src":"기출 2024-45"},{"x":"국가사무가 도지사에게 기관위임된 경우 도지사가 이를 군수에게 재위임하기 위해서는 도 조례에 의하여야 한다.","o":"위임기관의 승인을 받아 규칙으로 정한다.","src":"기출 2024-45"},{"x":"내부위임에 따라 수임관청이 자신의 이름으로 처분을 한 경우 그 처분에 대한 무효확인 소송의 피고는 위임관청이 된다.","o":"피고는 수임관청이다.","src":"기출 2024-45"},{"x":"「행정권한의 위임 및 위탁에 관한 규정」에 따르면 수임사무의 처리에 관하여 위임기관은 수임기관에 대하여 사전승인을 받을 것을 요구할 수 있다.","o":"요구할 수 없다.","src":"기출 2024-45 | 행정권한의 위임 및 위탁에 관한 규정 제7조"},{"x":"상급행정기관의 하급행정기관에 대한 승인·동의·지시는 국민의 권리 의무에 직접 영향을 미치지 않더라도 행정처분에 해당한다.","o":"국민의 권리·의무에 직접 영향을 미치지 않으면 행정처분이 아니다.","src":"기출 2025-44"},{"x":"지방자치단체가 국가사무를 수임한 경우에는 수임한 지방자치단체에서 그 경비를 부담하여야 한다.","o":"위임한 국가기관이 경비를 부담한다.","src":"기출 2025-45"}]},"지방자치법":{"묶음":[{"머리":"주민","줄":[{"t":"지방자치단체의 구역에 주소를 가진 자는 그 지방자치단체의 주민이 된다.","src":"지방자치법 제16조"},{"t":"주민의 권리: 정책의 결정 및 집행 과정에 참여할 권리, 재산과 공공시설을 이용할 권리, 균등하게 행정의 혜택을 받을 권리, 지방선거에 참여할 권리.","src":"지방자치법 제17조"},{"t":"주민투표: 지방자치단체의 장은 주민에게 과도한 부담을 주거나 중대한 영향을 미치는 주요 결정사항 등에 대하여 주민투표에 부칠 수 있다. 주민투표 회부권은 지방자치단체의 장에게 있고 지방의회의 권한이 아니다.","src":"지방자치법 제18조 | 기출 2024-46"},{"t":"주민투표권은 헌법상 보장되는 기본권 또는 헌법상 제도적으로 보장되는 주관적 공권이 아니다. 법률상 권리다.","src":"기출 2025-46"},{"t":"주민은 지방자치단체의 조례를 제정하거나 개정하거나 폐지할 것을 청구할 수 있다.","src":"지방자치법 제19조 | 기출 2025-46"},{"t":"주민은 규칙(권리·의무와 직접 관련되는 사항에 한함)의 제정·개정·폐지와 관련된 의견을 지방자치단체의 장에게 제출할 수 있고, 장은 의견이 제출된 날부터 30일 이내에 검토 결과를 통보하여야 한다.","src":"지방자치법 제20조"},{"t":"주민소환: 주민은 지방자치단체의 장 및 지방의회의원(비례대표 지방의회의원은 제외)을 소환할 권리를 가진다.","src":"지방자치법 제25조 | 기출 2025-46"}]},{"머리":"주민감사청구","줄":[{"t":"18세 이상의 주민이 시·도는 300명, 인구 50만 이상 대도시는 200명, 그 밖의 시·군 및 자치구는 150명 이내에서 조례로 정하는 수 이상 연대 서명하여 사무처리가 법령에 위반되거나 공익을 현저히 해친다고 인정되면 시·도는 주무부장관에게, 시·군 및 자치구는 시·도지사에게 감사를 청구할 수 있다.","src":"지방자치법 제21조 제1항"},{"t":"감사청구 제외 대상: 수사나 재판에 관여하게 되는 사항, 개인의 사생활을 침해할 우려가 있는 사항, 다른 기관에서 감사하였거나 감사 중인 사항(새로운 사항 발견·중요 사항 누락·주민소송 대상인 경우 제외), 동일한 사항에 대하여 주민소송이 진행 중이거나 판결이 확정된 사항.","src":"지방자치법 제21조 제2항"},{"t":"감사청구는 사무처리가 있었던 날이나 끝난 날부터 3년이 지나면 제기할 수 없다.","src":"지방자치법 제21조 제3항"},{"t":"주무부장관이나 시·도지사는 청구를 받으면 5일 이내에 내용을 공표하고, 공표한 날부터 10일간 청구인명부를 열람하게 한다. 청구를 수리한 날부터 60일 이내에 감사를 끝내야 하며, 정당한 사유가 있으면 기간을 연장할 수 있다.","src":"지방자치법 제21조 제5항·제9항"},{"t":"감사 결과에 따라 기간을 정하여 해당 지방자치단체의 장에게 필요한 조치를 요구할 수 있다.","src":"지방자치법 제21조 제12항"}]},{"머리":"주민소송","줄":[{"t":"주민소송은 공금의 지출, 재산의 취득·관리·처분, 계약의 체결·이행, 지방세·사용료·수수료·과태료 등 공금의 부과·징수를 게을리한 사항에 관해 주민감사청구를 한 주민이 제기할 수 있다. 주민소송을 제기하기 전에 주민감사청구를 거쳐야 한다.","src":"지방자치법 제22조 제1항 | 기출 2021-48 | 기출 2022-49"},{"t":"주민소송은 감사청구한 사항과 동일할 필요는 없고, 감사청구한 사항과 관련이 있는 위법한 행위나 업무를 게을리한 사실이면 된다.","src":"지방자치법 제22조 제1항 | 기출 2021-48"},{"t":"주민소송 제기 사유: 감사 청구를 수리한 날부터 60일이 지나도 감사를 끝내지 아니한 경우, 감사 결과 또는 조치 요구에 불복하는 경우, 조치 요구를 지방자치단체의 장이 이행하지 아니한 경우, 지방자치단체의 장의 이행 조치에 불복하는 경우.","src":"지방자치법 제22조 제1항"},{"t":"주민소송의 유형 1호: 해당 행위를 계속하면 회복하기 어려운 손해가 발생할 우려가 있는 경우 그 행위의 전부나 일부를 중지할 것을 요구하는 소송.","src":"지방자치법 제22조 제2항 제1호 | 기출 2022-49"},{"t":"유형 2호: 행정처분인 해당 행위의 취소 또는 변경을 요구하거나 그 행위의 효력 유무 또는 존재 여부의 확인을 요구하는 소송.","src":"지방자치법 제22조 제2항 제2호 | 기출 2021-48"},{"t":"유형 3호: 게을리한 사실의 위법 확인을 요구하는 소송. 공금의 부과·징수 업무를 게을리한 사실의 위법 확인을 요구하는 주민소송은 인정된다.","src":"지방자치법 제22조 제2항 제3호 | 기출 2021-48"},{"t":"유형 4호: 해당 지방자치단체의 장 및 직원, 지방의회의원, 해당 행위와 관련이 있는 상대방에게 손해배상청구 또는 부당이득반환청구를 할 것을 요구하는 소송. 지방의회의원에게 손해배상청구를 요구하는 주민소송도 인정된다.","src":"지방자치법 제22조 제2항 제4호 | 기출 2021-48"},{"t":"중지청구소송은 해당 행위를 중지할 경우 생명이나 신체에 중대한 위해가 생길 우려가 있거나 공공복리를 현저하게 해칠 우려가 있으면 제기할 수 없다.","src":"지방자치법 제22조 제3항"},{"t":"소송은 해당 사유에 따른 날부터 90일 이내에 제기하여야 한다.","src":"지방자치법 제22조 제4항"},{"t":"주민소송이 진행 중이면 다른 주민은 같은 사항에 대하여 별도의 소송을 제기할 수 없다.","src":"지방자치법 제22조 제5항 | 기출 2022-49"},{"t":"소송 계속 중에 소송을 제기한 주민이 사망하거나 주민의 자격을 잃으면 소송절차는 중단된다. 감사 청구에 연대 서명한 다른 주민은 안 날부터 6개월 이내에 수계할 수 있고, 수계하지 않으면 소송절차는 종료된다.","src":"지방자치법 제22조 제6항·제7항 | 기출 2022-49"},{"t":"주민소송은 민중소송이며 객관소송이다. 해당 지방자치단체의 사무소 소재지를 관할하는 행정법원의 관할이다.","src":"기출 2022-49 | 지방자치법 제22조 제9항"},{"t":"주민소송에서 당사자는 법원의 허가를 받지 아니하고는 소의 취하, 소송의 화해 또는 청구의 포기를 할 수 없다.","src":"지방자치법 제22조 제14항"}]},{"머리":"조례와 규칙","줄":[{"t":"지방자치단체는 법령의 범위에서 그 사무에 관하여 조례를 제정할 수 있다. 주민의 권리 제한 또는 의무 부과에 관한 사항이나 벌칙은 법률의 위임이 있어야 한다.","src":"지방자치법 제28조 제1항"},{"t":"조례안이 의결되면 의장은 5일 이내에 지방자치단체의 장에게 이송하고, 장은 20일 이내에 공포하거나 이유를 붙여 재의를 요구할 수 있다(일부 재의·수정 재의 불가). 재의 결과 재적의원 과반수 출석과 출석의원 3분의 2 이상 찬성으로 전과 같이 의결하면 조례로 확정된다.","src":"지방자치법 제32조"},{"t":"조례와 규칙은 특별한 규정이 없으면 공포한 날부터 20일이 지나면 효력을 발생한다.","src":"지방자치법 제32조 제8항"},{"t":"지방의회는 자치사무에 관하여 법률에 특별한 규정이 없는 한 지방자치단체장의 고유권한을 침해하지 않는 범위 내에서 조례를 제정할 수 있다.","src":"기출 2025-29"},{"t":"지방자치단체장이 동일 수탁자에게 위탁사무를 재위탁하고자 할 때 지방의회의 동의를 받도록 한 조례안은 집행권한을 본질적으로 침해하는 것으로 볼 수 없다.","src":"기출 2025-46"}]},{"머리":"지방의회","줄":[{"t":"지방의회 의결사항: 조례의 제정·개정 및 폐지, 예산의 심의·확정, 결산의 승인, 법령에 규정된 것을 제외한 사용료·수수료·분담금·지방세 또는 가입금의 부과와 징수, 기금의 설치·운용, 대통령령으로 정하는 중요 재산의 취득·처분, 대통령령으로 정하는 공공시설의 설치·처분, 법령과 조례에 규정된 것을 제외한 예산 외의 의무부담이나 권리의 포기, 청원의 수리와 처리, 외국 지방자치단체와의 교류·협력, 그 밖에 법령에 따라 그 권한에 속하는 사항.","src":"지방자치법 제47조 제1항 | 기출 2024-46"},{"t":"지방의회의 권한: 결산과 관련한 검사위원 선임, 지방의회의원 자격상실에 대한 의결(재적의원 3분의 2 이상 찬성), 기금의 설치·운용에 관한 의결, 청원의 수리와 처리에 관한 의결.","src":"지방자치법 제47조·제92조·제150조 | 기출 2024-46"},{"t":"지방의회는 매년 2회 정례회를 개최하고, 매년 1회 시·도에서는 14일, 시·군 및 자치구에서는 9일의 범위에서 행정사무 감사를 실시한다. 조사는 재적의원 3분의 1 이상의 발의와 본회의 의결이 필요하다.","src":"지방자치법 제53조·제49조"},{"t":"지방의회의원 정수의 2분의 1 범위에서 해당 지방자치단체의 조례로 정하는 바에 따라 지방의회에 정책지원 전문인력을 둘 수 있다.","src":"지방자치법 제41조 | 기출 2025-46"},{"t":"의장과 부의장의 임기는 2년이다. 불신임은 재적의원 4분의 1 이상의 발의와 재적의원 과반수의 찬성으로 의결한다.","src":"지방자치법 제57조·제62조"}]},{"머리":"지방자치단체의 장·경계변경","줄":[{"t":"지방자치단체의 장은 주민이 보통·평등·직접·비밀선거로 선출하며 임기는 4년으로 3기 내에서만 계속 재임할 수 있다.","src":"지방자치법 제107조·제108조"},{"t":"지방자치단체의 장은 지방의회의 의결이 월권이거나 법령에 위반되거나 공익을 현저히 해친다고 인정되면 이송받은 날부터 20일 이내에 이유를 붙여 재의를 요구할 수 있다. 재적의원 과반수 출석과 출석의원 3분의 2 이상 찬성으로 전과 같이 의결하면 확정되고, 법령에 위반된다고 인정되면 대법원에 소를 제기할 수 있다.","src":"지방자치법 제120조"},{"t":"선결처분: 지방의회가 의결정족수에 미달될 때나 주민의 생명과 재산 보호를 위하여 긴급하게 필요한 사항으로서 지방의회를 소집할 시간적 여유가 없거나 의결이 지체되는 경우 선결처분을 할 수 있다. 지체 없이 지방의회에 보고하여 승인을 받아야 하고, 승인을 받지 못하면 그때부터 효력을 상실한다.","src":"지방자치법 제122조"},{"t":"관할 구역 경계변경: 지방자치단체의 장은 관할 구역과 생활권과의 불일치 등 대통령령으로 정하는 사유가 있으면 행정안전부장관에게 경계변경에 대한 조정을 신청할 수 있다. 이 경우 지방의회 재적의원 과반수의 출석과 출석의원 3분의 2 이상의 동의를 받아야 한다.","src":"지방자치법 제6조 제1항 | 기출 2023-49"},{"t":"지방자치단체의 명칭과 구역을 바꾸거나 폐지·설치·분합할 때에는 법률로 정한다. 관할 구역 경계변경과 한자 명칭 변경은 대통령령으로 정한다.","src":"지방자치법 제5조 제1항·제2항"},{"t":"지방자치단체의 사무: 자치사무와 법령에 따라 지방자치단체에 속하는 사무. 국가사무는 시·도지사와 시장·군수·구청장에게 위임하여 수행하는 것이 원칙이다(기관위임사무).","src":"지방자치법 제13조·제115조"},{"t":"지방자치단체가 처리할 수 없는 국가사무: 외교·국방·사법·국세, 물가·금융·수출입정책, 농산물 등 수급조절, 국가종합경제개발계획·국가하천·국유림·지정항만·고속국도 등, 근로기준·측량단위 등, 우편·철도 등, 고도의 기술이 필요한 검사·시험·연구·항공관리·기상행정·원자력개발.","src":"지방자치법 제15조"}]}],"함정":[{"x":"지방의회의원에게 손해배상청구를 할 것을 요구하는 주민소송은 인정되지 않는다.","o":"지방의회의원에게 손해배상청구 또는 부당이득반환청구를 할 것을 요구하는 주민소송이 인정된다.","src":"기출 2021-48 | 지방자치법 제22조 제2항 제4호"},{"x":"주민소송이 진행 중이라도 다른 주민은 같은 사항에 대하여 별도의 소송을 제기할 수 있다.","o":"같은 사항에 대하여 별도의 소송을 제기할 수 없다.","src":"기출 2022-49"},{"x":"지방자치단체의 주민은 그 지방자치단체의 장 및 비례대표 지방의회의원을 포함한 지방의회의원을 소환할 권리를 가진다.","o":"비례대표 지방의회의원은 소환 대상에서 제외된다.","src":"기출 2025-46 | 지방자치법 제25조"},{"x":"주민투표 회부권은 지방의회의 권한이다.","o":"주민투표 회부권은 지방자치단체의 장에게 있다.","src":"기출 2024-46"}]},"공무원법":{"묶음":[{"머리":"공무원의 구분","줄":[{"t":"국가공무원은 경력직공무원과 특수경력직공무원으로 구분한다.","src":"국가공무원법 제2조 제1항"},{"t":"경력직공무원: 일반직공무원(기술·연구 또는 행정 일반 업무)과 특정직공무원(법관, 검사, 외무공무원, 경찰공무원, 소방공무원, 교육공무원, 군인, 군무원, 헌법연구관, 국가정보원 직원, 경호공무원 등).","src":"국가공무원법 제2조 제2항"},{"t":"법관, 검사, 외무공무원은 특정직공무원이다. 일반직공무원이 아니다. 검사는 특정직공무원에 해당한다.","src":"국가공무원법 제2조 제2항 | 기출 2023-46 | 기출 2025-49"},{"t":"특수경력직공무원: 정무직공무원(선거로 취임하거나 임명에 국회 동의가 필요한 공무원, 고도의 정책결정 업무 담당 공무원)과 별정직공무원(비서관·비서 등). 정무직공무원은 특수경력직공무원에 해당한다.","src":"국가공무원법 제2조 제3항 | 기출 2025-49"},{"t":"직위: 1명의 공무원에게 부여할 수 있는 직무와 책임. 직급: 직무의 종류·곤란성과 책임도가 상당히 유사한 직위의 군이다.","src":"국가공무원법 제5조 | 기출 2025-49"},{"t":"공무원의 신분과 지위의 특수성상 공무원에 대해서는 일반 국민에 비해 보다 넓고 강한 기본권 제한이 가능하다.","src":"기출 2023-46"}]},{"머리":"임용·결격사유","줄":[{"t":"국가기관의 장은 소속 공무원을 임용할 때 합리적인 이유 없이 사회적 신분을 이유로 차별해서는 아니 된다.","src":"기출 2023-46"},{"t":"공무원 임용 결격사유: 피성년후견인, 파산선고를 받고 복권되지 아니한 자, 금고 이상 실형 집행 종료·면제 후 5년 미경과, 금고 이상 집행유예 기간 종료 후 2년 미경과, 금고 이상 선고유예 기간 중, 법원 판결 또는 법률에 따라 자격 상실·정지된 자, 일정 범죄(공무원 재직 중 직무 관련 횡령·배임 300만원 이상 벌금 후 2년 미경과 등), 징계 파면 후 5년 미경과, 징계 해임 후 3년 미경과.","src":"국가공무원법 제33조"},{"t":"임용 당시 공무원임용결격사유가 있었다면 비록 국가의 과실에 의하여 임용결격자임을 밝혀내지 못하였다 하더라도 그 임용행위는 당연무효이다.","src":"기출 2022-48 | 기출 2024-44"},{"t":"공무원임용결격사유가 있는지의 여부는 임용 당시의 법률을 기준으로 판단한다.","src":"기출 2022-48"},{"t":"임용결격자에 대한 임용행위가 당연무효이므로 국가가 사후에 이를 발견하여 취소하는 것은 취소권의 시효 제한을 받지 않는다.","src":"기출 2022-48"},{"t":"임용행위의 하자로 임용행위가 취소되어 소급적으로 공무원의 지위를 상실한 자는 공무원연금법상 퇴직급여를 청구할 수 없다.","src":"기출 2024-44"},{"t":"모든 공무원은 법령을 준수하며 성실히 직무를 수행하여야 한다.","src":"국가공무원법 제56조 | 기출 2023-46"},{"t":"공무원이 직무 수행에서 소속 상관의 명백한 위법 내지 불법한 명령에 따라야 할 의무는 없다.","src":"기출 2023-46"},{"t":"공무원의 의무: 성실, 복종, 직장 이탈 금지, 친절·공정, 비밀 엄수, 청렴, 외국 정부의 영예 등 수령 시 대통령 허가, 품위 유지, 정치운동 금지, 집단행위 금지(사실상 노무 종사자 예외).","src":"국가공무원법 제56조~제66조"}]},{"머리":"휴직·직위해제·면직","줄":[{"t":"직위해제 사유: 직무수행 능력이 부족하거나 근무성적이 극히 나쁜 자, 파면·해임·강등 또는 정직에 해당하는 징계 의결이 요구 중인 자, 형사 사건으로 기소된 자(약식명령 청구자 제외), 고위공무원단 적격심사 요구를 받은 자, 금품비위·성범죄 등으로 감사원·수사기관에서 조사나 수사 중인 자로서 비위가 중대하여 정상적인 업무수행을 기대하기 현저히 어려운 자.","src":"국가공무원법 제73조의3 제1항"},{"t":"직위해제는 징계처분이 아니라 잠정적 보직 박탈이다.","src":"기출 2021-49 | 기출 2022-48"},{"t":"직위해제처분과 그 후속 직권면직처분은 별개 독립의 처분으로 일사부재리원칙에 위배되지 않는다. 직위해제 후 동일한 사유로 다시 해임처분을 하는 것도 일사부재리에 어긋나지 않는다.","src":"기출 2021-49 | 기출 2024-44"},{"t":"직위해제 사유가 소멸되면 임용권자는 지체 없이 직위를 부여하여야 한다. 직무수행 능력 부족 등으로 직위해제된 자에게는 3개월의 범위에서 대기를 명한다.","src":"국가공무원법 제73조의3 제2항·제3항"},{"t":"직권면직 사유: 직제와 정원의 개폐 또는 예산 감소에 따른 폐직·과원, 휴직 기간 종료 후 복귀하지 않거나 직무를 감당할 수 없을 때, 대기 명령을 받은 자의 능력·근무성적 향상을 기대하기 어려운 때, 전직시험 3회 이상 불합격, 병역 관련 기피·이탈, 필요한 자격증 효력 상실·면허 취소, 고위공무원단 적격심사 부적격 결정.","src":"국가공무원법 제70조"},{"t":"당연퇴직 사유: 결격사유(임용 후 발생) 등. 공무원이 당연퇴직 사유에 해당하면 법률상 당연히 퇴직되며, 당연퇴직 인사발령은 관념의 통지로서 항고소송의 대상이 되는 처분이 아니다.","src":"국가공무원법 제69조 | 기출 2024-44 | 보충"},{"t":"공무원의 정년은 60세다. 정년에 이른 날이 1월부터 6월 사이에 있으면 6월 30일에, 7월부터 12월 사이에 있으면 12월 31일에 각각 당연히 퇴직된다.","src":"국가공무원법 제74조"},{"t":"국가공무원법상의 직위해제처분에는 의견청취에 관한 행정절차법 규정이 적용되지 않는다.","src":"기출 2024-44"},{"t":"시험승진후보자명부에서의 삭제행위는 행정처분이 아니다.","src":"기출 2022-48"},{"t":"공무원에 대하여 징계처분 등을 할 때나 강임·휴직·직위해제 또는 면직처분을 할 때에는 처분사유를 적은 설명서를 교부하여야 한다. 본인의 원에 따른 강임·휴직 또는 면직처분은 설명서를 교부하지 않아도 된다.","src":"국가공무원법 제75조 | 기출 2025-49"}]},{"머리":"징계","줄":[{"t":"징계의 종류: 파면·해임·강등·정직·감봉·견책의 6가지.","src":"국가공무원법 제79조"},{"t":"강등: 1계급 아래로 직급을 내리고 신분은 보유하나 3개월간 직무에 종사하지 못하며 그 기간 중 보수는 전액을 감한다. 정직: 1개월 이상 3개월 이하이며 보수는 전액을 감한다. 감봉: 1개월 이상 3개월 이하이며 보수의 3분의 1을 감한다. 견책: 전과에 대하여 훈계하고 회개하게 한다.","src":"국가공무원법 제80조"},{"t":"징계 사유: 국가공무원법 및 명령 위반, 직무상 의무 위반 또는 직무 태만, 직무의 내외를 불문하고 체면 또는 위신을 손상하는 행위.","src":"국가공무원법 제78조"},{"t":"징계부가금: 금품·향응 등 취득·제공이나 예산·기금·국유재산 횡령 등의 경우 해당 이득의 5배 내의 징계부가금 부과 의결을 요구하여야 한다.","src":"국가공무원법 제78조의2"},{"t":"파면과 해임은 징계위원회의 의결을 거쳐 각 임용권자 또는 임용권을 위임한 상급 감독기관의 장이 한다.","src":"국가공무원법 제82조 제1항"}]},{"머리":"소청심사","줄":[{"t":"행정기관 소속 공무원의 징계처분, 그 밖에 그 의사에 반하는 불리한 처분이나 부작위에 대한 소청을 심사·결정하게 하기 위하여 인사혁신처에 소청심사위원회를 둔다. 국회·법원·헌법재판소·선거관리위원회 소속 공무원은 각 사무처에 해당 소청심사위원회를 둔다.","src":"국가공무원법 제9조"},{"t":"처분사유 설명서를 받은 공무원이 불복할 때에는 설명서를 받은 날부터, 그 밖의 불리한 처분은 그 처분이 있은 것을 안 날부터 30일 이내에 소청심사위원회에 심사를 청구할 수 있다.","src":"국가공무원법 제76조 제1항"},{"t":"소청심사위원회는 청구를 접수한 날부터 60일 이내에 결정하여야 하며, 불가피하면 의결로 30일을 연장할 수 있다.","src":"국가공무원법 제76조 제5항"},{"t":"소청심사위원회가 소청 사건을 심사할 때 소청인 또는 대리인에게 진술 기회를 주어야 하며, 진술 기회를 주지 아니한 결정은 무효로 한다.","src":"국가공무원법 제13조 | 기출 2021-49"},{"t":"소청심사위원회의 결정은 그 이유를 구체적으로 밝힌 결정서로 하여야 한다.","src":"국가공무원법 제14조 제9항 | 기출 2021-49"},{"t":"소청심사위원회의 결정은 처분 행정청을 기속한다.","src":"국가공무원법 제15조 | 기출 2021-49 | 기출 2025-49"},{"t":"소청심사위원회가 징계처분의 취소·변경을 구한 소청을 심사할 때에는 원징계처분보다 무거운 징계를 부과하는 결정을 하지 못한다.","src":"국가공무원법 제14조 제8항"},{"t":"본인의 의사에 반한 불리한 처분에 관한 행정소송은 소청심사위원회의 심사·결정을 거치지 아니하면 제기할 수 없다(필요적 전치). 대통령의 처분의 경우 소속 장관을 피고로 한다.","src":"국가공무원법 제16조"},{"t":"파면 또는 해임 처분에 대한 소청에서 후임자 보충발령은 처분일부터 40일 이내에는 하지 못하며, 소청심사위원회는 청구 접수일부터 5일 이내에 후임자 보충발령 유예 임시결정을 할 수 있다.","src":"국가공무원법 제76조 제2항·제3항"}]}],"함정":[{"x":"공무원에 대한 직위해제처분은 징계처분이다.","o":"직위해제는 징계처분이 아니다.","src":"기출 2021-49 | 기출 2022-48"},{"x":"공무원임용결격사유가 있는지의 여부는 임용당시가 아닌 채용후보자 명부에 등록한 때에 시행되던 법률을 기준으로 하여 판단하여야 한다.","o":"임용 당시의 법률을 기준으로 판단한다.","src":"기출 2022-48"},{"x":"국가가 공무원임용결격사유가 있는 자에 대해 결격사유가 있음을 알지 못하고 임용하였다가 사후에 결격사유가 있는 자임을 발견하고 임용행위를 취소하는 경우, 그 취소권은 시효의 제한을 받는다.","o":"당연무효이므로 취소권의 시효 제한을 받지 않는다.","src":"기출 2022-48"},{"x":"시험승진후보자명부에서의 삭제행위는 행정처분이다.","o":"행정처분이 아니다.","src":"기출 2022-48"},{"x":"직위해제는 징계처분에 해당한다.","o":"징계처분에 해당하지 않는다.","src":"기출 2022-48"},{"x":"법관, 검사, 외무공무원은 일반직공무원에 해당한다.","o":"특정직공무원에 해당한다.","src":"기출 2023-46"},{"x":"공무원에 대한 직위해제처분이 있은 후 동일한 사유로 다시 해임처분을 하는 것은 일사부재리의 법리에 어긋난다.","o":"별개 독립의 처분이므로 일사부재리에 어긋나지 않는다.","src":"기출 2024-44"},{"x":"「국가공무원법」상 당연퇴직의 인사발령은 항고소송의 대상이 되는 처분에 해당한다.","o":"당연퇴직의 인사발령은 항고소송의 대상이 되는 처분이 아니다.","src":"기출 2024-44"},{"x":"「국가공무원법」상의 직위해제처분에는 의견청취에 관한 「행정절차법」 규정이 적용된다.","o":"적용되지 않는다.","src":"기출 2024-44"},{"x":"임용행위의 하자로 임용행위가 취소되어 소급적으로 공무원의 지위를 상실한 자도 「공무원연금법」에서 정한 퇴직급여를 청구할 수 있다.","o":"퇴직급여를 청구할 수 없다.","src":"기출 2024-44"},{"x":"직급이란 1명의 공무원에게 부여할 수 있는 직무와 책임을 말한다.","o":"그것은 직위의 정의다. 직급은 직무의 종류·곤란성과 책임도가 상당히 유사한 직위의 군이다.","src":"기출 2025-49 | 국가공무원법 제5조"}]},"경찰행정법과 공물법·국가재정법":{"묶음":[{"머리":"경찰관 직무집행법: 직무와 불심검문","줄":[{"t":"경찰관의 직무: 국민의 생명·신체 및 재산의 보호, 범죄의 예방·진압 및 수사, 범죄피해자 보호, 경비·주요 인사(人士) 경호 및 대간첩·대테러 작전 수행, 공공안녕에 대한 위험의 예방과 대응을 위한 정보의 수집·작성 및 배포, 교통 단속과 교통 위해의 방지, 외국 정부기관 및 국제기구와의 국제협력, 그 밖에 공공의 안녕과 질서 유지.","src":"경찰관 직무집행법 제2조 | 기출 2025-48"},{"t":"경찰관의 직권은 직무 수행에 필요한 최소한도에서 행사되어야 하며 남용되어서는 아니 된다.","src":"경찰관 직무집행법 제1조 제2항"},{"t":"불심검문 대상: 수상한 행동이나 주위 사정을 합리적으로 판단할 때 죄를 범하였거나 범하려 한다고 의심할 만한 상당한 이유가 있는 사람, 이미 행하여진 범죄나 행하여지려는 범죄행위에 관한 사실을 안다고 인정되는 사람.","src":"경찰관 직무집행법 제3조 제1항"},{"t":"정지시킨 장소에서 질문하는 것이 그 사람에게 불리하거나 교통에 방해가 된다고 인정될 때에는 가까운 경찰관서로 동행할 것을 요구할 수 있다. 동행을 요구받은 사람은 그 요구를 거절할 수 있다.","src":"경찰관 직무집행법 제3조 제2항 | 기출 2024-47"},{"t":"경찰관은 질문을 할 때 그 사람이 흉기를 가지고 있는지를 조사할 수 있다.","src":"경찰관 직무집행법 제3조 제3항 | 기출 2024-47"},{"t":"질문이나 동행 요구 시 신분을 표시하는 증표를 제시하면서 소속과 성명을 밝히고 목적과 이유를 설명하여야 하며, 동행 장소를 밝혀야 한다.","src":"경찰관 직무집행법 제3조 제4항"},{"t":"동행한 사람의 가족이나 친지 등에게 신분·장소·목적·이유를 알리거나 즉시 연락할 기회를 주어야 하며, 변호인의 도움을 받을 권리가 있음을 알려야 한다. 6시간을 초과하여 경찰관서에 머물게 할 수 없다.","src":"경찰관 직무집행법 제3조 제5항·제6항"},{"t":"질문을 받거나 동행을 요구받은 사람은 형사소송에 관한 법률에 따르지 아니하고는 신체를 구속당하지 아니하며, 그 의사에 반하여 답변을 강요당하지 아니한다.","src":"경찰관 직무집행법 제3조 제7항 | 기출 2024-47"}]},{"머리":"보호조치·위험방지·사실확인","줄":[{"t":"보호조치 대상(구호대상자): 정신착란 또는 술에 취하여 자신 또는 타인의 생명·신체·재산에 위해를 끼칠 우려가 있는 사람, 자살을 시도하는 사람, 미아·병자·부상자 등으로서 적당한 보호자가 없고 응급구호가 필요한 사람(본인이 구호를 거절하는 경우 제외).","src":"경찰관 직무집행법 제4조 제1항"},{"t":"구호대상자를 경찰관서에서 보호하는 기간은 24시간을 초과할 수 없고, 휴대한 무기·흉기를 임시 영치하는 기간은 10일을 초과할 수 없다.","src":"경찰관 직무집행법 제4조 제7항"},{"t":"긴급구호를 요청받은 보건의료기관이나 공공구호기관은 정당한 이유 없이 거절할 수 없다.","src":"경찰관 직무집행법 제4조 제2항"},{"t":"위험 발생의 방지: 천재, 사변, 인공구조물의 파손이나 붕괴, 교통사고, 위험물의 폭발 등의 사태가 있을 때 경고, 이동 제한·대피, 원인 제공자의 퇴거·접근 금지, 관계인에게 위해를 방지하기 위해 필요하다고 인정되는 조치를 하게 하거나 직접 그 조치를 하는 것.","src":"경찰관 직무집행법 제5조 제1항 | 기출 2024-47"},{"t":"범죄의 예방과 제지: 범죄행위가 목전에 행하여지려고 한다고 인정될 때 관계인에게 필요한 경고를 하고, 생명·신체의 위해 또는 재산에 중대한 손해를 끼칠 우려가 있는 긴급한 경우 제지할 수 있다.","src":"경찰관 직무집행법 제6조"},{"t":"위험 방지를 위한 출입: 위해가 임박한 때 위해 방지·피해자 구조를 위해 부득이하다고 인정하면 필요한 한도에서 타인의 토지·건물·배·차에 출입할 수 있다. 흥행장·여관·음식점·역 등 공개된 장소의 관리자는 영업시간에 출입 요구를 정당한 이유 없이 거절할 수 없다.","src":"경찰관 직무집행법 제7조"},{"t":"사실의 확인: 경찰관서의 장은 직무 수행에 필요한 상당한 이유가 있을 때 국가기관이나 공사 단체 등에 사실을 조회할 수 있다. 경찰관은 출석 요구서를 보내 경찰관서에 출석할 것을 요구할 수 있다.","src":"경찰관 직무집행법 제8조"},{"t":"출석요구 대상 직무: 미아를 인수할 보호자 확인, 유실물을 인수할 권리자 확인, 사고로 인한 사상자 확인, 행정처분을 위한 교통사고 조사에 필요한 사실 확인. 긴급구호를 요청받은 보건의료기관에 대한 요청사실의 확인은 포함되지 않는다.","src":"경찰관 직무집행법 제8조 제2항 | 기출 2023-47"},{"t":"손실보상: 국가는 경찰관의 적법한 직무집행으로 손실발생의 원인에 책임이 없는 자가 입은 손실, 책임이 있는 자가 자신의 책임에 상응하는 정도를 초과하여 입은 손실에 대해 정당한 보상을 하여야 한다. 청구권은 손실이 있음을 안 날부터 3년, 손실이 발생한 날부터 5년이 지나면 시효로 소멸한다.","src":"경찰관 직무집행법 제11조의2 | 기출 2024-47"},{"t":"경찰장비의 사용: 위해성 경찰장비는 필요한 최소한도에서 사용하여야 한다. 경찰장구는 현행범 등의 체포·도주 방지, 생명·신체의 방어 및 보호, 공무집행에 대한 항거 제지를 위해 필요한 한도에서 사용한다.","src":"경찰관 직무집행법 제10조·제10조의2"}]},{"머리":"경찰책임","줄":[{"t":"행위능력이 없는 자도 경찰책임자가 될 수 있다.","src":"기출 2022-47"},{"t":"행위책임의 행위에는 부작위를 포함한다.","src":"기출 2022-47"},{"t":"물건에 대한 권원의 유무와 관계없이 물건을 현실적으로 지배하고 있는 자에게도 상태책임이 인정된다.","src":"기출 2022-47"},{"t":"경찰책임자에 대한 경찰권의 발동이 어려운 경우에는 예외적으로 경찰책임이 없는 자에게도 경찰권이 발동될 수 있다(긴급 경찰권).","src":"기출 2022-47"},{"t":"타인을 감독하는 자가 타인의 행위에 대하여 지는 경찰책임은 타인의 책임을 대신하여 지는 것이 아니라 자기의 감독의무 위반에 대한 자기책임이다.","src":"기출 2022-47 | 보충"}]},{"머리":"공물법","줄":[{"t":"공공용물: 일반공중의 공동사용에 직접 제공된 공물. 공용물: 행정주체 자신의 사용에 제공된 공물. 보존공물: 공적 목적을 위해 보존되는 공물.","src":"기출 2022-44 | 보충"},{"t":"자연공물: 자연 상태 그대로 공적 목적에 제공된 공물(하천·바다 등). 인공공물: 인공을 가해 공적 목적에 제공된 공물(도로·공원 등).","src":"기출 2022-44 | 보충"},{"t":"국유공물·공유공물·사유공물은 소유권 귀속 주체에 따른 분류다. 국가 또는 지방자치단체가 소유권자인 공물을 모두 국유공물이라 하는 것이 아니다.","src":"기출 2022-44 | 보충"},{"t":"자유공물(自有公物)은 공물의 관리주체와 귀속주체가 같은 공물, 타유공물(他有公物)은 관리주체와 귀속주체가 다른 공물이다.","src":"기출 2022-44 | 보충"},{"t":"경찰견은 동산공물(인공공물, 공용물)에 해당한다.","src":"기출 2022-44"},{"t":"공공용물의 일반사용은 원칙적으로 무료다. 사용료를 납부하지 않는다.","src":"기출 2024-48 | 보충"},{"t":"공물의 인접주민에게 고양된 일반사용권이 인정되려면 공물을 실제로 사용하는 등의 요건이 필요하고, 구체적으로 사용하지 않는 경우에는 인정되지 않는다.","src":"기출 2024-48 | 보충"},{"t":"행정재산이 공용폐지되어 시효취득의 대상이 된다는 증명책임은 시효취득을 주장하는 자에게 있다.","src":"기출 2024-48"},{"t":"하천법상 하천의 점용허가권은 대세적 효력이 있는 물권이 아니다.","src":"기출 2024-48"}]},{"머리":"국유재산법: 구분과 보호","줄":[{"t":"국유재산은 그 용도에 따라 행정재산과 일반재산으로 구분한다. 행정재산은 공용재산, 공공용재산, 기업용재산, 보존용재산이다.","src":"국유재산법 제6조 제1항·제2항"},{"t":"공용재산: 국가가 직접 사무용·사업용 또는 공무원의 주거용으로 사용하거나 대통령령으로 정하는 기한까지 사용하기로 결정한 재산.","src":"국유재산법 제6조 제2항 제1호 | 기출 2025-50"},{"t":"공공용재산: 국가가 직접 공공용으로 사용하거나 대통령령으로 정하는 기한까지 사용하기로 결정한 재산.","src":"국유재산법 제6조 제2항 제2호 | 기출 2025-50"},{"t":"기업용재산: 정부기업이 직접 사무용·사업용 또는 그 기업에 종사하는 직원의 주거용으로 사용하거나 기한까지 사용하기로 결정한 재산.","src":"국유재산법 제6조 제2항 제3호"},{"t":"보존용재산: 법령이나 그 밖의 필요에 따라 국가가 보존하는 재산. 행정재산에 속한다.","src":"국유재산법 제6조 제2항 제4호 | 기출 2021-50 | 기출 2023-50 | 기출 2025-50"},{"t":"일반재산: 행정재산 외의 모든 국유재산.","src":"국유재산법 제6조 제3항"},{"t":"행정재산은 민법 제245조에도 불구하고 시효취득의 대상이 되지 아니한다. 기업용재산도 행정재산이므로 시효취득 대상이 아니다. 일반재산은 시효취득의 대상이 된다.","src":"국유재산법 제7조 제2항 | 기출 2021-50 | 기출 2025-50"},{"t":"국유재산에는 사권을 설정하지 못한다. 다만 일반재산에 대하여 대통령령으로 정하는 경우에는 예외다. 행정재산에는 사권을 설정하지 못한다.","src":"국유재산법 제11조 제2항 | 기출 2021-50"},{"t":"사권이 설정된 재산은 그 사권이 소멸된 후가 아니면 국유재산으로 취득하지 못한다. 판결에 따라 취득하는 경우에는 예외다.","src":"국유재산법 제11조 제1항 | 기출 2025-50"},{"t":"총괄청이나 중앙관서의 장은 소유자 없는 부동산을 국유재산으로 취득한다. 6개월 이상의 기간을 정하여 이의를 제기할 수 있다는 뜻을 공고하여야 하고, 취득한 국유재산은 등기일부터 10년간 처분하지 못한다.","src":"국유재산법 제12조 | 기출 2025-50"},{"t":"행정재산은 처분하지 못한다. 공유 또는 사유재산과 교환하여 행정재산으로 관리하려는 경우 등 예외적으로 교환하거나 양여할 수 있다.","src":"국유재산법 제27조"},{"t":"변상금: 사용허가나 대부계약 없이 국유재산을 사용·수익하거나 점유한 자(허가·대부 기간 종료 후 계속 점유자 포함)에게 사용료나 대부료의 100분의 120에 상당하는 금액을 부과한다.","src":"국유재산법 제72조 | 기출 2024-49"}]},{"머리":"행정재산 사용허가","줄":[{"t":"중앙관서의 장은 공용·공공용·기업용재산은 그 용도나 목적에 장애가 되지 아니하는 범위에서, 보존용재산은 보존목적의 수행에 필요한 범위에서만 사용허가를 할 수 있다. 특별한 제한 없이 허가할 수 있는 것이 아니다.","src":"국유재산법 제30조 제1항 | 기출 2024-48"},{"t":"사용허가를 받은 자는 그 재산을 다른 사람에게 사용·수익하게 하여서는 아니 된다. 기부자·상속인 등의 경우 등 중앙관서의 장의 승인을 받은 경우는 예외.","src":"국유재산법 제30조 제2항"},{"t":"행정재산의 사용허가는 그 뜻을 공고하여 일반경쟁에 부쳐야 한다. 필요하다고 인정되면 참가자격 제한·지명경쟁·수의의 방법으로 할 수 있다.","src":"국유재산법 제31조"},{"t":"행정재산의 사용허가기간은 5년 이내로 한다. 허가기간이 끝난 재산에 대하여 종전 허가기간에 관계없이 5년을 초과하지 않는 범위에서 갱신할 수 있다(수의 허가가 아니면 1회). 갱신 신청은 허가기간이 끝나기 1개월 전에 한다.","src":"국유재산법 제35조 | 기출 2021-50"},{"t":"사용허가 취소·철회 사유: 거짓·부정한 방법, 무단 전대, 보존 게을리·사용목적 위배, 사용료 미납, 승인 없이 원래 상태 변경.","src":"국유재산법 제36조 제1항"},{"t":"중앙관서의 장은 사용허가한 행정재산을 국가나 지방자치단체가 직접 공용이나 공공용으로 사용하기 위하여 필요하게 된 경우에는 그 허가를 철회할 수 있다. 이때 손실이 발생하면 그 재산을 사용할 기관이 보상한다.","src":"국유재산법 제36조 제3항 | 기출 2021-50"},{"t":"사용허가를 취소하거나 철회하려는 경우 청문을 하여야 한다.","src":"국유재산법 제37조"},{"t":"일반재산의 대부기간: 조림 목적 토지와 정착물 20년, 대부받은 자의 비용으로 시설을 보수하는 건물 10년, 그 밖의 토지와 정착물 5년, 그 밖의 재산 1년.","src":"국유재산법 제46조"}]},{"머리":"국가재정법","줄":[{"t":"국가의 회계연도는 매년 1월 1일에 시작하여 12월 31일에 종료한다. 각 회계연도의 경비는 그 연도의 세입 또는 수입으로 충당하여야 한다(회계연도 독립의 원칙).","src":"국가재정법 제2조·제3조 | 기출 2025-47"},{"t":"국가의 회계는 일반회계와 특별회계로 구분한다. 통상회계·임시회계가 아니다.","src":"국가재정법 제4조 | 기출 2025-47"},{"t":"예산 및 기금에 관한 사무는 기획예산처장관이, 결산에 관한 사무는 재정경제부장관이 관장한다(현행). 2025 기출 당시에는 기획재정부장관이 예산·결산·기금 사무를 관장하는 것으로 출제되었다.","src":"국가재정법 제11조 제1항 | 기출 2025-47"},{"t":"정부는 재정건전성의 확보를 위하여 최선을 다하여야 한다. 국민부담의 최소화, 재정지출 성과 제고, 예산과정의 투명성 제고에도 노력한다.","src":"국가재정법 제16조 | 기출 2023-48"},{"t":"정부는 성별영향평가 결과를 포함하여 예산이 여성과 남성에게 미치는 효과를 평가하고 그 결과를 예산편성에 반영하기 위하여 노력하여야 한다.","src":"국가재정법 제16조 제5호 | 기출 2023-48"},{"t":"예산총계주의: 한 회계연도의 모든 수입을 세입으로 하고, 모든 지출을 세출로 한다.","src":"국가재정법 제17조 제1항 | 기출 2023-48 | 기출 2025-47"},{"t":"예산은 예산총칙·세입세출예산·계속비·명시이월비 및 국고채무부담행위를 총칭한다.","src":"국가재정법 제19조 | 기출 2023-48 | 기출 2025-47"},{"t":"예비비: 정부는 예측할 수 없는 예산 외의 지출 또는 예산초과지출에 충당하기 위하여 일반회계 예산총액의 100분의 1 이내의 금액을 예비비로 세입세출예산에 계상할 수 있다. 10분의 1이 아니다.","src":"국가재정법 제22조 | 기출 2023-48"},{"t":"계속비: 완성에 수년이 필요한 공사나 제조 및 연구개발사업은 총액과 연부액을 정하여 국회의 의결을 얻은 범위 안에서 지출한다. 지출 연한은 그 회계연도부터 5년 이내이며 예외적으로 10년 이내로 할 수 있다.","src":"국가재정법 제23조"},{"t":"명시이월비: 경비의 성질상 연도 내에 지출을 끝내지 못할 것이 예측되는 경우 그 취지를 명시하여 국회의 승인을 얻은 후 다음 연도로 이월한다.","src":"국가재정법 제24조"},{"t":"국고채무부담행위: 법률에 따른 것과 세출예산금액 또는 계속비의 총액 범위 안의 것 외에 채무를 부담하는 행위를 하려면 미리 예산으로써 국회의 의결을 얻어야 한다.","src":"국가재정법 제25조"},{"t":"예산 편성 일정: 예산안편성지침은 3월 31일까지 통보, 예산요구서는 5월 31일까지 제출, 예산안은 회계연도 개시 120일 전까지 국회에 제출한다.","src":"국가재정법 제29조·제31조·제33조"},{"t":"각 중앙관서의 장은 세출예산이 정한 목적 외에 경비를 사용할 수 없다. 세항·목 사이의 전용은 기획예산처장관의 승인을 얻어야 한다.","src":"국가재정법 제45조·제46조"},{"t":"매 회계연도의 세출예산은 다음 연도에 이월하여 사용할 수 없다. 명시이월비, 연도 내 지출원인행위를 하고 불가피한 사유로 지출하지 못한 경비 등은 예외다.","src":"국가재정법 제48조"}]}],"함정":[{"x":"일반재산은 민법상 시효취득의 대상이 되지 아니한다.","o":"일반재산은 시효취득의 대상이 된다. 행정재산이 시효취득의 대상이 되지 않는다.","src":"기출 2021-50 | 국유재산법 제7조 제2항"},{"x":"공공용물은 직접 행정주체 자신의 사용에 제공된 공물을 말한다.","o":"그것은 공용물의 정의다. 공공용물은 일반공중의 공동사용에 직접 제공된 공물이다.","src":"기출 2022-44"},{"x":"국가 또는 지방자치단체가 소유권자인 공물을 국유공물이라 한다.","o":"국유공물은 국가가 소유권자인 공물이다. 지방자치단체 소유는 공유공물이다.","src":"기출 2022-44"},{"x":"공물의 관리주체와 공물의 귀속주체가 다른 공물을 자유공물(自有公物)이라고 한다.","o":"관리주체와 귀속주체가 다른 공물은 타유공물이다.","src":"기출 2022-44"},{"x":"도로, 공원 등은 자연공물에 해당한다.","o":"도로, 공원은 인공공물이다.","src":"기출 2022-44"},{"x":"타인을 감독하는 자가 타인의 행위에 대하여 지는 경찰책임은 자기책임이 아니라 타인의 책임을 대신하여 지는 것이다.","o":"자기의 감독의무 위반에 대한 자기책임이다.","src":"기출 2022-47"},{"x":"정부는 예측할 수 없는 예산 외의 지출에 충당하기 위하여 일반회계 예산총액의 100분의 10 이내의 금액을 예비비로 세입세출예산에 계상하여야 한다.","o":"100분의 1 이내의 금액을 계상할 수 있다.","src":"기출 2023-48 | 국가재정법 제22조"},{"x":"경찰관의 적법한 직무집행으로 인하여 손실을 입은 자는 그 손실발생의 원인에 대하여 책임이 있는 경우라도 그 손실 전부에 대하여 보상을 받을 수 있다.","o":"책임이 있는 자는 자신의 책임에 상응하는 정도를 초과하는 손실에 대해서만 보상을 받는다.","src":"기출 2024-47 | 경찰관 직무집행법 제11조의2"},{"x":"공공용물의 일반사용의 경우에는 사용료를 납부하여야 한다.","o":"공공용물의 일반사용은 무료다.","src":"기출 2024-48"},{"x":"공물의 인접주민에게는 구체적으로 공물을 사용하지 않고 있더라도 공물에 대한 고양된 일반사용권이 인정된다.","o":"구체적으로 사용하지 않는 경우에는 인정되지 않는다.","src":"기출 2024-48"},{"x":"「하천법」상 하천의 점용허가권은 대세적 효력이 있는 물권이다.","o":"대세적 효력이 있는 물권이 아니다.","src":"기출 2024-48"},{"x":"중앙관서의 장은 특별한 제한 없이 행정재산의 사용허가를 할 수 있다.","o":"용도나 목적에 장애가 되지 아니하는 범위(보존용재산은 보존목적의 수행에 필요한 범위)에서만 할 수 있다.","src":"기출 2024-48 | 국유재산법 제30조 제1항"},{"x":"국가의 회계는 통상회계와 임시회계로 구분한다.","o":"일반회계와 특별회계로 구분한다.","src":"기출 2025-47"},{"x":"보존용재산은 일반재산에 속한다.","o":"보존용재산은 행정재산에 속한다.","src":"기출 2025-50"},{"x":"공용재산이란 국가가 직접 공공용으로 사용하거나 대통령령으로 정하는 기한까지 사용하기로 결정한 재산을 말한다.","o":"그것은 공공용재산이다. 공용재산은 사무용·사업용·공무원 주거용으로 사용하는 재산이다.","src":"기출 2025-50"},{"x":"기업용재산은 「민법」 제245조에 따른 시효취득의 대상이 된다.","o":"기업용재산은 행정재산이므로 시효취득의 대상이 아니다.","src":"기출 2025-50"},{"x":"판결에 따라 취득하는 경우에도 사권(私權)이 설정된 재산은 그 사권이 소멸된 후가 아니면 국유재산으로 취득하지 못한다.","o":"판결에 따라 취득하는 경우는 예외다.","src":"기출 2025-50 | 국유재산법 제11조 제1항"}]}};
